package FSM::Support::ProcessSupervisor::Connection;

use strict;
use warnings;

use Errno qw(EAGAIN EINTR EPIPE EWOULDBLOCK);
use IO::Select;
use POSIX qw(SIGPIPE);
use Scalar::Util qw(openhandle refaddr);
use Socket qw(AF_UNIX MSG_PEEK SOCK_STREAM SOL_SOCKET SO_TYPE sockaddr_family);
use Time::HiRes qw(CLOCK_MONOTONIC clock_gettime);
use FSM::Support::ProcessSupervisor::Endpoint ();
use FSM::Support::ProcessSupervisor::Reservation ();
use FSM::Support::ProcessSupervisor::Wire ();

# Inactive, server-side mechanics only. The owner must consume each received
# frame before advancing again and supply the original invocation deadline.
# This object neither authenticates a parent nor admits or launches a command.
# Outgoing client SPAWN serialization belongs to the later client-routing leaf,
# not to these finite coordinator control/stream queues.
my $LIMIT = FSM::Support::ProcessSupervisor::Wire::limits();

sub _now { return clock_gettime(CLOCK_MONOTONIC) }
sub _error { die "private process connection: $_[0]\n" }

sub new_connection {
    _error('expected descriptor and invocation deadline') unless @_ == 2;
    my ($handle, $deadline) = @_;
    _error('expected an open Unix stream descriptor') unless ref($handle) && openhandle($handle);
    my $type = getsockopt($handle, SOL_SOCKET, SO_TYPE);
    my $address = getsockname($handle);
    _error('expected an open Unix stream descriptor') unless defined($type)
        && unpack('i', $type) == SOCK_STREAM && defined($address)
        && sockaddr_family($address) == AF_UNIX;
    _error('invalid invocation deadline') unless defined($deadline) && !ref($deadline)
        && $deadline =~ /\A[0-9]+(?:\.[0-9]+)?\z/ && $deadline > 0;
    my $state = bless {
        owner_pid => $$, handle => $handle, deadline => 0 + $deadline,
        input => '', target => 4, frame_started => undef,
        queues => {control => [], stream => []},
        queued_bytes => {control => 0, stream => 0},
        active => undef, progress_deadline => undef, closed => 0,
    }, __PACKAGE__;
    $state->{owner_identity} = refaddr($state);
    my $sealed = eval { FSM::Support::ProcessSupervisor::Endpoint::_seal_handle($handle, 1); 1 };
    $state->_fail('host_error', 'cannot seal accepted descriptor') unless $sealed;
    return $state;
}

sub _owner {
    my ($self) = @_;
    _error('invalid or copied connection handle') unless ref($self) eq __PACKAGE__
        && defined($self->{owner_identity}) && $self->{owner_identity} == refaddr($self);
    _error('inherited connection cannot be reused') unless $self->{owner_pid} == $$;
}

sub _fail {
    my ($self, $status, $diagnostic) = @_;
    $self->{failure} //= {status => $status, diagnostic => $diagnostic};
    $self->close;
    return;
}

sub failure {
    my ($self) = @_;
    _owner($self);
    return $self->{failure} ? {%{$self->{failure}}} : undef;
}

sub is_closed { _owner($_[0]); return $_[0]{closed} ? 1 : 0 }
sub handle { _owner($_[0]); return $_[0]{handle} }

sub queue {
    my ($self, $message) = @_;
    _error('expected one outgoing message') unless @_ == 2;
    _owner($self);
    return 0 if $self->{closed};
    my $frame = eval { FSM::Support::ProcessSupervisor::Wire::encode_frame('coordinator', $message) };
    if ($@) { $self->_fail('protocol_error', 'invalid outgoing coordinator frame'); return 0; }
    my $kind = $message->{type} eq 'STDOUT' || $message->{type} eq 'STDERR' ? 'stream' : 'control';
    return $self->_queue_encoded($kind, $frame);
}

# One tracked ACCEPT per original connection. This records successful local
# socket writes, not remote acknowledgement or permission to release a job.
sub queue_accept {
    my ($self, $job) = @_;
    _error('expected one ACCEPT job identity') unless @_ == 2;
    _owner($self);
    my $queued = 0;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        _error('ACCEPT publication is single-use') if $self->{accept_publication};
        return if $self->{closed};
        my $frame = eval { FSM::Support::ProcessSupervisor::Wire::encode_frame(
            'coordinator', {type => 'ACCEPT', job => $job}) };
        if ($@) { $self->_fail('protocol_error', 'invalid ACCEPT job identity'); return; }
        my $publication = $self->{accept_publication} = {
            job => $job, state => 'queued', frame_bytes => length($frame), confirmed_bytes => 0,
        };
        $queued = $self->_queue_encoded('control', $frame, $publication);
    });
    return $queued;
}

sub accept_publication {
    my ($self) = @_;
    _error('unexpected ACCEPT publication arguments') unless @_ == 1;
    _owner($self);
    my $publication = $self->{accept_publication} or return;
    return {%$publication, published => $publication->{state} eq 'written' ? 1 : 0,
        failure => $publication->{failure} ? {%{$publication->{failure}}} : undef};
}

sub _queue_encoded {
    my ($self, $kind, $frame, $publication) = @_;
    my $cap = $LIMIT->{$kind . '_queue'};
    if (length($frame) > $cap - $self->{queued_bytes}{$kind}) {
        # Stream pressure means the caller must retain its unaccepted chunk
        # and stop reading that producer. Control exhaustion is a failed link.
        $self->_fail('control_queue_full', 'control queue exhausted') if $kind eq 'control';
        return 0;
    }
    push @{$self->{queues}{$kind}}, $publication
        ? {kind => $kind, bytes => $frame, publication => $publication} : $frame;
    $self->{queued_bytes}{$kind} += length($frame);
    $self->{progress_deadline} //= _now() + $LIMIT->{delivery_seconds};
    return 1;
}

sub queued_bytes {
    my ($self) = @_;
    _owner($self);
    return {%{$self->{queued_bytes}}};
}

sub take_frame {
    my ($self) = @_;
    _owner($self);
    return delete $self->{received};
}

sub poll_delay {
    my ($self) = @_;
    _owner($self);
    return 0 if $self->{closed};
    my $deadline = $self->{deadline};
    for my $candidate (
        defined($self->{frame_started}) ? $self->{frame_started} + $LIMIT->{handshake_seconds} : (),
        defined($self->{progress_deadline}) ? $self->{progress_deadline} : (),
    ) {
        $deadline = $candidate if $candidate < $deadline;
    }
    my $remaining = $deadline - _now();
    return 0 if $remaining <= 0;
    return $remaining < $LIMIT->{idle_seconds} ? $remaining : $LIMIT->{idle_seconds};
}

sub _read_once { return sysread($_[0], ${$_[1]}, $_[2]) }
sub _write_once { return syswrite($_[0], ${$_[1]}, $_[2]) }

sub _read_ready {
    my ($self, $now) = @_;
    if ($self->{received}) {
        # Even while a completed frame is waiting for its owner, peer EOF must
        # remain observable. Peeking stores at most one byte and consumes none.
        my $peer = recv($self->{handle}, my $peek, 1, MSG_PEEK);
        if (defined($peer)) {
            $self->_fail('peer_closed', 'peer closed the connection') unless length($peek);
        }
        elsif ($! != EAGAIN && $! != EWOULDBLOCK && $! != EINTR) {
            $self->_fail('host_error', 'cannot inspect peer closure');
        }
        return;
    }
    my $needed = $self->{target} - length($self->{input});
    $needed = $LIMIT->{chunk} if $needed > $LIMIT->{chunk};
    my $read = _read_once($self->{handle}, \my $part, $needed);
    if (!defined($read)) {
        # Inspection may use only a completed empty nonblocking read as proof
        # of current quiescence. An interrupted read has no such result.
        return 1 if $! == EAGAIN || $! == EWOULDBLOCK;
        return if $! == EINTR;
        $self->_fail('host_error', 'socket read failed');
        return;
    }
    if (!$read) { $self->_fail('peer_closed', 'peer closed the connection'); return; }
    $self->{frame_started} //= $now;
    $self->{input} .= $part;
    if (length($self->{input}) == 4 && $self->{target} == 4) {
        my $admitted = eval { FSM::Support::ProcessSupervisor::Wire::payload_size($self->{input}) };
        unless (defined($admitted)) { $self->_fail('protocol_error', 'invalid frame length header'); return; }
        $self->{target} = 6;
    }
    if (length($self->{input}) == 6 && $self->{target} == 6) {
        my $size = eval { FSM::Support::ProcessSupervisor::Wire::frame_size('client', $self->{input}) };
        unless (defined($size)) { $self->_fail('protocol_error', 'invalid client frame prefix'); return; }
        $self->{target} = $size;
    }
    if (length($self->{input}) == $self->{target} && $self->{target} >= 6) {
        my $decoded = eval { FSM::Support::ProcessSupervisor::Wire::decode_frame('client', $self->{input}) };
        unless ($decoded) { $self->_fail('protocol_error', 'invalid client frame body'); return; }
        $self->{received} = $decoded;
        $self->{input} = '';
        $self->{target} = 4;
        $self->{frame_started} = undef;
    }
}

sub _write_ready {
    my ($self, $observed_now, $check) = @_;
    _owner($self);
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        # A pre-mask handler may have closed or advanced this original owner.
        return if $self->{closed};
        if ($check) {
            my ($admitted, $error);
            {
                local $@;
                eval {
                    $admitted = $check->($self);
                    _error('write admission must return a boolean') unless defined($admitted)
                        && !ref($admitted) && "$admitted" =~ /\A[01]\z/;
                    1;
                } or $error = $@;
            }
            if (defined $error) {
                # A failed callback cannot leave queued bytes eligible for an
                # unguarded retry. Preserve its exception if cleanup also fails.
                eval { $self->_fail('host_error', 'socket write admission failed'); 1 };
                die $error;
            }
            return unless $admitted;
            return if $self->{closed};
        }
        # The caller's authority check can consume time or close the owner.
        # Neither callback success nor a stale readiness sample renews a wall.
        my $now = _now();
        if ($now >= $self->{deadline}) {
            $self->_fail('timed_out', 'original invocation deadline expired'); return;
        }
        if (defined($self->{progress_deadline}) && $now >= $self->{progress_deadline}) {
            $self->_fail('write_timeout', 'queued bytes made no delivery progress'); return;
        }
        $self->_write_ready_effect($now);
    });
    return;
}

sub _write_ready_effect {
    my ($self, $now) = @_;
    unless ($self->{active}) {
        for my $kind (qw(control stream)) {
            next unless @{$self->{queues}{$kind}};
            my $frame = shift @{$self->{queues}{$kind}};
            $self->{active} = ref($frame) ? $frame : {kind => $kind, bytes => $frame};
            last;
        }
    }
    return unless $self->{active};
    my $active = $self->{active};
    my $count = length($active->{bytes});
    $count = $LIMIT->{chunk} if $count > $LIMIT->{chunk};
    my $previous = POSIX::SigAction->new;
    my $ignore = POSIX::SigAction->new('IGNORE', POSIX::SigSet->new, 0);
    unless (defined POSIX::sigaction(SIGPIPE, $ignore, $previous)) {
        $self->_fail('host_error', 'cannot scope socket SIGPIPE disposition');
        return;
    }
    my ($written, $errno, $exception);
    {
        local $@;
        eval {
            $written = _write_once($self->{handle}, \$active->{bytes}, $count);
            $errno = 0 + $!;
            1;
        } or $exception = 1;
    }
    unless (defined POSIX::sigaction(SIGPIPE, $previous)) {
        $self->_fail('host_error', 'fatal socket SIGPIPE restoration failure');
        return;
    }
    if ($exception) { $self->_fail('host_error', 'socket write raised an exception'); return; }
    unless (defined $written) {
        return if $errno == EAGAIN || $errno == EWOULDBLOCK || $errno == EINTR;
        $self->_fail($errno == EPIPE ? 'peer_closed' : 'host_error', 'socket write failed');
        return;
    }
    unless ($written > 0) { $self->_fail('host_error', 'socket write made no progress'); return; }
    # A partially written frame must finish before any other frame, including
    # newly queued control. Otherwise control priority would corrupt framing.
    substr($active->{bytes}, 0, $written, '');
    $self->{queued_bytes}{$active->{kind}} -= $written;
    if (my $publication = $active->{publication}) {
        $publication->{confirmed_bytes} += $written;
        $publication->{state} = length($active->{bytes}) ? 'writing' : 'written';
    }
    $self->{active} = undef unless length($active->{bytes});
    my $pending = $self->{queued_bytes}{control} + $self->{queued_bytes}{stream};
    $self->{progress_deadline} = $pending ? $now + $LIMIT->{delivery_seconds} : undef;
}

sub _check_deadlines {
    my ($self, $now, $frame_started) = @_;
    return 0 if $self->{closed};
    $frame_started //= $self->{frame_started};
    if ($now >= $self->{deadline}) {
        $self->_fail('timed_out', 'original invocation deadline expired');
        return 0;
    }
    if (defined($frame_started) && $now >= $frame_started + $LIMIT->{handshake_seconds}) {
        $self->_fail('framing_timeout', 'fixed partial-frame deadline expired');
        return 0;
    }
    if (defined($self->{progress_deadline}) && $now >= $self->{progress_deadline}) {
        $self->_fail('write_timeout', 'queued bytes made no delivery progress');
        return 0;
    }
    return 1;
}

# A fresh read-only pass for the original owner. This is an observation, not
# authority to execute: its caller must retain and check the matching job.
# One bounded nonblocking read/peek may retain a frame, but sends no output.
sub inspect_input {
    my ($self) = @_;
    _error('unexpected input inspection arguments') unless @_ == 1;
    _owner($self);
    my $quiet = 0;
    my $ok = eval {
        FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
            my $inspected = eval {
                _owner($self);
                my $now = _now();
                return 1 unless $self->_check_deadlines($now);
                my $frame_started = $self->{frame_started};
                my $empty = $self->_read_ready($now);
                # Completing a frame cannot erase the wall that governed its
                # last read; retain that start through the post-read check.
                return 1 unless $self->_check_deadlines(_now(), $frame_started);
                $quiet = $empty && !length($self->{input}) && !$self->{received} ? 1 : 0;
                1;
            };
            unless ($inspected) {
                my $error = $@;
                $self->_fail('host_error', 'input inspection interrupted');
                die $error;
            }
        });
        1;
    };
    unless ($ok) {
        my $error = $@;
        # Also cover mask setup/restoration or a handler after retained input.
        # A lost read return can never permit a later execution check.
        eval { $self->_fail('host_error', 'input inspection interrupted'); 1 };
        die $error;
    }
    return {state => $self->{closed} ? 'closed' : $quiet ? 'quiet' : 'pending',
        buffered_bytes => length($self->{input}), frame_ready => $self->{received} ? 1 : 0,
        failure => $self->{failure} ? {%{$self->{failure}}} : undef};
}

sub advance {
    my ($self, $check) = @_;
    _error('expected optional socket write admission')
        unless @_ == 1 || (@_ == 2 && ref($check) eq 'CODE');
    _owner($self);
    return if $self->{closed};
    my $now = _now();
    return unless $self->_check_deadlines($now);
    my $select = IO::Select->new($self->{handle});
    $self->_read_ready($now) if $select->can_read(0);
    return if $self->{closed};
    $self->_write_ready($now, $check) if $self->{progress_deadline} && $select->can_write(0);
    return;
}

sub close {
    my ($self) = @_;
    _error('unexpected close arguments') unless @_ == 1;
    _owner($self);
    return $self->{close_ok} if $self->{closed};
    $self->{closed} = 1;
    if (my $publication = $self->{accept_publication}) {
        unless ($publication->{state} eq 'written') {
            $publication->{state} = 'failed';
            $publication->{failure} //= $self->{failure} ? {%{$self->{failure}}}
                : {status => 'cancelled', diagnostic => 'connection closed before complete ACCEPT write'};
        }
    }
    $self->{close_ok} = CORE::close(delete $self->{handle}) ? 1 : 0;
    $self->{failure} //= {status => 'host_error', diagnostic => 'socket close failed'}
        unless $self->{close_ok};
    $self->{input} = '';
    delete $self->{received};
    $self->{active} = undef;
    $self->{queues} = {control => [], stream => []};
    $self->{queued_bytes} = {control => 0, stream => 0};
    return $self->{close_ok};
}

sub discard_inherited {
    my ($self) = @_;
    _error('expected inherited connection') unless @_ == 1
        && ref($self) eq __PACKAGE__ && $self->{owner_pid} != $$
        && defined($self->{owner_identity}) && $self->{owner_identity} == refaddr($self);
    CORE::close(delete $self->{handle}) if $self->{handle};
    $self->{closed} = 1;
    return;
}

1;

sources.perl/FSM/Support/ProcessSupervisor/Servi:
package FSM::Support::ProcessSupervisor::Service;

use strict;
use warnings;

use Errno qw(EAGAIN EINTR EWOULDBLOCK);
use IO::Select;
use Math::BigInt;
use Scalar::Util qw(refaddr);
use Time::HiRes qw(CLOCK_MONOTONIC clock_gettime);
use FSM::Support::ProcessSupervisor::Connection ();
use FSM::Support::ProcessSupervisor::Endpoint ();
use FSM::Support::ProcessSupervisor::Reservation ();
use FSM::Support::ProcessSupervisor::Wire ();

# Private transport admission and lifetime. A standalone service owns its endpoint;
# a shared service borrows it until the aggregate native owner retires the run.
# The trusted caller owns ledger admission, native readiness and exec release.
# Service binds a handed request to its ready job context and tracked ACCEPT;
# local publication and fresh execution admission keep the original admission
# wall until the trusted aggregate reports its original confirmed native effect.
# Service retains that report and selects the original execution lifetime; it
# neither proves the native effect nor launches a command or delivers its result.
my $LIMIT = FSM::Support::ProcessSupervisor::Wire::limits();
my $SECOND = 1_000_000_000;
my $EXECUTION_GRANT = __PACKAGE__ . '::ExecutionAdmission';

sub _error { die "private process service: $_[0]\n" }
sub _now_ns { return sprintf('%.0f', clock_gettime(CLOCK_MONOTONIC) * $SECOND) }
sub _time {
    return Math::BigInt->new(FSM::Support::ProcessSupervisor::Wire::_uint(
        $_[0], '18446744073709551615', 1));
}
sub _minimum {
    my $value = shift;
    for (@_) { $value = $_ if $_->bcmp($value) < 0; }
    return $value->copy;
}
sub _window { return $_[0]->copy->badd($LIMIT->{handshake_seconds} * $SECOND) }
sub _owner {
    my ($self) = @_;
    _error('invalid or copied service handle') unless ref($self) eq __PACKAGE__
        && defined($self->{owner_identity}) && $self->{owner_identity} == refaddr($self);
    _error('inherited service cannot be reused') unless $self->{owner_pid} == $$;
    _error('lost or substituted original service endpoint') unless ref($self->{run})
        && refaddr($self->{run}) == ($self->{run_identity} // 0);
}

sub new_service {
    _error('expected endpoint run and original deadline') unless @_ == 2;
    return _new_service(@_, 0);
}

sub new_shared_service {
    _error('expected shared endpoint run and original deadline') unless @_ == 2;
    return _new_service(@_, 1);
}

sub _new_service {
    my ($run, $deadline_ns, $shared) = @_;
    _error('expected an owned endpoint run')
        unless ref($run) eq 'FSM::Support::ProcessSupervisor::Endpoint';
    my $encoded = $run->context;
    my $context = FSM::Support::ProcessSupervisor::Wire::decode_context($encoded);
    my $deadline = _time($deadline_ns);
    _error('original deadline already expired') if $deadline->bcmp(_time(_now_ns())) <= 0;
    my $self = bless {
        owner_pid => $$, run => $run, identity => $context->{run}, deadline => $deadline,
        shared_run => $shared,
        parents => {1 => {state => 'ready', token => $context->{token},
            context => $encoded, deadline => $deadline->copy}},
        high_parent => 1, next_ticket => 1, records => {}, order => [], closed => 0,
    }, __PACKAGE__;
    $self->{owner_identity} = refaddr($self);
    $self->{run_identity} = refaddr($run);
    return $self;
}

sub context {
    _error('unexpected context arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    _error('root authority is no longer live') unless !$self->{closed} && $self->{parents}{1}
        && $self->{deadline}->bcmp(_time(_now_ns())) > 0;
    return $self->parent_context(1);
}

sub _check_parent_live {
    my ($self, $id, $record) = @_;
    _error('parent authority is no longer retained') unless !$self->{closed}
        && $self->{parents}{1} && $self->{parents}{$id}
        && refaddr($self->{parents}{$id}) == refaddr($record);
    my $now = _time(_now_ns());
    if ($now->bcmp($self->{deadline}) >= 0 || $now->bcmp($record->{deadline}) >= 0) {
        $record->{failure} //= {status => 'timed_out', diagnostic => 'original parent lifetime expired'}
            if $record->{state} eq 'preparing';
        _error('original parent lifetime expired');
    }
    my $run = $self->{run}->observation;
    _error('parent endpoint is no longer ready') unless $run->{phase} eq 'ready' && !$run->{closed};
    return;
}

sub parent_context {
    _error('expected one original parent identity') unless @_ == 2;
    my ($self, $id) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($id, '4294967295', 1);
    my $record = $self->{parents}{$id} or _error('unknown or revoked parent authority');
    _error('parent authority preparation is not complete') unless $record->{state} eq 'ready';
    $self->_check_parent_live($id, $record);
    return $record->{context};
}

sub parent_observation {
    _error('expected one retained parent identity') unless @_ == 2;
    my ($self, $id) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($id, '4294967295', 1);
    my $record = $self->{parents}{$id} or _error('unknown or revoked parent authority');
    # Preparation state is a historical fact, not current submission authority.
    # Inspecting it never exposes a token or replaces parent_context's checks.
    return {parent => 0 + $id, state => $record->{state},
        deadline_ns => $record->{deadline}->bstr,
        failure => $record->{failure} ? {%{$record->{failure}}} : undef};
}

sub register_parent {
    _error('expected job identity, original deadline and optional token admission')
        unless @_ == 3 || (@_ == 4 && ref($_[3]) eq 'CODE');
    my ($self, $id, $deadline_ns, $check) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($id, '4294967295', 1);
    my $deadline = _time($deadline_ns);
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        # Validate before spending an identity, then retain the original record
        # before entropy effects. Failed preparation consumes its bounded slot
        # until explicit revocation, and the identity can never be reused.
        _error('service is closed') if $self->{closed};
        _error('parent identity is reused or out of order') if $id <= $self->{high_parent};
        _error('live authority capacity exhausted') if keys(%{$self->{parents}}) >= $LIMIT->{jobs};
        _error('invalid parent lifetime') if $deadline->bcmp(_time(_now_ns())) <= 0
            || $deadline->bcmp($self->{deadline}) > 0 || !$self->{parents}{1};
        my $record = $self->{parents}{$id} = {state => 'preparing', deadline => $deadline};
        $self->{high_parent} = 0 + $id;
        my $ok = eval {
            $self->_check_parent_live($id, $record);
            $record->{token} = FSM::Support::ProcessSupervisor::Endpoint::new_job_token(sub {
                # Each native open/read needs current original authority. A
                # caller check can revoke it or consume time before returning.
                $self->_check_parent_live($id, $record);
                $check->($self, $id, @_) if $check;
                $self->_check_parent_live($id, $record);
            });
            $self->_check_parent_live($id, $record);
            $record->{context} = $self->{run}->context_for($id, $record->{token});
            $self->_check_parent_live($id, $record);
            $record->{state} = 'ready';
            1;
        };
        unless ($ok) {
            my $error = $@;
            $record->{state} = 'failed';
            $record->{failure} //= {status => 'host_error', diagnostic => 'parent authority preparation failed'};
            die $error;
        }
    });
    # Fresh lookup also refuses closure/expiry from a pre-return handler.
    return $self->parent_context($id);
}

sub _fail_record {
    my ($self, $record, $status, $diagnostic) = @_;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        $record->{failure} //= ($record->{io} ? $record->{io}->failure : undef)
            // {status => $status, diagnostic => $diagnostic};
        delete $record->{request};
        $record->{state} = 'closing';
        my $error;
        if ($record->{io}) {
            my $ok = eval {
                $record->{close_failed} = 1 unless $record->{io}->close;
                delete $record->{close_interrupted};
                1;
            };
            unless ($ok) { $error = $@; $record->{close_interrupted} = 1; }
        }
        # Retain the original accept handle even when Connection has removed
        # its own field before close. Never substitute a remembered FD number.
        for my $handle (@{_record_handles($record)}) {
            my $ok = eval { $record->{close_failed} = 1 unless _close_once($handle); 1 };
            unless ($ok) { $error //= $@; $record->{close_failed} = 1; }
        }
        $self->{descriptor_cleanup_failed} = 1 if $record->{close_failed};
        $record->{state} = 'closed'
            unless $record->{close_interrupted} || @{_record_handles($record)};
        die $error if defined $error;
    });
    return;
}

sub _record_handles {
    my ($record) = @_;
    my %seen;
    return [grep { defined($_) && defined(fileno($_)) && !$seen{refaddr($_)}++ }
        $record->{handle}, $record->{io} ? $record->{io}->handle : ()];
}
sub _close_once { return CORE::close($_[0]) }

sub _revoke {
    my ($self, $id, $status, $diagnostic) = @_;
    # Authority is removed before any descriptor cleanup can run.
    delete $self->{parents}{$id};
    for my $record (values %{$self->{records}}) {
        next unless (defined($record->{parent}) && $record->{parent} == $id)
            || (defined($record->{job}) && $record->{job} == $id);
        $self->_fail_record($record, $status, $diagnostic);
    }
}

sub revoke_parent {
    _error('expected one parent identity') unless @_ == 2;
    my ($self, $id) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($id, '4294967295', 1);
    if ($id == 1) {
        $self->{failure} //= {status => 'authority_revoked', diagnostic => 'root authority is no longer live'};
        $self->close;
        return;
    }
    $self->_revoke($id, 'authority_revoked', 'parent authority is no longer live');
    return;
}

sub _accept_once { return accept(${$_[0]}, $_[1]) }

sub _accept {
    my ($self, $now, $check) = @_;
    my $record;
    my $ok = eval {
        FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
            # Recheck after any pre-mask handler. Closed outcomes still occupy
            # slots; a saturated backlog receives no ticket or native effect.
            return if $self->{closed} || @{$self->{order}} >= $LIMIT->{connections};
            return unless IO::Select->new($self->{run}->listener)->can_read(0);
            if ($self->{next_ticket} > 4_294_967_295) {
                $self->{failure} //= {status => 'host_error', diagnostic => 'connection identity exhausted'};
                $self->close;
                return;
            }
            my $ticket = $self->{next_ticket}++;
            $record = {ticket => $ticket, state => 'accepting',
                wall => _minimum(_window($now), $self->{deadline})};
            $self->{records}{$ticket} = $record;
            push @{$self->{order}}, $ticket;
            if ($check) {
                my $admitted = $check->($self, $ticket);
                _error('accept admission must return a boolean') unless defined($admitted)
                    && !ref($admitted) && "$admitted" =~ /\A[01]\z/;
                unless ($admitted) { $self->_forget_empty($record); return; }
            }
            _error('accept admission is no longer live') if $self->{closed}
                || $record->{state} ne 'accepting' || !$self->{parents}{1};
            _error('original accept admission wall expired')
                if _time(_now_ns())->bcmp($record->{wall}) >= 0;
            # Publish directly into the retained record. Construction borrows
            # this handle; the record keeps custody through every close path.
            my $peer = _accept_once(\$record->{handle}, $self->{run}->listener);
            unless (defined $peer) {
                my $transient = $! == EAGAIN || $! == EWOULDBLOCK || $! == EINTR;
                if ($transient && !@{_record_handles($record)}) {
                    $self->_forget_empty($record);
                    return;
                }
                $self->{failure} //= {status => 'host_error', diagnostic => 'socket accept failed'};
                $self->close;
                return;
            }
            $record->{io} = FSM::Support::ProcessSupervisor::Connection::new_connection(
                $record->{handle}, $self->{deadline}->numify / $SECOND);
            $record->{state} = 'hello';
            $self->_fail_record($record, 'host_error', 'accepted descriptor sealing failed')
                if $record->{io}->failure;
        });
        1;
    };
    unless ($ok) {
        my $error = $@;
        $self->{failure} //= {status => 'host_error', diagnostic => 'accepted descriptor admission interrupted'};
        # Preserve the original exception if cleanup also throws. The original
        # service and raw handles remain inspectable and retryable by the owner.
        my $closed = eval { $self->close; 1 };
        $self->{cleanup_interruption} //= 'accepted descriptor cleanup interrupted' unless $closed;
        die $error;
    }
    return;
}

sub _forget_empty {
    my ($self, $record) = @_;
    _error('cannot forget a native accepted handle') if @{_record_handles($record)};
    delete $self->{records}{$record->{ticket}};
    @{$self->{order}} = grep { $_ != $record->{ticket} } @{$self->{order}};
    return;
}

sub _message {
    my ($self, $record, $message, $now) = @_;
    if ($record->{state} eq 'hello' && $message->{type} eq 'HELLO') {
        my $parent = $self->{parents}{$message->{parent}};
        unless ($message->{run} eq $self->{identity} && $parent && $parent->{state} eq 'ready'
            && $message->{token} eq $parent->{token} && $parent->{deadline}->bcmp($now) > 0) {
            $self->_fail_record($record, 'invocation_error', 'invalid or expired parent authority');
            return;
        }
        $record->{parent} = $message->{parent};
        $record->{hello_ns} = $now->copy;
        $record->{wall} = _minimum(_window($now), $parent->{deadline}, $self->{deadline});
        $record->{state} = 'spawn';
        $record->{io}->queue({type => 'READY', run => $self->{identity}, parent => $record->{parent}});
        return;
    }
    if ($record->{state} eq 'spawn' && $message->{type} eq 'SPAWN') {
        my $start = Math::BigInt->new($message->{started_ns});
        my $earliest = $record->{hello_ns}->copy->bsub($LIMIT->{handshake_seconds} * $SECOND);
        unless ($start->bcmp($earliest) >= 0 && $start->bcmp($record->{hello_ns}) <= 0
            && $start->bcmp($now) <= 0) {
            $self->_fail_record($record, 'invocation_error', 'invocation timestamp outside HELLO window');
            return;
        }
        my $parent = $self->{parents}{$record->{parent}};
        unless ($parent) {
            $self->_fail_record($record, 'authority_revoked', 'parent authority is no longer live');
            return;
        }
        my $execution = $start->copy->badd(Math::BigInt->new($message->{timeout_seconds})->bmul($SECOND));
        $record->{deadline} = _minimum($execution, $parent->{deadline}, $self->{deadline});
        $record->{wall} = _minimum($record->{wall}, $record->{deadline});
        if ($record->{wall}->bcmp($now) <= 0) {
            $self->_fail_record($record, 'timed_out', 'original invocation deadline expired');
            return;
        }
        $record->{request} = $message;
        $record->{state} = 'request';
        return;
    }
    if ($record->{state} eq 'bound' && $message->{type} eq 'CANCEL'
        && $message->{job} == $record->{job}) {
        $self->_fail_record($record, 'cancelled', 'client cancelled its admitted job');
        return;
    }
    $self->_fail_record($record, 'protocol_error', 'unexpected or repeated client message');
}

sub advance {
    _error('expected optional native accept and bound-write admission')
        unless @_ == 1 || (@_ == 2 && ref($_[1]) eq 'CODE')
            || (@_ == 3 && ref($_[1]) eq 'CODE' && ref($_[2]) eq 'CODE');
    my ($self, $check, $write_check) = @_; _owner($self);
    return if $self->{closed};
    my $now = _time(_now_ns());
    if ($now->bcmp($self->{deadline}) >= 0) {
        $self->{failure} //= {status => 'timed_out', diagnostic => 'original run deadline expired'};
        $self->close;
        return;
    }
    for my $id (keys %{$self->{parents}}) {
        $self->_revoke($id, 'timed_out', 'parent invocation deadline expired')
            if $self->{parents}{$id}{deadline}->bcmp($now) <= 0;
    }
    $self->_accept($now, $check);
    return if $self->{closed};
    # Rotate before every pass; each descriptor gets at most one bounded
    # advancement and one decoded message. There is no private waiting loop.
    push @{$self->{order}}, shift @{$self->{order}} if @{$self->{order}} > 1;
    for my $ticket (@{$self->{order}}) {
        my $record = $self->{records}{$ticket};
        next if $record->{state} eq 'closed';
        if ($record->{state} eq 'closing') {
            $self->_fail_record($record, 'host_error', 'accepted descriptor cleanup incomplete');
            next;
        }
        if ($now->bcmp(_active_wall($record)) >= 0) {
            $self->_fail_record($record, 'timed_out', _wall_diagnostic($record));
            next;
        }
        if ($record->{state} eq 'bound') {
            $record->{io}->advance(sub { $self->_write_admission($record, $_[0], $write_check) });
        }
        else { $record->{io}->advance; }
        if (my $failure = $record->{io}->failure) {
            $self->_fail_record($record, $failure->{status}, $failure->{diagnostic});
            next;
        }
        my $message = $record->{io}->take_frame;
        if ($message) {
            my $received = _time(_now_ns());
            if ($received->bcmp(_active_wall($record)) >= 0) {
                $self->_fail_record($record, 'timed_out', _wall_diagnostic($record));
                next;
            }
            $self->_message($record, $message, $received);
        }
    }
    return;
}

# The aggregate supplies a slot in its original retained peer entry BEFORE
# calling. Publish into that slot before releasing Service custody; a creator
# signal may interrupt the return but cannot strand the original snapshot.
# This transfers data only, never job admission or permission to execute.
sub transfer_request {
    _error('expected original ticket and empty retained request slot') unless @_ == 3;
    my ($self, $ticket, $target) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($ticket, '4294967295', 1);
    _request_target($target);
    my $transferred = 0;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        # A pre-mask handler may have filled the destination, closed this
        # peer or consumed its request. Never overwrite that newer state.
        _request_target($target);
        my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
        _error('ticket has no pending original request')
            unless $record->{state} eq 'request' && $record->{request};
        my $parent = $self->{parents}{$record->{parent}};
        if ($self->{closed} || !$parent) {
            $self->_fail_record($record, 'authority_revoked', 'parent authority is no longer live');
            return;
        }
        my $now = _time(_now_ns());
        if (grep { $now->bcmp($_) >= 0 }
            $record->{wall}, $record->{deadline}, $parent->{deadline}, $self->{deadline}) {
            $self->_fail_record($record, 'timed_out', 'original request admission deadline expired');
            return;
        }
        $$target = {ticket => $ticket, parent => $record->{parent},
            deadline_ns => $record->{deadline}->bstr,
            admission_deadline_ns => $record->{wall}->bstr, request => $record->{request}};
        delete $record->{request};
        $record->{state} = 'handed';
        $transferred = 1;
    });
    return $transferred;
}

sub _request_target {
    my ($target) = @_;
    # Native scalar custody only: a tied STORE is an arbitrary callback and
    # cannot provide the same assignment-before-release guarantee.
    _error('request target must be an empty untied scalar slot')
        unless ref($target) eq 'SCALAR' && !defined(tied($$target)) && !defined($$target);
    return;
}

# Retain only a transport/context association here. The caller must already
# own the actual ledger grant and ready gated job; no numeric id proves those.
sub queue_accept {
    _error('expected original ticket and ready job identity') unless @_ == 3;
    my ($self, $ticket, $job) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($_, '4294967295', 1) for $ticket, $job;
    my $queued = 0;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
        _error('ACCEPT requires one unbound handed request')
            unless $record->{state} eq 'handed' && !defined($record->{job});
        my $context = $self->{parents}{$job};
        _error('ACCEPT requires a ready original child context') unless $context
            && $context->{state} eq 'ready' && $job > $record->{parent};
        _error('job context already belongs to a request') if defined($context->{request_ticket});
        _error('job context exceeds original request lifetime')
            if $context->{deadline}->bcmp($record->{deadline}) > 0;
        # Spend the association before queue effects or a thrown return. The
        # ready context retains this ticket even after its outcome is consumed.
        $record->{job} = 0 + $job;
        $record->{execution_deadline} = _minimum($record->{deadline}, $context->{deadline});
        $record->{state} = 'bound';
        $context->{request_ticket} = 0 + $ticket;
        my $ok = eval {
            if ($self->_bound_live($record)) {
                $queued = $record->{io}->queue_accept($job);
                $self->_fail_record($record, 'host_error', 'ACCEPT queue admission failed') unless $queued;
            }
            1;
        };
        unless ($ok) {
            my $error = $@;
            eval { $self->_fail_record($record, 'host_error', 'ACCEPT queue publication interrupted'); 1 };
            die $error;
        }
    });
    return $queued;
}

sub _active_wall {
    my ($record) = @_;
    return $record->{execution_report} ? $record->{execution_deadline} : $record->{wall};
}
sub _wall_diagnostic {
    my ($record) = @_;
    return $record->{execution_report} ? 'original execution deadline expired'
        : 'fixed authentication or admission deadline expired';
}

sub _bound_live {
    my ($self, $record) = @_;
    return 0 if $record->{state} ne 'bound';
    my $parent = $self->{parents}{$record->{parent}};
    my $job = $self->{parents}{$record->{job}};
    if ($self->{closed} || !$self->{parents}{1} || !$parent || $parent->{state} ne 'ready'
        || !$job || $job->{state} ne 'ready' || !defined($job->{request_ticket})
        || $job->{request_ticket} != $record->{ticket}) {
        $self->_fail_record($record, 'authority_revoked', 'original request or job authority is no longer live');
        return 0;
    }
    my $now = _time(_now_ns());
    if (grep { $now->bcmp($_) >= 0 }
        _active_wall($record), $record->{deadline}, $parent->{deadline}, $job->{deadline}, $self->{deadline}) {
        $self->_fail_record($record, 'timed_out', $record->{execution_report}
            ? 'original execution deadline expired' : 'original ACCEPT admission deadline expired');
        return 0;
    }
    my $run = $self->{run}->observation;
    unless ($run->{phase} eq 'ready' && !$run->{closed}) {
        $self->_fail_record($record, 'host_error', 'original ACCEPT endpoint is no longer ready');
        return 0;
    }
    return 1;
}

sub _write_admission {
    my ($self, $record, $io, $check) = @_; _owner($self);
    _error('write admission requires the original retained peer')
        unless $self->{records}{$record->{ticket}}
            && refaddr($self->{records}{$record->{ticket}}) == refaddr($record)
            && refaddr($record->{io}) == refaddr($io);
    return 0 unless $self->_bound_live($record);
    # Connection has just advanced its bounded read. A complete cancellation
    # or foreign/repeated message must close this peer before another write.
    if (my $message = $io->take_frame) {
        $self->_message($record, $message, _time(_now_ns()));
        return 0;
    }
    if ($check) {
        my $admitted;
        my $ok = eval {
            $admitted = $check->($self, $record->{ticket}, $record->{job});
            _error('bound-write admission must return a boolean') unless defined($admitted)
                && !ref($admitted) && "$admitted" =~ /\A[01]\z/;
            1;
        };
        unless ($ok) {
            my $error = $@;
            eval { $self->_fail_record($record, 'host_error', 'original bound-write admission failed'); 1 };
            die $error;
        }
        # An owner check may consume the remaining wall or revoke this peer.
        return 0 unless $self->_bound_live($record);
        return $admitted;
    }
    return 1;
}

# This is transport admission only. The aggregate must call it immediately
# before its original native E attempt; historical observations grant no exec.
sub execution_admission {
    _error('expected original execution ticket and job, with optional retained grant slot')
        unless @_ == 3 || @_ == 4;
    my ($self, $ticket, $job, $target) = @_; _owner($self);
    _execution_target($target) if @_ == 4;
    FSM::Support::ProcessSupervisor::Wire::_uint($_, '4294967295', 1) for $ticket, $job;
    my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
    _error('execution admission requires the matching bound job')
        unless defined($record->{job}) && $record->{job} == $job;
    _error('execution admission already consumed') if $record->{execution_report};
    my ($started, $admitted) = (0, 0);
    my $ok = eval {
        FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
            _error('original execution peer is no longer retained')
                unless $self->{records}{$ticket}
                    && refaddr($self->{records}{$ticket}) == refaddr($record)
                    && $record->{job} == $job;
            _execution_target($target) if defined $target;
            _error('execution admission already consumed') if $record->{execution_report};
            my $check = $record->{execution_check} = {state => 'checking', checked_ns => _now_ns()};
            $started = 1;
            my $checked = eval {
                unless ($self->_bound_live($record)) { $check->{state} = 'refused'; return 1; }
                my $io = $record->{io};
                _error('execution admission lost original accepted connection')
                    unless defined($io->handle) && defined($record->{handle})
                        && refaddr($io->handle) == refaddr($record->{handle});
                my $input = $io->inspect_input;
                if (my $failure = $io->failure) {
                    $self->_fail_record($record, $failure->{status}, $failure->{diagnostic});
                    $check->{state} = 'refused'; return 1;
                }
                if ($io->is_closed) {
                    $self->_fail_record($record, 'peer_closed', 'original execution connection is closed');
                    $check->{state} = 'refused'; return 1;
                }
                # Inspection can consume the wall or observe peer cancellation.
                # Revalidate before classifying even a deferred attempt.
                unless ($self->_bound_live($record)) { $check->{state} = 'refused'; return 1; }
                if (my $message = $io->take_frame) {
                    $self->_message($record, $message, _time(_now_ns()));
                    $check->{state} = 'refused'; return 1;
                }
                if ($input->{state} ne 'quiet') {
                    $check->{state} = 'pending'; $check->{reason} = 'input'; return 1;
                }
                my $publication = $io->accept_publication;
                unless ($publication && $publication->{job} == $job) {
                    $self->_fail_record($record, 'host_error', 'execution admission lost original ACCEPT');
                    $check->{state} = 'refused'; return 1;
                }
                unless ($publication->{published} && !$publication->{failure}
                    && $publication->{confirmed_bytes} == $publication->{frame_bytes}) {
                    $check->{state} = 'pending'; $check->{reason} = 'publication'; return 1;
                }
                unless ($self->_bound_live($record)) { $check->{state} = 'refused'; return 1; }
                $check->{state} = 'admitted';
                # Keep the last positive check separately from later deferrals
                # or closure, for the aggregate's subsequent native-effect join.
                $record->{execution_admission} = {%$check};
                if (defined $target) {
                    unless ($record->{execution_grant}) {
                        my $grant = $record->{execution_grant} = bless {
                            owner_pid => $$, owner_identity => refaddr($self),
                            peer_identity => refaddr($record), ticket => $ticket, job => $job,
                            issued_ns => _now_ns(),
                        }, $EXECUTION_GRANT;
                        $grant->{identity} = refaddr($grant);
                    }
                    $$target = $record->{execution_grant};
                }
                $admitted = 1;
                1;
            };
            unless ($checked) {
                my $error = $@;
                $check->{state} = 'refused';
                eval { $self->_fail_record($record, 'host_error', 'execution admission interrupted'); 1 };
                die $error;
            }
        });
        1;
    };
    unless ($ok) {
        my $error = $@;
        eval { $self->_fail_record($record, 'host_error', 'execution admission interrupted'); 1 } if $started;
        die $error;
    }
    if ($admitted && !$self->_bound_live($record)) {
        $record->{execution_check}{state} = 'refused';
        return 0;
    }
    return $admitted;
}

sub _execution_target {
    my ($target) = @_;
    _error('execution grant target must be an empty untied scalar slot')
        unless ref($target) eq 'SCALAR' && !defined(tied($$target)) && !defined($$target);
}

sub _execution_grant_record {
    my ($self, $grant) = @_; _owner($self);
    _error('execution report requires an original admission grant')
        unless ref($grant) eq $EXECUTION_GRANT
            && ($grant->{identity} // 0) == refaddr($grant)
            && ($grant->{owner_pid} // 0) == $$
            && ($grant->{owner_identity} // 0) == refaddr($self);
    my $record = $self->{records}{$grant->{ticket}};
    _error('execution report lost original peer admission')
        unless $record && refaddr($record) == $grant->{peer_identity}
            && $record->{execution_grant} && refaddr($record->{execution_grant}) == refaddr($grant)
            && $record->{job} == $grant->{job} && $record->{execution_admission}
            && $record->{execution_admission}{state} eq 'admitted';
    return $record;
}

# The trusted aggregate calls only AFTER independently observing its original
# Pair's confirmed E write. This records that report; Service never proves or
# performs the native effect. The grant ties the report to original admission,
# including after peer closure, without turning copied observations into proof.
sub record_execution {
    _error('expected one original execution admission grant') unless @_ == 2;
    my ($self, $grant) = @_; _owner($self);
    my $record = $self->_execution_grant_record($grant);
    my $started = 0;
    my $ok = eval {
        FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
            $self->_execution_grant_record($grant);
            $started = 1;
            $record->{execution_report} //= {
                reported_ns => _now_ns(), admission_issued_ns => $grant->{issued_ns},
                deadline_ns => $record->{execution_deadline}->bstr,
            };
            # A delayed report may follow the admission wall or peer closure.
            # Record history first, then validate only a still-bound lifetime.
            $self->_bound_live($record) if $record->{state} eq 'bound';
        });
        1;
    };
    unless ($ok) {
        my $error = $@;
        eval { $self->_fail_record($record, 'host_error', 'execution report interrupted'); 1 } if $started;
        die $error;
    }
    return 1;
}

sub execution_observation {
    _error('expected one retained execution ticket') unless @_ == 2;
    my ($self, $ticket) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($ticket, '4294967295', 1);
    my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
    return unless $record->{execution_check};
    return {ticket => $record->{ticket}, parent => $record->{parent}, job => $record->{job},
        deadline_ns => $record->{deadline}->bstr, admission_deadline_ns => $record->{wall}->bstr,
        active_deadline_ns => _active_wall($record)->bstr,
        report => $record->{execution_report} ? {%{$record->{execution_report}}} : undef,
        latest => {%{$record->{execution_check}}},
        admitted => $record->{execution_admission} ? {%{$record->{execution_admission}}} : undef,
        failure => $record->{failure} ? {%{$record->{failure}}} : undef};
}

sub accept_publication {
    _error('expected one retained connection ticket') unless @_ == 2;
    my ($self, $ticket) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($ticket, '4294967295', 1);
    my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
    return unless defined($record->{job});
    # Both layers are copied historical observations, never live exec authority.
    return {ticket => $record->{ticket}, parent => $record->{parent}, job => $record->{job},
        state => $record->{state}, deadline_ns => $record->{deadline}->bstr,
        admission_deadline_ns => $record->{wall}->bstr,
        write => scalar($record->{io}->accept_publication),
        failure => $record->{failure} ? {%{$record->{failure}}} : undef};
}

sub take_request {
    _error('unexpected request arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    for my $ticket (@{$self->{order}}) {
        my $record = $self->{records}{$ticket};
        next unless $record->{state} eq 'request';
        my $now = _time(_now_ns());
        unless ($self->{parents}{$record->{parent}} && $now->bcmp($record->{wall}) < 0) {
            $self->_fail_record($record, 'timed_out', 'original request admission deadline expired');
            next;
        }
        # Taking a snapshot grants no command authority and does not renew
        # admission. Later owner integration must recheck before publication.
        $record->{state} = 'handed';
        return {ticket => $ticket, parent => $record->{parent},
            deadline_ns => $record->{deadline}->bstr, request => delete $record->{request}};
    }
    return;
}

sub retire {
    _error('expected one connection ticket') unless @_ == 2;
    my ($self, $ticket) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($ticket, '4294967295', 1);
    my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
    $self->_fail_record($record, 'cancelled', 'private owner retired the connection');
    return;
}

sub take_closed {
    _error('unexpected outcome arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    my $outcome;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        for my $ticket (@{$self->{order}}) {
            my $record = $self->{records}{$ticket};
            next unless $record->{state} eq 'closed';
            _error('closed outcome still owns native handles') if @{_record_handles($record)};
            $outcome = {ticket => $ticket, parent => $record->{parent}, %{$record->{failure}},
                defined($record->{job}) ? (job => $record->{job}) : (),
                $record->{execution_report} ? (execution => scalar $self->execution_observation($ticket)) : (),
                resources_closed => $record->{close_failed} ? 0 : 1};
            $self->_forget_empty($record);
            last;
        }
    });
    return $outcome;
}

sub tickets {
    _error('unexpected ticket inventory arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return [sort { $a <=> $b } keys %{$self->{records}}];
}
sub ticket_observation {
    _error('expected one retained connection ticket') unless @_ == 2;
    my ($self, $ticket) = @_; _owner($self);
    FSM::Support::ProcessSupervisor::Wire::_uint($ticket, '4294967295', 1);
    my $record = $self->{records}{$ticket} or _error('unknown connection ticket');
    return {ticket => $record->{ticket}, state => $record->{state}, parent => $record->{parent},
        defined($record->{job}) ? (job => $record->{job}) : (),
        wall_ns => $record->{wall}->bstr, active_deadline_ns => _active_wall($record)->bstr,
        handles => scalar @{_record_handles($record)},
        resources_closed => $record->{state} eq 'closed' && !$record->{close_failed}
            && !@{_record_handles($record)} ? 1 : 0,
        failure => $record->{failure} ? {%{$record->{failure}}} : undef};
}

sub poll_delay {
    _error('unexpected poll arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return 0 if $self->{closed};
    my $now = _time(_now_ns());
    my $wall = $self->{deadline}->copy;
    for my $parent (values %{$self->{parents}}) { $wall = _minimum($wall, $parent->{deadline}); }
    my $delay = $LIMIT->{idle_seconds};
    for my $record (values %{$self->{records}}) {
        next if $record->{state} eq 'closed';
        $wall = _minimum($wall, _active_wall($record));
        my $io_delay = $record->{io}->poll_delay;
        $delay = $io_delay if $io_delay < $delay;
    }
    my $remaining = $wall->bsub($now)->numify / $SECOND;
    return 0 if $remaining <= 0;
    return $remaining < $delay ? $remaining : $delay;
}

sub counts {
    _error('unexpected count arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return {parents => scalar keys %{$self->{parents}}, connections => scalar @{$self->{order}},
        open => scalar grep { $_->{state} ne 'closed' } values %{$self->{records}}};
}

# Include the owned or borrowed run and all accepted sockets, including handed
# requests. Closed peer outcomes retain slots but no handle. A closed shared
# service can still report its aggregate owner's live endpoint handles.
sub handles {
    _error('unexpected handles arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return [@{$self->{run}->handles}, map { @{_record_handles($self->{records}{$_})} } @{$self->{order}}];
}

sub failure {
    _error('unexpected failure arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return $self->{failure} ? {%{$self->{failure}}} : undef;
}
sub close {
    _error('unexpected close arguments') unless @_ == 1;
    my ($self) = @_; _owner($self);
    return {%{$self->{cleanup}}} if $self->{cleanup};
    my $pending;
    FSM::Support::ProcessSupervisor::Reservation::_masked_preparation(sub {
        # A handler may have completed close before this mask took effect.
        return if $self->{cleanup};
        $self->{closed} = 1;
        $self->{parents} = {};
        my $failure = $self->{failure} // {status => 'cancelled', diagnostic => 'private service closed'};
        $self->_fail_record($_, $failure->{status}, $failure->{diagnostic}) for values %{$self->{records}};
        if (grep { $_->{state} ne 'closed' } values %{$self->{records}}) {
            # A failed close can leave an actual handle alive. Keep the run
            # and original records retryable; cache only completed cleanup.
            $self->{failure} //= {status => 'cleanup_failed', diagnostic => 'accepted descriptor cleanup incomplete'};
            $pending = {ok => 0, pending => 1, endpoint_retained => 1,
                socket_removed => 0, directory_removed => 0,
                diagnostic => 'accepted descriptor cleanup incomplete'};
            return;
        }
        $self->{cleanup} = $self->{shared_run}
            ? {ok => 1, endpoint_retained => 1, socket_removed => 0, directory_removed => 0,
                diagnostic => 'shared endpoint retained by aggregate owner'}
            : $self->{run}->close;
        if ($self->{descriptor_cleanup_failed}) {
            $self->{cleanup}{ok} = 0;
            $self->{cleanup}{diagnostic} = 'accepted descriptor cleanup incomplete; ' . $self->{cleanup}{diagnostic};
        }
        $self->{failure} //= {status => 'cleanup_failed', diagnostic => 'private endpoint cleanup failed'}
            unless $self->{cleanup}{ok};
    });
    return $pending // {%{$self->{cleanup}}};
}
sub discard_inherited {
    _error('expected inherited service') unless @_ == 1
        && ref($_[0]) eq __PACKAGE__ && $_[0]{owner_pid} != $$
        && defined($_[0]{owner_identity}) && $_[0]{owner_identity} == refaddr($_[0]);
    my ($self) = @_;
    for my $record (values %{$self->{records}}) {
        $record->{io}->discard_inherited if $record->{io};
        CORE::close($record->{handle})
            if $record->{handle} && defined(fileno($record->{handle}));
    }
    $self->{run}->discard_inherited;
    $self->{parents} = {};
    $self->{records} = {};
    $self->{order} = [];
    $self->{closed} = 1;
    return;
}

1;

sources.scripts/check_claim_verification.pl:
#!/usr/bin/env perl
use strict;
use warnings;
use utf8;

use Cwd qw(abs_path);
use Encode qw(encode);
use File::Basename qw(dirname);
use File::Spec;
use Getopt::Long qw(GetOptions);
use JSON::PP;

my ($root_arg, $registry_arg, $registry_set_arg, $help);
GetOptions(
    'root=s'         => \$root_arg,
    'registry=s'     => \$registry_arg,
    'registry-set=s' => \$registry_set_arg,
    'help|h'         => \$help,
) or usage(2);
usage(0) if $help;
fail('--registry and --registry-set are mutually exclusive')
    if defined($registry_arg) && defined($registry_set_arg);

my $script = abs_path(__FILE__);
my $root = abs_path($root_arg // File::Spec->catdir(dirname($script), '..'));
my @problems;

if (!defined($root) || !-d $root) {
    fail('invalid repository root');
}

my %tracked = tracked_paths($root);
my @registry_paths;
my $registry_set_meta;
my $registry_set_path;
if (!defined $registry_arg) {
    $registry_set_path = $registry_set_arg
        // 'doctrine/claim_verification/claim_registries.jsonl';
    if (!safe_relative_path($registry_set_path)) {
        fail("registry-set path is not repository-relative and local: $registry_set_path");
    }
    ($registry_set_meta, my $paths) = read_registry_set(
        $root, \%tracked, $registry_set_path
    );
    @registry_paths = @{$paths};
} else {
    my $registry = $registry_arg;
    if (!safe_relative_path($registry)) {
        fail("registry path is not repository-relative and local: $registry");
    }
    @registry_paths = ($registry);
}

my @record_entries;
my $aggregate_shard_bytes = 0;
for my $registry (@registry_paths) {
    my $valid_registry = validate_tracked_path(
        $root, \%tracked, $registry, 'claim registry'
    );
    next if !defined $valid_registry;
    my ($records, $raw_lines) = read_registry($root, $registry);
    validate_registry_bounds($records, $raw_lines, $registry);
    validate_record_order($records, $registry);
    my $path = File::Spec->catfile($root, split m{/}, $registry);
    $aggregate_shard_bytes += -f $path ? -s $path : 0;
    for my $index (1 .. $#{$records}) {
        push @record_entries, {
            record => $records->[$index],
            where => "$registry line " . ($index + 1),
        };
    }
}

if (defined $registry_set_path) {
    validate_registry_set_aggregate(
        $registry_set_meta,
        $aggregate_shard_bytes,
        scalar(@record_entries),
        $registry_set_path,
    );
}

@record_entries = sort {
    string_value(ref($a->{record}) eq 'HASH' ? $a->{record}{claim_id} : undef)
        cmp string_value(ref($b->{record}) eq 'HASH' ? $b->{record}{claim_id} : undef)
        || $a->{where} cmp $b->{where}
} @record_entries;

my %claims;
my %source_records;
my $published = 0;
my $fixtures = 0;

for my $entry (@record_entries) {
    my $record = $entry->{record};
    my $where = $entry->{where};
    next if ref($record) ne 'HASH';

    validate_record_shape($record, $where);
    my $id = string_value($record->{claim_id});
    if ($id !~ /\A[a-z][a-z0-9]*(?:-[a-z0-9]+)*\z/) {
        problem("$where has invalid claim_id");
        next;
    }
    if (exists $claims{$id}) {
        problem("$where duplicates claim_id $id");
        next;
    }
    $claims{$id} = $record;

    my $classification = string_value($record->{classification});
    if ($classification eq 'published_claim') {
        ++$published;
    } elsif ($classification eq 'conformance_fixture') {
        ++$fixtures;
    } else {
        problem("$where has invalid classification");
    }

    validate_scalar($record->{claim}, "$where claim", 1024);
    validate_scalar($record->{owner_task}, "$where owner_task", 160);
    my $owner_task = string_value($record->{owner_task});
    problem("$where has invalid owner_task")
        if $owner_task !~ /\A[A-Z][A-Z0-9-]*(?:\.[1-9][0-9]*)*\z/;

    my $source_path = validate_tracked_path(
        $root, \%tracked, $record->{source_path}, "$where source_path"
    );
    if (defined($source_path)
        && $classification eq 'published_claim'
        && $source_path !~ /\.md\z/) {
        problem("$where published source_path must name a Markdown file");
    }
    if (defined($source_path)
        && $classification eq 'conformance_fixture'
        && $source_path !~ m{\Adoctrine/claim_verification/fixtures/[^/]+\.txt\z}) {
        problem("$where conformance source_path must name a claim-verification text fixture");
    }
    my $owner_path = validate_tracked_path(
        $root, \%tracked, $record->{owner_path}, "$where owner_path"
    );
    if (defined($owner_path)
        && $owner_path !~ m{\Adocs/tasks/(?:[^/]+)\.md\z}) {
        problem("$where owner_path must name one docs/tasks/*.md file");
    }
    if (defined($owner_path) && $owner_task ne '') {
        my $owner_text = read_relative_file($root, $owner_path, "$where owner_path");
        if (defined($owner_text)
            && index($owner_text, "- ID: `$owner_task`") < 0) {
            problem("$where owner_task $owner_task is absent from $owner_path");
        }
    }

    my %leg_specs = (
        rederive => [qw(producer_paths)],
        falsify => [qw(oracle_paths)],
        durability => [qw(producer_paths watcher_paths)],
    );
    my %leg_display;
    my %leg_paths;
    for my $leg (qw(rederive falsify durability)) {
        my ($display, $paths) = validate_leg(
            $root, \%tracked, $record->{$leg}, $leg_specs{$leg},
            "$where $leg", $owner_path
        );
        $leg_display{$leg} = $display if defined $display;
        $leg_paths{$leg} = $paths;
    }

    for my $pair ([qw(rederive falsify)], [qw(rederive durability)],
                  [qw(falsify durability)]) {
        my ($left, $right) = @{$pair};
        next if !defined($leg_display{$left}) || !defined($leg_display{$right});
        problem("$where aliases $left and $right evidence")
            if $leg_display{$left} eq $leg_display{$right};
    }
    if (same_path_set(
            $leg_paths{rederive}{producer_paths},
            $leg_paths{falsify}{oracle_paths})) {
        problem("$where aliases rederive producer_paths and falsify oracle_paths");
    }
    if (same_path_set(
            $leg_paths{rederive}{producer_paths},
            $leg_paths{durability}{watcher_paths})) {
        problem("$where aliases rederive producer_paths and durability watcher_paths");
    }

    next if !defined($source_path)
        || !defined($leg_display{rederive})
        || !defined($leg_display{falsify})
        || !defined($leg_display{durability});
    my $claim = string_value($record->{claim});
    my $expected = encode('UTF-8', marker_block(
        $id, $claim, $leg_display{rederive}, $leg_display{falsify},
        $leg_display{durability}
    ));
    $source_records{$id} = {
        path => $source_path,
        expected => $expected,
    };
}

validate_markers($root, \%tracked, \%claims, \%source_records);

if (@problems) {
    print STDERR "claim-verification: $_\n" for @problems;
    exit 1;
}

my $count = scalar @record_entries;
if (defined $registry_set_path) {
    my $shards = scalar @registry_paths;
    print "claim-verification: all bounded registry-set and record invariants hold "
        . "(shards=$shards, records=$count, published=$published, fixtures=$fixtures)\n";
} else {
    print "claim-verification: all bounded record invariants hold "
        . "(records=$count, published=$published, fixtures=$fixtures)\n";
}
exit 0;

sub usage {
    my ($status) = @_;
    print <<'USAGE';
Usage:
  scripts/check_claim_verification.pl [--root DIR]
      [--registry FILE | --registry-set FILE]

Checks FSMGen's bounded claim registry or finite registry set, exact source
markers, explicit re-derive/falsify/durability legs, tracked evidence paths,
and path locality.
USAGE
    exit $status;
}

sub fail {
    my ($message) = @_;
    print STDERR "claim-verification: $message\n";
    exit 1;
}

sub problem {
    push @problems, $_[0];
}

sub read_registry_set {
    my ($base, $tracked, $relative) = @_;
    my $valid_set = validate_tracked_path(
        $base, $tracked, $relative, 'registry set'
    );
    return ({}, []) if !defined $valid_set;
    my ($records, $lines) = read_jsonl(
        $base, $relative, 'claim registry set', 65_536
    );
    if (!@{$records} || ref($records->[0]) ne 'HASH') {
        problem("$relative must begin with registry-set metadata");
        return ({}, []);
    }

    my $meta = $records->[0];
    exact_keys(
        $meta,
        [qw(max_bytes max_record_bytes max_shards max_total_bytes
            max_total_records record_type schema_version)],
        "$relative line 1"
    );
    problem("$relative line 1 record_type must be registry_set")
        if string_value($meta->{record_type}) ne 'registry_set';
    validate_integer($meta->{schema_version}, 1, 1,
        "$relative line 1 schema_version");
    validate_registry_set_limit(
        $meta->{max_bytes}, 65_536, "$relative line 1 max_bytes"
    );
    validate_registry_set_limit(
        $meta->{max_record_bytes}, 512,
        "$relative line 1 max_record_bytes"
    );
    validate_registry_set_limit(
        $meta->{max_shards}, 64, "$relative line 1 max_shards"
    );
    validate_registry_set_limit(
        $meta->{max_total_bytes}, 4_194_304,
        "$relative line 1 max_total_bytes"
    );
    validate_registry_set_limit(
        $meta->{max_total_records}, 8_192,
        "$relative line 1 max_total_records"
    );

    my $path = File::Spec->catfile($base, split m{/}, $relative);
    my $bytes = -f $path ? -s $path : 0;
    if (positive_integer($meta->{max_bytes}) && $bytes > $meta->{max_bytes}) {
        problem("$relative registry set size $bytes exceeds max_bytes $meta->{max_bytes}");
    }
    if (positive_integer($meta->{max_record_bytes})) {
        for my $index (0 .. $#{$lines}) {
            my $line_bytes = length($lines->[$index]);
            problem("$relative line " . ($index + 1)
                . " is $line_bytes bytes (> max_record_bytes $meta->{max_record_bytes})")
                if $line_bytes > $meta->{max_record_bytes};
        }
    }

    my $entry_count = @{$records} - 1;
    if (positive_integer($meta->{max_shards})
        && $entry_count > $meta->{max_shards}) {
        problem("$relative shard count $entry_count exceeds max_shards $meta->{max_shards}");
    }
    problem("$relative must enumerate at least one registry shard")
        if $entry_count < 1;

    my $directory = dirname($relative);
    my $prefix = $directory eq '.' ? '' : "$directory/";
    my @paths;
    my %seen;
    for my $index (1 .. $#{$records}) {
        my $entry = $records->[$index];
        my $line_number = $index + 1;
        my $where = "$relative line $line_number";
        next if ref($entry) ne 'HASH';
        exact_keys(
            $entry,
            [qw(ordinal path record_type schema_version)],
            $where
        );
        problem("$where record_type must be registry_shard")
            if string_value($entry->{record_type}) ne 'registry_shard';
        validate_integer($entry->{schema_version}, 1, 1,
            "$where schema_version");
        validate_integer($entry->{ordinal}, 1, 64, "$where ordinal");
        problem("$where ordinal must equal $index")
            if positive_integer($entry->{ordinal})
                && $entry->{ordinal} != $index;

        my $expected = $index == 1
            ? "${prefix}claims.jsonl"
            : sprintf('%sclaims-%04d.jsonl', $prefix, $index);
        my $declared = string_value($entry->{path});
        problem("$where ordinal $index path must be $expected")
            if $declared ne $expected;
        my $valid = validate_tracked_path(
            $base, $tracked, $entry->{path}, "$where path"
        );
        next if !defined $valid;
        problem("$where duplicates shard path $valid") if $seen{$valid}++;
        push @paths, $valid;
    }

    my $quoted_prefix = quotemeta($prefix);
    my @tracked_shards = sort grep {
        /\A${quoted_prefix}claims(?:-[0-9]{4})?\.jsonl\z/
    } keys %{$tracked};
    my @declared_shards = sort @paths;
    problem("$relative tracked shard census does not match manifest entries")
        if join("\0", @tracked_shards) ne join("\0", @declared_shards);

    return ($meta, \@paths);
}

sub validate_registry_set_limit {
    my ($value, $hard_maximum, $where) = @_;
    problem("$where must be an integer in 1..$hard_maximum")
        if !positive_integer($value) || $value > $hard_maximum;
}

sub validate_registry_set_aggregate {
    my ($meta, $bytes, $record_count, $relative) = @_;
    return if ref($meta) ne 'HASH';
    if (positive_integer($meta->{max_total_bytes})
        && $bytes > $meta->{max_total_bytes}) {
        problem("$relative aggregate shard size $bytes exceeds "
            . "max_total_bytes $meta->{max_total_bytes}");
    }
    if (positive_integer($meta->{max_total_records})
        && $record_count > $meta->{max_total_records}) {
        problem("$relative aggregate record count $record_count exceeds "
            . "max_total_records $meta->{max_total_records}");
    }
}

sub read_registry {
    my ($base, $relative) = @_;
    return read_jsonl($base, $relative, 'claim registry', 65_536);
}

sub read_jsonl {
    my ($base, $relative, $label, $hard_maximum) = @_;
    my $path = File::Spec->catfile($base, split m{/}, $relative);
    my @stat = lstat $path;
    if (@stat && defined($hard_maximum) && $stat[7] > $hard_maximum) {
        problem("$relative $label size $stat[7] exceeds hard byte limit $hard_maximum");
        return ([], []);
    }
    my $raw = read_relative_file($base, $relative, $label);
    return ([], []) if !defined $raw;
    problem("$relative must end with exactly one newline")
        if $raw eq '' || $raw !~ /\n\z/ || $raw =~ /\n\n\z/;
    my @lines = split /\n/, $raw, -1;
    pop @lines if @lines && $lines[-1] eq '';
    my @records;
    my $json = JSON::PP->new->canonical(1)->utf8(1);
    for my $index (0 .. $#lines) {
        my $line_number = $index + 1;
        my $line = $lines[$index];
        if ($line eq '') {
            problem("$relative line $line_number is blank");
            push @records, undef;
            next;
        }
        my $record = eval { $json->decode($line) };
        if ($@ || ref($record) ne 'HASH') {
            problem("$relative line $line_number is not a JSON object");
            push @records, undef;
            next;
        }
        my $canonical = $json->encode($record);
        problem("$relative line $line_number is not canonical JSON")
            if $canonical ne $line;
        push @records, $record;
    }
    return (\@records, \@lines);
}

sub validate_registry_bounds {
    my ($records, $lines, $relative) = @_;
    if (!@{$records} || ref($records->[0]) ne 'HASH') {
        problem("$relative must begin with registry metadata");
        return;
    }
    my $meta = $records->[0];
    exact_keys(
        $meta,
        [qw(max_bytes max_record_bytes max_records record_type schema_version)],
        "$relative line 1"
    );
    problem("$relative line 1 record_type must be registry")
        if string_value($meta->{record_type}) ne 'registry';
    validate_integer($meta->{schema_version}, 1, 1,
        "$relative line 1 schema_version");
    validate_integer($meta->{max_records}, 1, 256,
        "$relative line 1 max_records");
    validate_integer($meta->{max_bytes}, 1, 65_536,
        "$relative line 1 max_bytes");
    validate_integer($meta->{max_record_bytes}, 1, 4096,
        "$relative line 1 max_record_bytes");

    my $path = File::Spec->catfile($root, split m{/}, $relative);
    my $bytes = -f $path ? -s $path : 0;
    if (positive_integer($meta->{max_bytes}) && $bytes > $meta->{max_bytes}) {
        problem("$relative size $bytes exceeds max_bytes $meta->{max_bytes}");
    }
    my $record_count = @{$records} - 1;
    if (positive_integer($meta->{max_records})
        && $record_count > $meta->{max_records}) {
        problem("$relative record count $record_count exceeds max_records $meta->{max_records}");
    }
    if (positive_integer($meta->{max_record_bytes})) {
        for my $index (0 .. $#{$lines}) {
            my $line_bytes = length($lines->[$index]);
            problem("$relative line " . ($index + 1)
                . " is $line_bytes bytes (> max_record_bytes $meta->{max_record_bytes})")
                if $line_bytes > $meta->{max_record_bytes};
        }
    }
}

sub validate_record_shape {
    my ($record, $where) = @_;
    exact_keys(
        $record,
        [qw(classification claim claim_id durability falsify owner_path
            owner_task record_type rederive schema_version source_path)],
        $where
    );
    problem("$where record_type must be claim")
        if string_value($record->{record_type}) ne 'claim';
    validate_integer($record->{schema_version}, 1, 1,
        "$where schema_version");
}

sub validate_leg {
    my ($base, $tracked, $leg, $path_keys, $where, $owner_path) = @_;
    if (ref($leg) ne 'HASH') {
        problem("$where must be an object");
        return (undef, {});
    }
    exact_keys(
        $leg,
        [sort qw(evidence gap_owner gap_reason status), @{$path_keys}],
        $where
    );
    my $status = string_value($leg->{status});
    problem("$where status must be available or missing")
        if $status ne 'available' && $status ne 'missing';

    my %paths;
    for my $path_key (@{$path_keys}) {
        $paths{$path_key} = validate_path_list(
            $base, $tracked, $leg->{$path_key}, "$where $path_key"
        );
    }

    if ($status eq 'available') {
        validate_scalar($leg->{evidence}, "$where evidence", 768);
        problem("$where gap_owner must be null while available")
            if defined $leg->{gap_owner};
        problem("$where gap_reason must be null while available")
            if defined $leg->{gap_reason};
        for my $path_key (@{$path_keys}) {
            problem("$where $path_key must name at least one tracked path while available")
                if !@{$paths{$path_key}};
        }
        return (string_value($leg->{evidence}), \%paths);
    }

    if ($status eq 'missing') {
        problem("$where evidence must be null while missing")
            if defined $leg->{evidence};
        validate_scalar($leg->{gap_owner}, "$where gap_owner", 160);
        validate_scalar($leg->{gap_reason}, "$where gap_reason", 512);
        my $gap_owner = string_value($leg->{gap_owner});
        problem("$where gap_owner has invalid task-tree node syntax")
            if $gap_owner !~ /\A[A-Z][A-Z0-9-]*(?:\.[1-9][0-9]*)*\z/;
        if (defined($owner_path) && $gap_owner ne '') {
            my $owner_text = read_relative_file($base, $owner_path, "$where owner_path");
            problem("$where gap_owner $gap_owner is absent from $owner_path")
                if defined($owner_text)
                    && index($owner_text, "- ID: `$gap_owner`") < 0;
        }
        for my $path_key (@{$path_keys}) {
            problem("$where $path_key must be empty while missing")
                if @{$paths{$path_key}};
        }
        return (
            'MISSING - ' . string_value($leg->{gap_reason})
                . ' (owner: ' . $gap_owner . ')',
            \%paths
        );
    }
    return (undef, \%paths);
}

sub validate_path_list {
    my ($base, $tracked, $value, $where) = @_;
    if (ref($value) ne 'ARRAY') {
        problem("$where must be an array");
        return [];
    }
    problem("$where has more than 16 entries") if @{$value} > 16;
    my @valid;
    my %seen;
    for my $index (0 .. $#{$value}) {
        my $path = validate_tracked_path(
            $base, $tracked, $value->[$index], "$where entry " . ($index + 1)
        );
        next if !defined $path;
        problem("$where duplicates $path") if $seen{$path}++;
        push @valid, $path;
    }
    my @sorted = sort @valid;
    problem("$where must be lexically sorted")
        if join("\0", @valid) ne join("\0", @sorted);
    return \@valid;
}

sub validate_tracked_path {
    my ($base, $tracked, $value, $where) = @_;
    if (ref($value) || !defined($value) || !safe_relative_path($value)) {
        problem("$where is not a repository-relative local path");
        return undef;
    }
    if (!$tracked->{$value}) {
        problem("$where is not tracked: $value");
        return undef;
    }
    my $path = File::Spec->catfile($base, split m{/}, $value);
    if (-l $path || !-f $path) {
        problem("$where is not a regular non-symlink file: $value");
        return undef;
    }
    my @root_stat = stat $base;
    my @path_stat = lstat $path;
    if (!@root_stat || !@path_stat || $path_stat[0] != $root_stat[0]) {
        problem("$where is not on the repository filesystem volume: $value");
        return undef;
    }
    if ($path_stat[4] != $root_stat[4]) {
        problem("$where is not owned by the repository owner: $value");
        return undef;
    }
    my $resolved = abs_path($path);
    if (!defined($resolved) || index($resolved, "$base/") != 0) {
        problem("$where resolves outside the repository: $value");
        return undef;
    }
    return $value;
}

sub validate_markers {
    my ($base, $tracked, $claims_by_id, $records_by_id) = @_;
    my %begins;
    my %ends;
    my %texts;
    for my $path (sort grep {
            /\.md\z/
                || m{\Adoctrine/claim_verification/fixtures/[^/]+\.txt\z}
        } keys %{$tracked}) {
        my $text = read_relative_file($base, $path, "tracked claim source $path");
        next if !defined($text)
            || index($text, '<!-- CLAIM-VERIFICATION:') < 0;
        $texts{$path} = $text;
        for my $line (split /\n/, $text, -1) {
            if (index($line, '<!-- CLAIM-VERIFICATION:BEGIN') >= 0) {
                if ($line =~ /\A<!-- CLAIM-VERIFICATION:BEGIN ([a-z][a-z0-9]*(?:-[a-z0-9]+)*) -->\z/) {
                    push @{$begins{$1}}, $path;
                } else {
                    problem("$path has malformed claim-verification BEGIN marker");
                }
            }
            if (index($line, '<!-- CLAIM-VERIFICATION:END') >= 0) {
                if ($line =~ /\A<!-- CLAIM-VERIFICATION:END ([a-z][a-z0-9]*(?:-[a-z0-9]+)*) -->\z/) {
                    push @{$ends{$1}}, $path;
                } else {
                    problem("$path has malformed claim-verification END marker");
                }
            }
        }
    }

    my %all_ids = map { $_ => 1 } (keys %begins, keys %ends, keys %{$records_by_id});
    for my $id (sort keys %all_ids) {
        my @begin_paths = @{$begins{$id} // []};
        my @end_paths = @{$ends{$id} // []};
        if (!$claims_by_id->{$id}) {
            problem("claim marker $id is not declared in the registry");
            next;
        }
        problem("claim $id must have exactly one BEGIN marker")
            if @begin_paths != 1;
        problem("claim $id must have exactly one END marker")
            if @end_paths != 1;
        my $record = $records_by_id->{$id};
        next if !$record;
        my $path = $record->{path};
        problem("claim $id BEGIN marker is not in declared source_path $path")
            if @begin_paths == 1 && $begin_paths[0] ne $path;
        problem("claim $id END marker is not in declared source_path $path")
            if @end_paths == 1 && $end_paths[0] ne $path;
        my $text = exists($texts{$path})
            ? $texts{$path}
            : read_relative_file($base, $path, "claim $id source");
        next if !defined $text;
        my $expected = $record->{expected};
        my $matches = () = $text =~ /\Q$expected\E/g;
        problem("claim $id source does not contain its exact registered record block")
            if $matches != 1;
    }
}

sub validate_record_order {
    my ($records, $relative) = @_;
    my @ids = map {
        ref($_) eq 'HASH' ? string_value($_->{claim_id}) : ''
    } @{$records}[1 .. $#{$records}];
    return if !@ids;
    my @sorted = sort @ids;
    problem("$relative claim records must be sorted by claim_id")
        if join("\0", @ids) ne join("\0", @sorted);
}

sub marker_block {
    my ($id, $claim, $rederive, $falsify, $durability) = @_;
    return "<!-- CLAIM-VERIFICATION:BEGIN $id -->\n"
        . "- Claim: $claim\n"
        . "- Re-derive: $rederive\n"
        . "- Falsify: $falsify\n"
        . "- Durability: $durability\n"
        . "<!-- CLAIM-VERIFICATION:END $id -->";
}

sub same_path_set {
    my ($left, $right) = @_;
    return 0 if ref($left) ne 'ARRAY' || ref($right) ne 'ARRAY';
    return 0 if !@{$left} || !@{$right};
    return join("\0", @{$left}) eq join("\0", @{$right});
}

sub tracked_paths {
    my ($base) = @_;
    my %paths;
    open my $git, '-|', 'git', '-C', $base, 'ls-files', '-z'
        or fail('cannot execute git ls-files');
    local $/ = "\0";
    while (my $path = <$git>) {
        chop $path;
        $paths{$path} = 1 if $path ne '';
    }
    close $git or fail('git ls-files failed');
    return %paths;
}

sub read_relative_file {
    my ($base, $relative, $label) = @_;
    if (!safe_relative_path($relative)) {
        problem("$label path is not repository-relative and local");
        return undef;
    }
    my $path = File::Spec->catfile($base, split m{/}, $relative);
    open my $fh, '<:raw', $path or do {
        problem("cannot read $label: $relative: $!");
        return undef;
    };
    local $/;
    my $text = <$fh>;
    close $fh or problem("cannot close $label: $relative: $!");
    return $text;
}

sub safe_relative_path {
    my ($path) = @_;
    return 0 if ref($path) || !defined($path) || $path eq '';
    return 0 if File::Spec->file_name_is_absolute($path);
    return 0 if $path =~ /[\\\0\r\n]/ || $path =~ m{\A/|/\z|//};
    my @parts = split m{/}, $path, -1;
    return 0 if grep { $_ eq '' || $_ eq '.' || $_ eq '..' } @parts;
    return 1;
}

sub validate_scalar {
    my ($value, $where, $maximum) = @_;
    if (ref($value) || !defined($value) || $value eq ''
        || $value =~ /[\0\r\n]/ || $value =~ /\A\s|\s\z/
        || length(encode('UTF-8', $value)) > $maximum) {
        problem("$where must be a nonempty single-line scalar <= $maximum bytes");
    }
}

sub validate_integer {
    my ($value, $minimum, $maximum, $where) = @_;
    if (!positive_integer($value) || $value < $minimum || $value > $maximum) {
        problem("$where must be an integer from $minimum through $maximum");
    }
}

sub positive_integer {
    my ($value) = @_;
    return 0 if !defined($value) || ref($value);
    my $encoded = JSON::PP->new->allow_nonref->encode($value);
    return $encoded =~ /\A[1-9][0-9]*\z/;
}

sub exact_keys {
    my ($object, $required, $where) = @_;
    return if ref($object) ne 'HASH';
    my %allowed = map { $_ => 1 } @{$required};
    for my $key (@{$required}) {
        problem("$where is missing required key $key") if !exists $object->{$key};
    }
    for my $key (sort keys %{$object}) {
        problem("$where has unknown key $key") if !$allowed{$key};
    }
}

sub string_value {
    my ($value) = @_;
    return '' if !defined($value) || ref($value);
    return "$value";
}

sources.scripts/check_task_tree_integrity.pl:
#!/usr/bin/env perl
use strict;
use warnings;

use Cwd qw(abs_path);
use Digest::SHA qw(sha256_hex);
use File::Basename qw(basename dirname);
use File::Spec;
use Getopt::Long qw(GetOptions);
use IPC::Cmd qw(run);
use JSON::PP;

my $root;
my $help;
GetOptions(
    'root=s' => \$root,
    'help|h' => \$help,
) or usage(2);
usage(0) if $help;

$root //= File::Spec->catdir(dirname(__FILE__), '..');
$root = abs_path($root);
fail("repository root does not exist") if !defined $root || !-d $root;

my $index_relative = 'docs/TASK_TREE.md';
my $index_path = local_path($index_relative);
my $index = read_file($index_path, $index_relative);

my @active_trees;
my %seen_index_tree;
my $active_index_section =
    extract_section($index, 'Active Task Trees') // $index;
for my $line (split /\n/, $active_index_section) {
    next if $line !~ /^\|\s*`([^`]+)`\s*\|\s*`active`\s*\|/;
    my $tree_id = $1;
    my ($task_path) = $line =~ m{\((docs/tasks/[^)]+\.md)\)};
    fail("$index_relative: active tree $tree_id has no docs/tasks/*.md link")
        if !defined $task_path;
    fail("$index_relative: active tree $tree_id is listed more than once")
        if $seen_index_tree{$tree_id}++;
    fail("$index_relative: active tree $tree_id uses unsafe task path $task_path")
        if !safe_relative_path($task_path);
    push @active_trees, [$tree_id, $task_path];
}

my %valid_status = map { $_ => 1 } qw(
    proposed active pending in_progress blocked done deferred superseded
);
my %terminal_status = map { $_ => 1 } qw(done deferred superseded);
my @errors;
my $total_nodes = 0;
my $total_segments = 0;
my $total_compact_terminals = 0;
my $total_index_archives = 0;
my $total_migrations = 0;
my $total_acceptance_histories = 0;
my $max_live_narrative_bytes = 4096;
my $retention_registry_relative =
    'doctrine/live_document_size/version_retention_contracts.jsonl';
my %retention_contracts;
my $retention_contracts_loaded = 0;

my @index_archive_fields =
    $index =~ /^- Completed-history manifest: `([^`]+)`\s*$/mg;
if (@index_archive_fields > 1) {
    push @errors,
        "$index_relative: must have at most one Completed-history manifest field";
}
elsif (@index_archive_fields == 1) {
    $total_index_archives = load_index_archive_manifest(
        manifest => $index_archive_fields[0],
        index    => $index,
    );
}

for my $entry (@active_trees) {
    my ($tree_id, $task_relative) = @{$entry};
    my $task_path = local_path($task_relative);
    if (!-f $task_path) {
        push @errors, "$task_relative: active task file is missing";
        next;
    }

    my $task = read_file($task_path, $task_relative);
    my $section = extract_section($task, 'Task Tree');
    if (!defined $section) {
        push @errors, "$task_relative: missing ## Task Tree section";
        next;
    }

    my @live_nodes = parse_nodes($section, $task_relative, 'live');
    if (!@live_nodes) {
        push @errors, "$task_relative: ## Task Tree contains no nodes";
        next;
    }

    my @manifest_fields =
        $task =~ /^- Segment manifest: `([^`]+)`\s*$/mg;
    if (@manifest_fields > 1) {
        push @errors, "$task_relative: must have at most one Segment manifest field";
    }

    my (@segment_nodes, @segment_paths);
    if (@manifest_fields == 1) {
        my ($nodes, $segments, $paths) = load_segment_manifest(
            tree_id       => $tree_id,
            task_relative => $task_relative,
            manifest      => $manifest_fields[0],
        );
        @segment_nodes = @{$nodes};
        @segment_paths = @{$paths};
        $total_segments += $segments;
    }

    my @migration_fields =
        $task =~ /^- Migration manifest: `([^`]+)`\s*$/mg;
    if (@migration_fields > 1) {
        push @errors, "$task_relative: must have at most one Migration manifest field";
    }
    elsif (@migration_fields == 1) {
        $total_migrations += load_migration_manifest(
            tree_id          => $tree_id,
            task_relative    => $task_relative,
            task_raw         => $task,
            manifest         => $migration_fields[0],
            segment_manifest => $manifest_fields[0],
            segment_nodes    => \@segment_nodes,
            segment_paths    => \@segment_paths,
        );
    }

    my @acceptance_history_fields =
        $task =~ /^- Acceptance history manifest: `([^`]+)`\s*$/mg;
    if (@acceptance_history_fields > 1) {
        push @errors,
            "$task_relative: must have at most one Acceptance history manifest field";
    }
    elsif (@acceptance_history_fields == 1) {
        $total_acceptance_histories += load_acceptance_history_manifest(
            tree_id       => $tree_id,
            task_relative => $task_relative,
            task_raw      => $task,
            manifest      => $acceptance_history_fields[0],
        );
    }

    my @nodes = (@live_nodes, @segment_nodes);
    $total_nodes += scalar @nodes;
    validate_tree(
        tree_id       => $tree_id,
        task_relative => $task_relative,
        live_nodes    => \@live_nodes,
        nodes         => \@nodes,
    );
}

if (@errors) {
    print STDERR "[task-tree-integrity] FAIL: $_\n" for @errors;
    print STDERR "[task-tree-integrity] active task-tree invariants failed\n";
    exit 1;
}

printf "[task-tree-integrity] all active task-tree invariants hold "
    . "(trees=%d, nodes=%d, segments=%d, compact_terminals=%d, "
    . "index_archives=%d, migrations=%d, acceptance_histories=%d)\n",
    scalar(@active_trees), $total_nodes, $total_segments,
    $total_compact_terminals, $total_index_archives, $total_migrations,
    $total_acceptance_histories;
exit 0;

sub load_index_archive_manifest {
    my (%args) = @_;
    my $manifest_relative = $args{manifest};
    my $current_index = $args{index};

    if (!safe_relative_path($manifest_relative)
        || $manifest_relative !~ /\.jsonl\z/) {
        push @errors,
            "$index_relative: unsafe or non-JSONL completed-history manifest "
                . $manifest_relative;
        return 0;
    }
    my $manifest_path = checked_local_file(
        $manifest_relative, "$index_relative: completed-history manifest"
    );
    return 0 if !defined $manifest_path;

    my $raw = read_file($manifest_path, $manifest_relative);
    my @records = decode_jsonl($raw, $manifest_relative);
    return 0 if !@records;

    my $registry = shift @records;
    check_keys(
        $registry,
        [qw(record_type schema_version max_records max_bytes)],
        [],
        "$manifest_relative: registry record",
    );
    check_equal($registry->{record_type}, 'registry',
        "$manifest_relative: registry record_type");
    check_integer($registry->{schema_version}, 1, 1,
        "$manifest_relative: registry schema_version");
    check_integer($registry->{max_records}, 1, undef,
        "$manifest_relative: registry max_records");
    check_integer($registry->{max_bytes}, 1, undef,
        "$manifest_relative: registry max_bytes");
    if (is_positive_integer($registry->{max_records})
        && @records > $registry->{max_records}) {
        push @errors,
            "$manifest_relative: archive record count " . scalar(@records)
                . " exceeds max_records $registry->{max_records}";
    }
    if (is_positive_integer($registry->{max_bytes})
        && length($raw) > $registry->{max_bytes}) {
        push @errors,
            "$manifest_relative: size " . length($raw)
                . " exceeds max_bytes $registry->{max_bytes}";
    }
    if (!@records) {
        push @errors,
            "$manifest_relative: contains no completed-history archive records";
        return 0;
    }

    my %seen_archive_id;
    my $record_number = 1;
    for my $record (@records) {
        $record_number++;
        my $where = "$manifest_relative: record $record_number";
        check_keys(
            $record,
            [qw(record_type schema_version archive_id revision path sha256
                lines bytes terminal_rows unique_tree_ids statuses
                current_pointer sealed_on retention_contract)],
            [],
            $where,
        );
        check_equal($record->{record_type}, 'version_object',
            "$where record_type");
        check_integer($record->{schema_version}, 1, 1,
            "$where schema_version");

        my $archive_id = $record->{archive_id};
        if (!defined $archive_id || ref $archive_id
            || $archive_id !~ /\A[a-z][a-z0-9_.-]*\z/) {
            push @errors, "$where has invalid archive_id";
        }
        elsif ($seen_archive_id{$archive_id}++) {
            push @errors, "$where duplicates archive_id $archive_id";
        }

        my $revision = $record->{revision};
        if (!defined $revision || ref $revision
            || $revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/) {
            push @errors, "$where has invalid exact revision";
            next;
        }
        my $path = $record->{path};
        my $current_pointer = $record->{current_pointer};
        for my $path_field (
            ['path', $path], ['current_pointer', $current_pointer]
        ) {
            my ($name, $value) = @{$path_field};
            push @errors, "$where has unsafe $name"
                if !defined $value || ref $value
                    || !safe_relative_path($value) || $value !~ /\.md\z/;
        }
        next if !defined $path || ref $path || !safe_relative_path($path);
        if ($path ne $index_relative) {
            push @errors, "$where path must identify $index_relative";
        }
        if (defined $current_pointer && !ref $current_pointer
            && $current_pointer ne $index_relative) {
            push @errors,
                "$where current_pointer must identify $index_relative";
        }

        my $digest = $record->{sha256};
        push @errors, "$where has invalid sha256"
            if !defined $digest || ref $digest
                || $digest !~ /\A[0-9a-f]{64}\z/;
        for my $field (qw(lines bytes terminal_rows unique_tree_ids)) {
            check_integer($record->{$field}, 1, undef, "$where $field");
        }
        my $statuses = $record->{statuses};
        if (ref($statuses) ne 'ARRAY'
            || join(',', sort @{$statuses}) ne 'deferred,done,superseded') {
            push @errors,
                "$where statuses must be exactly done, deferred, superseded";
        }
        my $sealed_on = $record->{sealed_on};
        push @errors, "$where has invalid sealed_on date"
            if !defined $sealed_on || ref $sealed_on
                || $sealed_on !~ /\A[0-9]{4}-[0-9]{2}-[0-9]{2}\z/;

        my $source = retrieve_version_object(
            $revision, $path, "$where completed-history source",
            $record->{retention_contract},
        );
        next if !defined $source;
        if (defined $digest && !ref $digest
            && $digest =~ /\A[0-9a-f]{64}\z/
            && sha256_hex($source) ne $digest) {
            push @errors, "$where completed-history digest mismatch";
        }
        if (is_positive_integer($record->{lines})
            && line_count($source) != $record->{lines}) {
            push @errors,
                "$where completed-history line count $record->{lines} does not "
                    . "match retrieved count " . line_count($source);
        }
        if (is_positive_integer($record->{bytes})
            && length($source) != $record->{bytes}) {
            push @errors,
                "$where completed-history byte count $record->{bytes} does not "
                    . "match retrieved count " . length($source);
        }

        my @terminal_rows = terminal_index_rows($source, $where);
        my %tree_ids;
        for my $row (@terminal_rows) {
            if ($tree_ids{$row->{tree_id}}++) {
                push @errors,
                    "$where completed-history duplicates tree ID $row->{tree_id}";
            }
        }
        if (is_positive_integer($record->{terminal_rows})
            && @terminal_rows != $record->{terminal_rows}) {
            push @errors,
                "$where terminal_rows $record->{terminal_rows} does not match "
                    . scalar(@terminal_rows) . " retrieved rows";
        }
        if (is_positive_integer($record->{unique_tree_ids})
            && scalar(keys %tree_ids) != $record->{unique_tree_ids}) {
            push @errors,
                "$where unique_tree_ids $record->{unique_tree_ids} does not match "
                    . scalar(keys %tree_ids) . " retrieved IDs";
        }

        my ($ok, undef, undef, $stdout, $stderr) = run(
            command => [
                'git', '-C', $root, 'ls-tree', '-r', '--name-only',
                $revision, '--', 'docs/tasks'
            ],
        );
        if (!$ok) {
            my $detail = join('', @{$stderr || []});
            $detail =~ s/\s+/ /g;
            push @errors,
                "$where cannot enumerate exact task files"
                    . ($detail ne '' ? " ($detail)" : '');
        }
        else {
            my %source_paths = map { $_ => 1 }
                grep { $_ ne '' } split /\n/, join('', @{$stdout || []});
            for my $row (@terminal_rows) {
                push @errors,
                    "$where archived tree $row->{tree_id} cannot retrieve "
                        . "$revision:$row->{task_path}"
                    if !$source_paths{$row->{task_path}};
                checked_local_file(
                    $row->{task_path},
                    "$where current task $row->{tree_id}",
                );
            }
        }
    }

    validate_live_index_views($current_index, $index_relative);
    return scalar @records;
}

sub terminal_index_rows {
    my ($contents, $where) = @_;
    my @rows;
    for my $heading ('Active Task Trees', 'Completed Task Trees') {
        my $section = extract_section($contents, $heading);
        if (!defined $section) {
            push @errors, "$where source is missing ## $heading";
            next;
        }
        for my $line (split /\n/, $section) {
            next if $line !~ /^\|\s*`([^`]+)`\s*\|\s*`
                (done|deferred|superseded)`\s*\|/x;
            my ($tree_id, $status) = ($1, $2);
            my ($task_path) =
                $line =~ m{\((docs/tasks/[^)]+\.md)\)\s*\|\s*\z};
            if (!defined $task_path || !safe_relative_path($task_path)) {
                push @errors,
                    "$where archived tree $tree_id has unsafe or missing task link";
                next;
            }
            push @rows, {
                tree_id => $tree_id,
                status => $status,
                task_path => $task_path,
            };
        }
    }
    return @rows;
}

sub validate_live_index_views {
    my ($contents, $where) = @_;
    for my $view (
        ['Active Task Trees', 'active'],
        ['Proposed Task Trees', 'proposed'],
    ) {
        my ($heading, $expected) = @{$view};
        my $section = extract_section($contents, $heading);
        if (!defined $section) {
            push @errors, "$where is missing ## $heading";
            next;
        }
        for my $line (split /\n/, $section) {
            next if $line !~ /^\|\s*`([^`]+)`\s*\|\s*`([^`]+)`\s*\|/;
            my ($tree_id, $status) = ($1, $2);
            push @errors,
                "$where $heading row $tree_id has status $status, expected $expected"
                if $status ne $expected;
        }
    }
    my $completed = extract_section($contents, 'Completed Task Trees');
    if (!defined $completed) {
        push @errors, "$where is missing ## Completed Task Trees";
    }
    elsif ($completed =~ /^\|\s*`([^`]+)`\s*\|/m) {
        push @errors,
            "$where Completed Task Trees retains live row $1 instead of query-first history";
    }
}

sub load_segment_manifest {
    my (%args) = @_;
    my $tree_id = $args{tree_id};
    my $task_relative = $args{task_relative};
    my $manifest_relative = $args{manifest};

    if (!safe_relative_path($manifest_relative)
        || $manifest_relative !~ /\.jsonl\z/) {
        push @errors,
            "$task_relative: unsafe or non-JSONL segment manifest $manifest_relative";
        return ([], 0, []);
    }
    my $manifest_path = checked_local_file(
        $manifest_relative, "$task_relative: segment manifest"
    );
    return ([], 0, []) if !defined $manifest_path;

    my $raw = read_file($manifest_path, $manifest_relative);
    my @records = decode_jsonl($raw, $manifest_relative);
    return ([], 0, []) if !@records;

    my $registry = shift @records;
    check_keys(
        $registry,
        [qw(record_type schema_version tree_id max_records max_bytes
            max_segment_nodes max_segment_lines max_segment_bytes
            max_total_nodes max_total_lines max_total_bytes)],
        [],
        "$manifest_relative: registry record",
    );
    check_equal($registry->{record_type}, 'registry',
        "$manifest_relative: registry record_type");
    check_integer($registry->{schema_version}, 1, 1,
        "$manifest_relative: registry schema_version");
    check_equal($registry->{tree_id}, $tree_id,
        "$manifest_relative: registry tree_id");
    check_integer($registry->{max_records}, 1, undef,
        "$manifest_relative: registry max_records");
    check_integer($registry->{max_bytes}, 1, undef,
        "$manifest_relative: registry max_bytes");
    for my $dimension (qw(nodes lines bytes)) {
        check_integer(
            $registry->{"max_segment_$dimension"}, 1, undef,
            "$manifest_relative: registry max_segment_$dimension"
        );
        check_integer(
            $registry->{"max_total_$dimension"}, 1, undef,
            "$manifest_relative: registry max_total_$dimension"
        );
        if (is_positive_integer($registry->{"max_segment_$dimension"})
            && is_positive_integer($registry->{"max_total_$dimension"})
            && $registry->{"max_segment_$dimension"}
                > $registry->{"max_total_$dimension"}) {
            push @errors,
                "$manifest_relative: max_segment_$dimension exceeds max_total_$dimension";
        }
    }

    if (is_positive_integer($registry->{max_records})
        && @records > $registry->{max_records}) {
        push @errors,
            "$manifest_relative: segment record count " . scalar(@records)
                . " exceeds max_records $registry->{max_records}";
    }
    if (is_positive_integer($registry->{max_bytes})
        && length($raw) > $registry->{max_bytes}) {
        push @errors,
            "$manifest_relative: size " . length($raw)
                . " exceeds max_bytes $registry->{max_bytes}";
    }

    my @nodes;
    my %seen_segment_id;
    my %seen_segment_path;
    my %seen_root_id;
    my $record_number = 1;
    my %totals = (nodes => 0, lines => 0, bytes => 0);
    for my $record (@records) {
        $record_number++;
        my $where = "$manifest_relative: record $record_number";
        check_keys(
            $record,
            [qw(record_type schema_version segment_id path root_ids node_count sha256 source_revision source_path retention_contract)],
            [],
            $where,
        );
        check_equal($record->{record_type}, 'segment', "$where record_type");
        check_integer($record->{schema_version}, 1, 1,
            "$where schema_version");

        my $segment_id = $record->{segment_id};
        if (!defined $segment_id || ref $segment_id
            || $segment_id !~ /\A[A-Za-z0-9][A-Za-z0-9_.-]*\z/) {
            push @errors, "$where has invalid segment_id";
        }
        elsif ($seen_segment_id{$segment_id}++) {
            push @errors, "$where duplicates segment_id $segment_id";
        }

        my $segment_relative = $record->{path};
        if (!defined $segment_relative || ref $segment_relative
            || !safe_relative_path($segment_relative)
            || $segment_relative !~ /\.md\z/) {
            push @errors, "$where has unsafe or non-Markdown segment path";
            next;
        }
        if ($seen_segment_path{$segment_relative}++) {
            push @errors, "$where duplicates segment path $segment_relative";
        }

        my $digest = $record->{sha256};
        if (!defined $digest || ref $digest || $digest !~ /\A[0-9a-f]{64}\z/) {
            push @errors, "$where has invalid sha256";
            next;
        }
        if (basename($segment_relative) ne "$digest.md") {
            push @errors,
                "$where segment path basename must be the content digest $digest.md";
        }

        my $segment_path = checked_local_file(
            $segment_relative, "$where segment"
        );
        next if !defined $segment_path;
        my $segment_raw = read_file($segment_path, $segment_relative);
        my $segment_lines = line_count($segment_raw);
        my $actual_digest = sha256_hex($segment_raw);
        if ($actual_digest ne $digest) {
            push @errors,
                "$where sha256 mismatch for $segment_relative "
                    . "(declared $digest, actual $actual_digest)";
        }

        my $segment_section = extract_section($segment_raw, 'Task Tree Segment');
        if (!defined $segment_section) {
            push @errors,
                "$segment_relative: missing ## Task Tree Segment section";
            next;
        }
        my @part_nodes = parse_nodes(
            $segment_section, $segment_relative, 'segment'
        );
        if (!@part_nodes) {
            push @errors,
                "$segment_relative: ## Task Tree Segment contains no nodes";
            next;
        }

        my %measured = (
            nodes => scalar(@part_nodes),
            lines => $segment_lines,
            bytes => length($segment_raw),
        );
        for my $dimension (qw(nodes lines bytes)) {
            my $per_limit = $registry->{"max_segment_$dimension"};
            if (is_positive_integer($per_limit)
                && $measured{$dimension} > $per_limit) {
                push @errors,
                    "$where $dimension $measured{$dimension} exceeds "
                        . "max_segment_$dimension $per_limit";
            }
            $totals{$dimension} += $measured{$dimension};
        }

        check_integer($record->{node_count}, 1, undef, "$where node_count");
        if (is_positive_integer($record->{node_count})
            && $record->{node_count} != @part_nodes) {
            push @errors,
                "$where node_count $record->{node_count} does not match "
                    . scalar(@part_nodes) . " segment nodes";
        }

        my $root_ids = $record->{root_ids};
        if (ref($root_ids) ne 'ARRAY' || !@{$root_ids}) {
            push @errors, "$where root_ids must be a non-empty array";
            next;
        }
        my %part_by_id = map { $_->{id} => $_ } @part_nodes;
        report_duplicate_ids(\@part_nodes, "$where segment");
        my %covered;
        my %local_root;
        for my $root_id (@{$root_ids}) {
            if (!defined $root_id || ref $root_id
                || $root_id !~ /^\Q$tree_id\E(?:\.[1-9][0-9]*)+\z/) {
                push @errors, "$where has invalid root_id";
                next;
            }
            if ($local_root{$root_id}++ || $seen_root_id{$root_id}++) {
                push @errors, "$where duplicates sealed root_id $root_id";
            }
            my @overlap = grep {
                $_ ne $root_id
                    && ($_ =~ /^\Q$root_id\E\./ || $root_id =~ /^\Q$_\E\./)
            } keys %local_root;
            push @errors,
                "$where has overlapping sealed root_ids $root_id and "
                    . join(', ', sort_node_ids(@overlap))
                if @overlap;
            if (!exists $part_by_id{$root_id}) {
                push @errors,
                    "$where root_id $root_id is absent from $segment_relative";
            }
            for my $node_id (keys %part_by_id) {
                $covered{$node_id} = 1
                    if $node_id eq $root_id || $node_id =~ /^\Q$root_id\E\./;
            }
        }
        my @uncovered = sort_node_ids(
            grep { !$covered{$_} } keys %part_by_id
        );
        push @errors,
            "$where has nodes outside root_ids: " . join(', ', @uncovered)
            if @uncovered;

        my $source_revision = $record->{source_revision};
        my $source_path = $record->{source_path};
        if (!defined $source_revision || ref $source_revision
            || $source_revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/) {
            push @errors, "$where has invalid exact source_revision";
            next;
        }
        if (!defined $source_path || ref $source_path
            || !safe_relative_path($source_path)
            || $source_path !~ /\.md\z/) {
            push @errors, "$where has unsafe or non-Markdown source_path";
            next;
        }
        my $source_raw = retrieve_version_object(
            $source_revision, $source_path, "$where source",
            $record->{retention_contract},
        );
        next if !defined $source_raw;
        my $source_section = extract_section($source_raw, 'Task Tree');
        if (!defined $source_section) {
            push @errors,
                "$where source $source_revision:$source_path has no ## Task Tree section";
            next;
        }
        my @source_nodes = parse_nodes(
            $source_section, "$source_revision:$source_path", 'retrieved'
        );
        report_duplicate_ids(
            \@source_nodes, "$where exact source $source_revision:$source_path"
        );
        my %source_by_id = map { $_->{id} => $_ } @source_nodes;
        if (!exists $source_by_id{$tree_id}) {
            push @errors,
                "$where exact source does not contain tree root $tree_id";
        }

        for my $node (@part_nodes) {
            my $node_id = $node->{id};
            if (!exists $source_by_id{$node_id}) {
                push @errors,
                    "$where segment node $node_id is absent from exact source";
                next;
            }
            if (canonical_node($node) ne canonical_node($source_by_id{$node_id})) {
                push @errors,
                    "$where segment node $node_id differs from exact source";
            }
            my $status = one_field($node, 'Status');
            if (!defined $status || !$terminal_status{$status}) {
                push @errors,
                    "$where segment node $node_id is not terminal";
            }
        }
        for my $root_id (@{$root_ids}) {
            next if !defined $root_id || ref $root_id;
            my @source_subtree = grep {
                $_ eq $root_id || /^\Q$root_id\E\./
            } keys %source_by_id;
            my @missing = sort_node_ids(
                grep { !exists $part_by_id{$_} } @source_subtree
            );
            push @errors,
                "$where sealed root $root_id omits exact-source descendants "
                    . join(', ', @missing)
                if @missing;
        }
        push @nodes, @part_nodes;
    }

    for my $dimension (qw(nodes lines bytes)) {
        my $total_limit = $registry->{"max_total_$dimension"};
        if (is_positive_integer($total_limit)
            && $totals{$dimension} > $total_limit) {
            push @errors,
                "$manifest_relative: total segment $dimension $totals{$dimension} "
                    . "exceeds max_total_$dimension $total_limit";
        }
    }

    my @paths = ($manifest_relative, sort keys %seen_segment_path);
    return (\@nodes, scalar @records, \@paths);
}

sub load_migration_manifest {
    my (%args) = @_;
    my $tree_id = $args{tree_id};
    my $task_relative = $args{task_relative};
    my $manifest_relative = $args{manifest};

    if (!safe_relative_path($manifest_relative)
        || $manifest_relative !~ /\.jsonl\z/) {
        push @errors,
            "$task_relative: unsafe or non-JSONL migration manifest $manifest_relative";
        return 0;
    }
    my $manifest_path = checked_local_file(
        $manifest_relative, "$task_relative: migration manifest"
    );
    return 0 if !defined $manifest_path;
    my $raw = read_file($manifest_path, $manifest_relative);
    my @records = decode_jsonl($raw, $manifest_relative);
    return 0 if !@records;

    my $registry = shift @records;
    check_keys(
        $registry,
        [qw(record_type schema_version tree_id max_records max_bytes)],
        [], "$manifest_relative: registry record",
    );
    check_equal($registry->{record_type}, 'registry',
        "$manifest_relative: registry record_type");
    check_integer($registry->{schema_version}, 1, 1,
        "$manifest_relative: registry schema_version");
    check_equal($registry->{tree_id}, $tree_id,
        "$manifest_relative: registry tree_id");
    check_integer($registry->{max_records}, 1, undef,
        "$manifest_relative: registry max_records");
    check_integer($registry->{max_bytes}, 1, undef,
        "$manifest_relative: registry max_bytes");
    if (is_positive_integer($registry->{max_records})
        && @records > $registry->{max_records}) {
        push @errors,
            "$manifest_relative: migration record count " . scalar(@records)
                . " exceeds max_records $registry->{max_records}";
    }
    if (is_positive_integer($registry->{max_bytes})
        && length($raw) > $registry->{max_bytes}) {
        push @errors,
            "$manifest_relative: size " . length($raw)
                . " exceeds max_bytes $registry->{max_bytes}";
    }
    if (@records != 1) {
        push @errors,
            "$manifest_relative: must contain exactly one migration record";
        return scalar @records;
    }

    my $record = $records[0];
    my $where = "$manifest_relative: record 2";
    check_keys(
        $record,
        [qw(record_type schema_version migration_id outcome source_revision
            source_path source_sha256 source_lines source_bytes
            retention_contract semantic_manifest authoritative_nodes
            working_set_paths working_set_lines working_set_bytes
            product_relationship loss_residue_kind loss_residue_path
            loss_residue_sha256 loss_residue_lines loss_residue_bytes)],
        [], $where,
    );
    check_equal($record->{record_type}, 'migration', "$where record_type");
    check_integer($record->{schema_version}, 1, 1, "$where schema_version");
    my $migration_id = $record->{migration_id};
    push @errors, "$where has invalid migration_id"
        if !defined $migration_id || ref $migration_id
            || $migration_id !~ /\A[a-z][a-z0-9_.-]*\z/;
    check_equal($record->{outcome}, 're-form', "$where outcome");

    my $source_revision = $record->{source_revision};
    my $source_path = $record->{source_path};
    if (!defined $source_revision || ref $source_revision
        || $source_revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/) {
        push @errors, "$where has invalid exact source_revision";
    }
    if (!defined $source_path || ref $source_path
        || !safe_relative_path($source_path) || $source_path !~ /\.md\z/) {
        push @errors, "$where has unsafe or non-Markdown source_path";
    }
    my $source_sha = $record->{source_sha256};
    push @errors, "$where has invalid source_sha256"
        if !defined $source_sha || ref $source_sha
            || $source_sha !~ /\A[0-9a-f]{64}\z/;
    check_integer($record->{source_lines}, 1, undef, "$where source_lines");
    check_integer($record->{source_bytes}, 1, undef, "$where source_bytes");

    if (defined $source_revision && !ref $source_revision
        && $source_revision =~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/
        && defined $source_path && !ref $source_path
        && safe_relative_path($source_path)) {
        my $source = retrieve_version_object(
            $source_revision, $source_path, "$where complete source",
            $record->{retention_contract},
        );
        if (defined $source) {
            push @errors, "$where complete-source digest mismatch"
                if defined $source_sha && !ref $source_sha
                    && $source_sha =~ /\A[0-9a-f]{64}\z/
                    && sha256_hex($source) ne $source_sha;
            push @errors,
                "$where source_lines $record->{source_lines} does not match retrieved count "
                    . line_count($source)
                if is_positive_integer($record->{source_lines})
                    && line_count($source) != $record->{source_lines};
            push @errors,
                "$where source_bytes $record->{source_bytes} does not match retrieved count "
                    . length($source)
                if is_positive_integer($record->{source_bytes})
                    && length($source) != $record->{source_bytes};
        }
    }

    my $semantic_manifest = $record->{semantic_manifest};
    if (!defined $args{segment_manifest}) {
        push @errors, "$where semantic closure requires a Segment manifest";
    }
    elsif (!defined $semantic_manifest || ref $semantic_manifest
        || $semantic_manifest ne $args{segment_manifest}) {
        push @errors,
            "$where semantic_manifest must match $args{segment_manifest}";
    }
    check_integer($record->{authoritative_nodes}, 1, undef,
        "$where authoritative_nodes");
    if (is_positive_integer($record->{authoritative_nodes})
        && $record->{authoritative_nodes} != @{$args{segment_nodes}}) {
        push @errors,
            "$where authoritative_nodes $record->{authoritative_nodes} does not "
                . "match sealed semantic node count " . scalar(@{$args{segment_nodes}});
    }

    my @expected_paths = ($task_relative, @{$args{segment_paths}});
    my $declared_paths = $record->{working_set_paths};
    if (ref($declared_paths) ne 'ARRAY' || !@{$declared_paths}) {
        push @errors, "$where working_set_paths must be a non-empty array";
    }
    else {
        my %seen;
        my @unsafe = grep {
            !defined $_ || ref $_ || !safe_relative_path($_) || $seen{$_}++
        } @{$declared_paths};
        push @errors, "$where working_set_paths contains unsafe or duplicate paths"
            if @unsafe;
        my $expected = join("\0", sort @expected_paths);
        my $declared = join("\0", sort @{$declared_paths});
        push @errors,
            "$where working_set_paths does not exactly match the live root, segment manifest, and segment files"
            if $declared ne $expected;

        my ($lines, $bytes) = (0, 0);
        for my $path (@{$declared_paths}) {
            next if !defined $path || ref $path || !safe_relative_path($path);
            my $local = checked_local_file($path, "$where working-set path");
            next if !defined $local;
            my $contents = read_file($local, $path);
            $lines += line_count($contents);
            $bytes += length($contents);
        }
        check_integer($record->{working_set_lines}, 1, undef,
            "$where working_set_lines");
        check_integer($record->{working_set_bytes}, 1, undef,
            "$where working_set_bytes");
        push @errors,
            "$where working_set_lines $record->{working_set_lines} does not match measured count $lines"
            if is_positive_integer($record->{working_set_lines})
                && $record->{working_set_lines} != $lines;
        push @errors,
            "$where working_set_bytes $record->{working_set_bytes} does not match measured count $bytes"
            if is_positive_integer($record->{working_set_bytes})
                && $record->{working_set_bytes} != $bytes;
    }

    check_equal($record->{product_relationship}, 'overlapping_non_partition',
        "$where product_relationship");
    validate_loss_residue($record, $where);
    return 1;
}

sub load_acceptance_history_manifest {
    my (%args) = @_;
    my $tree_id = $args{tree_id};
    my $task_relative = $args{task_relative};
    my $current_task = $args{task_raw};
    my $manifest_relative = $args{manifest};

    if (!safe_relative_path($manifest_relative)
        || $manifest_relative !~ /\.jsonl\z/) {
        push @errors,
            "$task_relative: unsafe or non-JSONL acceptance-history manifest "
                . $manifest_relative;
        return 0;
    }
    my $manifest_path = checked_local_file(
        $manifest_relative, "$task_relative: acceptance-history manifest"
    );
    return 0 if !defined $manifest_path;

    my $raw = read_file($manifest_path, $manifest_relative);
    my @records = decode_jsonl($raw, $manifest_relative);
    return 0 if !@records;

    my $registry = shift @records;
    check_keys(
        $registry,
        [qw(record_type schema_version tree_id max_records max_bytes
            max_record_bytes)],
        [], "$manifest_relative: registry record",
    );
    check_equal($registry->{record_type}, 'registry',
        "$manifest_relative: registry record_type");
    check_integer($registry->{schema_version}, 1, 1,
        "$manifest_relative: registry schema_version");
    check_equal($registry->{tree_id}, $tree_id,
        "$manifest_relative: registry tree_id");
    check_integer($registry->{max_records}, 1, undef,
        "$manifest_relative: registry max_records");
    check_integer($registry->{max_bytes}, 1, undef,
        "$manifest_relative: registry max_bytes");
    check_integer($registry->{max_record_bytes}, 1, undef,
        "$manifest_relative: registry max_record_bytes");

    if (is_positive_integer($registry->{max_records})
        && @records > $registry->{max_records}) {
        push @errors,
            "$manifest_relative: acceptance-history record count "
                . scalar(@records)
                . " exceeds max_records $registry->{max_records}";
    }
    if (is_positive_integer($registry->{max_bytes})
        && length($raw) > $registry->{max_bytes}) {
        push @errors,
            "$manifest_relative: size " . length($raw)
                . " exceeds max_bytes $registry->{max_bytes}";
    }
    if (is_positive_integer($registry->{max_record_bytes})) {
        my $line = 0;
        for my $encoded (split /\n/, $raw) {
            $line++;
            push @errors,
                "$manifest_relative: record $line exceeds max_record_bytes "
                    . $registry->{max_record_bytes}
                if length($encoded) > $registry->{max_record_bytes};
        }
    }
    if (@records != 1) {
        push @errors,
            "$manifest_relative: must contain exactly one acceptance-history record";
        return scalar @records;
    }

    my $record = $records[0];
    my $where = "$manifest_relative: record 2";
    check_keys(
        $record,
        [qw(record_type schema_version history_id source_revision source_path
            source_sha256 source_lines source_bytes start_heading history_sha256
            history_lines history_bytes history_sections live_heading
            retention_contract)],
        [], $where,
    );
    check_equal($record->{record_type}, 'acceptance_history',
        "$where record_type");
    check_integer($record->{schema_version}, 1, 1,
        "$where schema_version");

    my $history_id = $record->{history_id};
    push @errors, "$where has invalid history_id"
        if !defined $history_id || ref $history_id
            || $history_id !~ /\A[a-z][a-z0-9_.-]*\z/;

    my $source_revision = $record->{source_revision};
    my $source_path = $record->{source_path};
    if (!defined $source_revision || ref $source_revision
        || $source_revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/) {
        push @errors, "$where has invalid exact source_revision";
    }
    if (!defined $source_path || ref $source_path
        || !safe_relative_path($source_path) || $source_path !~ /\.md\z/) {
        push @errors, "$where has unsafe or non-Markdown source_path";
    }
    elsif ($source_path ne $task_relative) {
        push @errors,
            "$where source_path must identify owning task $task_relative";
    }

    for my $field (qw(source_sha256 history_sha256)) {
        my $digest = $record->{$field};
        push @errors, "$where has invalid $field"
            if !defined $digest || ref $digest
                || $digest !~ /\A[0-9a-f]{64}\z/;
    }
    for my $field (
        qw(source_lines source_bytes history_lines history_bytes history_sections)
    ) {
        check_integer($record->{$field}, 1, undef, "$where $field");
    }
    for my $field (qw(start_heading live_heading)) {
        my $heading = $record->{$field};
        push @errors, "$where has invalid $field"
            if !defined $heading || ref $heading || $heading eq ''
                || $heading =~ /[\r\n`]/;
    }

    my $live_heading = $record->{live_heading};
    if (defined $live_heading && !ref $live_heading
        && $live_heading ne '' && $live_heading !~ /[\r\n`]/) {
        my @headings = $current_task =~ /^## \Q$live_heading\E\s*$/mg;
        if (@headings != 1) {
            push @errors,
                "$where live heading $live_heading is absent or duplicated";
        }
        else {
            my $live_section = extract_section($current_task, $live_heading);
            my @pointers = defined $live_section
                ? $live_section =~ /^- Acceptance history manifest: `([^`]+)`\s*$/mg
                : ();
            if (@pointers != 1 || $pointers[0] ne $manifest_relative) {
                push @errors,
                    "$where live heading $live_heading does not contain its exact manifest pointer";
            }
        }
    }

    return 1
        if !defined $source_revision || ref $source_revision
            || $source_revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/
            || !defined $source_path || ref $source_path
            || !safe_relative_path($source_path);
    my $source = retrieve_version_object(
        $source_revision, $source_path, "$where acceptance-history source",
        $record->{retention_contract},
    );
    return 1 if !defined $source;

    my $source_sha = $record->{source_sha256};
    if (defined $source_sha && !ref $source_sha
        && $source_sha =~ /\A[0-9a-f]{64}\z/
        && sha256_hex($source) ne $source_sha) {
        push @errors, "$where acceptance-history source digest mismatch";
    }
    push @errors,
        "$where source_lines $record->{source_lines} does not match retrieved count "
            . line_count($source)
        if is_positive_integer($record->{source_lines})
            && line_count($source) != $record->{source_lines};
    push @errors,
        "$where source_bytes $record->{source_bytes} does not match retrieved count "
            . length($source)
        if is_positive_integer($record->{source_bytes})
            && length($source) != $record->{source_bytes};

    my $start_heading = $record->{start_heading};
    return 1 if !defined $start_heading || ref $start_heading
        || $start_heading eq '' || $start_heading =~ /[\r\n`]/;
    my $needle = "## $start_heading\n";
    my @starts;
    while ($source =~ /^\Q$needle\E/mg) {
        push @starts, $-[0];
    }
    if (@starts != 1) {
        push @errors,
            "$where source heading $start_heading is absent or duplicated";
        return 1;
    }
    my $history = substr($source, $starts[0]);
    my $history_sha = $record->{history_sha256};
    if (defined $history_sha && !ref $history_sha
        && $history_sha =~ /\A[0-9a-f]{64}\z/
        && sha256_hex($history) ne $history_sha) {
        push @errors, "$where acceptance-history suffix digest mismatch";
    }
    push @errors,
        "$where history_lines $record->{history_lines} does not match retrieved count "
            . line_count($history)
        if is_positive_integer($record->{history_lines})
            && line_count($history) != $record->{history_lines};
    push @errors,
        "$where history_bytes $record->{history_bytes} does not match retrieved count "
            . length($history)
        if is_positive_integer($record->{history_bytes})
            && length($history) != $record->{history_bytes};
    my $history_sections = () = $history =~ /^## /mg;
    push @errors,
        "$where history_sections $record->{history_sections} does not match retrieved count "
            . $history_sections
        if is_positive_integer($record->{history_sections})
            && $history_sections != $record->{history_sections};
    return 1;
}

sub validate_loss_residue {
    my ($record, $where) = @_;
    my $kind = $record->{loss_residue_kind};
    check_integer($record->{loss_residue_lines}, 0, undef,
        "$where loss_residue_lines");
    check_integer($record->{loss_residue_bytes}, 0, undef,
        "$where loss_residue_bytes");
    if (defined $kind && !ref $kind && $kind eq 'none') {
        push @errors, "$where zero loss residue must use path '-' and sha256 '-'"
            if ($record->{loss_residue_path} // '') ne '-'
                || ($record->{loss_residue_sha256} // '') ne '-';
        push @errors, "$where loss residue declared none but dimensions are nonzero"
            if ($record->{loss_residue_lines} // -1) != 0
                || ($record->{loss_residue_bytes} // -1) != 0;
        return;
    }
    if (!defined $kind || ref $kind || $kind ne 'content_addressed_file') {
        push @errors,
            "$where loss_residue_kind must be none or content_addressed_file";
        return;
    }
    my $path = $record->{loss_residue_path};
    my $digest = $record->{loss_residue_sha256};
    if (!defined $path || ref $path || !safe_relative_path($path)
        || !defined $digest || ref $digest
        || $digest !~ /\A[0-9a-f]{64}\z/
        || basename($path) !~ /\A\Q$digest\E\.(?:md|txt)\z/) {
        push @errors,
            "$where loss residue must be a content-addressed repository Markdown/text file";
        return;
    }
    my $local = checked_local_file($path, "$where loss residue");
    return if !defined $local;
    my $contents = read_file($local, $path);
    push @errors, "$where loss-residue digest mismatch"
        if sha256_hex($contents) ne $digest;
    push @errors, "$where loss-residue line count mismatch"
        if line_count($contents) != ($record->{loss_residue_lines} // -1);
    push @errors, "$where loss-residue byte count mismatch"
        if length($contents) != ($record->{loss_residue_bytes} // -1);
}

sub validate_tree {
    my (%args) = @_;
    my $tree_id = $args{tree_id};
    my $task_relative = $args{task_relative};
    my @live_nodes = @{$args{live_nodes}};
    my @nodes = @{$args{nodes}};

    my %node_by_id;
    for my $node (@nodes) {
        my $node_id = $node->{id};
        if (exists $node_by_id{$node_id}) {
            push @errors,
                "$task_relative: duplicate node ID $node_id across "
                    . "$node_by_id{$node_id}{display} and $node->{display}";
            next;
        }
        $node_by_id{$node_id} = $node;
    }

    my $root_node = $node_by_id{$tree_id};
    if (!defined $root_node) {
        push @errors, "$task_relative: active tree root $tree_id is missing";
    }
    elsif ($live_nodes[0]{id} ne $tree_id) {
        push @errors,
            "$task_relative: active tree root $tree_id is not the first live node";
    }
    elsif ($root_node->{origin} ne 'live') {
        push @errors, "$task_relative: active tree root $tree_id is not live";
    }

    for my $node (@nodes) {
        my ($node_id, $body) = @{$node}{qw(id body)};
        my $display = $node->{display};
        if ($node_id ne $tree_id
            && $node_id !~ /^\Q$tree_id\E(?:\.[1-9][0-9]*)+\z/) {
            push @errors,
                "$display: node $node_id is not a descendant of root $tree_id";
        }

        if ($node->{origin} eq 'live') {
            for my $field (
                'Goal', 'Acceptance', 'Verification', 'Commit', 'Blocked by'
            ) {
                my @parsed = field_values($node, $field);
                my $count = field_count($node, $field);
                push @errors,
                    "$display: live node $node_id $field fields must use backtick-delimited values"
                    if @parsed != $count;
                for my $value (narrative_field_values($node, $field)) {
                    my $bytes = length($value);
                    push @errors,
                        "$display: live node $node_id $field bytes $bytes exceed "
                            . $max_live_narrative_bytes
                        if $bytes > $max_live_narrative_bytes;
                }
            }
        }

        my @statuses = field_values($node, 'Status');
        if (@statuses != 1) {
            push @errors,
                "$display: node $node_id must have exactly one Status field";
            next;
        }
        my $status = $statuses[0];
        if (!$valid_status{$status}) {
            push @errors, "$display: node $node_id has unknown status $status";
        }
        $node->{status} = $status;

        my $goal_count = field_count($node, 'Goal');
        if ($goal_count != 1) {
            push @errors,
                "$display: node $node_id must have exactly one Goal field";
        }
        if ($node->{origin} eq 'segment' && !$terminal_status{$status}) {
            push @errors,
                "$display: sealed segment node $node_id has nonterminal status $status";
        }

        my @actual_children = sort_node_ids(
            grep { /^\Q$node_id\E\.[1-9][0-9]*\z/ } keys %node_by_id
        );
        my @child_lines =
            $body =~ /^  Children(?: continuation(?: \d+)?)?:\s*(.*)$/mg;
        my @listed_children = parse_child_lines(
            $display, $node_id, \@child_lines
        );

        my @terminal_kinds = field_values($node, 'Terminal');
        if (@terminal_kinds) {
            validate_compact_terminal(
                node            => $node,
                actual_children => \@actual_children,
                child_lines     => \@child_lines,
            );
            next;
        }

        validate_child_closure(
            display         => $display,
            node_id         => $node_id,
            status          => $status,
            actual_children => \@actual_children,
            child_lines     => \@child_lines,
            listed_children => \@listed_children,
        );
        if (@actual_children || @child_lines) {
            if ($status ne 'active' && $status ne 'done') {
                push @errors,
                    "$display: container $node_id has non-container status $status";
            }
        }
        else {
            validate_leaf_fields($node, $node->{origin} eq 'segment');
        }
    }

    for my $node (@nodes) {
        my $node_id = $node->{id};
        next if $node_id eq $tree_id;
        (my $parent_id = $node_id) =~ s/\.[1-9][0-9]*\z//;
        if (!exists $node_by_id{$parent_id}) {
            push @errors,
                "$node->{display}: node $node_id has missing parent $parent_id";
            next;
        }
        if (defined $node->{status} && !$terminal_status{$node->{status}}
            && $node_by_id{$parent_id}{origin} ne 'live') {
            push @errors,
                "$node->{display}: nonterminal node $node_id has non-live ancestor $parent_id";
        }
    }

    for my $node (@nodes) {
        next if !defined $node->{status} || $node->{status} ne 'done';
        next if scalar(field_values($node, 'Terminal'));
        my $node_id = $node->{id};
        my @children = grep {
            /^\Q$node_id\E\.[1-9][0-9]*\z/
        } keys %node_by_id;
        my @nonterminal = sort_node_ids(grep {
            my $child_status = $node_by_id{$_}{status} // '';
            !$terminal_status{$child_status};
        } @children);
        push @errors,
            "$node->{display}: done container $node_id has nonterminal direct children "
                . join(', ', @nonterminal)
            if @nonterminal;
    }

    if (defined $root_node && defined $root_node->{status}
        && $root_node->{status} ne 'active') {
        push @errors,
            "$task_relative: indexed active tree root $tree_id has status $root_node->{status}";
    }
}

sub validate_compact_terminal {
    my (%args) = @_;
    my $node = $args{node};
    my $node_id = $node->{id};
    my $display = $node->{display};

    my @terminal = field_values($node, 'Terminal');
    if (@terminal != 1 || $terminal[0] ne 'version_object') {
        push @errors,
            "$display: compact terminal $node_id must use Terminal version_object";
        return;
    }
    if ($node->{origin} ne 'live') {
        push @errors,
            "$display: compact terminal $node_id must remain in the live root";
    }
    if (($node->{status} // '') ne 'done') {
        push @errors,
            "$display: compact terminal $node_id must have status done";
    }
    if (@{$args{actual_children}} || @{$args{child_lines}}) {
        push @errors,
            "$display: compact terminal $node_id must not carry live children";
    }
    if (field_count($node, 'Acceptance')) {
        push @errors,
            "$display: compact terminal $node_id must retrieve Acceptance from its version object";
    }

    for my $field (
        'Revision', 'Retrieval path', 'Retrieved SHA256',
        'Archived node count', 'Retention contract', 'Verification', 'Commit'
    ) {
        my $count = field_count($node, $field);
        push @errors,
            "$display: compact terminal $node_id must have exactly one $field field"
            if $count != 1;
    }

    my $revision = one_field($node, 'Revision');
    my $retrieval_path = one_field($node, 'Retrieval path');
    my $digest = one_field($node, 'Retrieved SHA256');
    my $node_count = one_field($node, 'Archived node count');
    my $retention_contract = one_field($node, 'Retention contract');
    my $verification = one_field($node, 'Verification');
    my $commit = one_field($node, 'Commit');
    return if !defined $revision || !defined $retrieval_path
        || !defined $digest || !defined $node_count;

    if ($revision !~ /\A(?:[0-9a-f]{40}|[0-9a-f]{64})\z/) {
        push @errors,
            "$display: compact terminal $node_id has invalid exact Revision";
        return;
    }
    if (!safe_relative_path($retrieval_path)
        || $retrieval_path !~ /\.md\z/) {
        push @errors,
            "$display: compact terminal $node_id has unsafe Retrieval path";
        return;
    }
    if ($digest !~ /\A[0-9a-f]{64}\z/) {
        push @errors,
            "$display: compact terminal $node_id has invalid Retrieved SHA256";
        return;
    }
    if (!is_positive_integer($node_count)) {
        push @errors,
            "$display: compact terminal $node_id has invalid Archived node count";
        return;
    }
    if (!defined $verification || $verification eq '' || $verification eq 'pending'
        || !defined $commit || $commit eq '' || $commit eq 'pending') {
        push @errors,
            "$display: compact terminal $node_id has pending verification or commit evidence";
    }

    my $retrieved = retrieve_version_object(
        $revision, $retrieval_path, "$display: compact terminal $node_id",
        $retention_contract,
    );
    return if !defined $retrieved;
    my $actual_digest = sha256_hex($retrieved);
    if ($actual_digest ne $digest) {
        push @errors,
            "$display: compact terminal $node_id retrieved digest mismatch "
                . "(declared $digest, actual $actual_digest)";
        return;
    }

    my $section = extract_section($retrieved, 'Task Tree');
    if (!defined $section) {
        push @errors,
            "$display: compact terminal $node_id version object has no ## Task Tree section";
        return;
    }
    my @retrieved_nodes = parse_nodes(
        $section, "$revision:$retrieval_path", 'retrieved'
    );
    report_duplicate_ids(
        \@retrieved_nodes,
        "$display: compact terminal $node_id version object"
    );
    my %retrieved_by_id = map { $_->{id} => $_ } @retrieved_nodes;
    (my $retrieved_tree_id = $node_id) =~ s/\..*\z//;
    if (!exists $retrieved_by_id{$retrieved_tree_id}) {
        push @errors,
            "$display: compact terminal $node_id version object has no tree root $retrieved_tree_id";
    }
    if (!exists $retrieved_by_id{$node_id}) {
        push @errors,
            "$display: compact terminal $node_id is absent from its version object";
        return;
    }

    my @subtree_ids = sort_node_ids(grep {
        $_ eq $node_id || /^\Q$node_id\E\./
    } keys %retrieved_by_id);
    if (@subtree_ids != $node_count) {
        push @errors,
            "$display: compact terminal $node_id Archived node count $node_count "
                . "does not match retrieved count " . scalar(@subtree_ids);
    }

    my $current_goal = one_field($node, 'Goal');
    my $retrieved_goal = one_field($retrieved_by_id{$node_id}, 'Goal');
    if (!defined $current_goal || !defined $retrieved_goal
        || $current_goal ne $retrieved_goal) {
        push @errors,
            "$display: compact terminal $node_id Goal differs from its version object";
    }

    my %subtree = map { $_ => 1 } @subtree_ids;
    for my $archived_id (@subtree_ids) {
        my $archived = $retrieved_by_id{$archived_id};
        my $archived_status = one_field($archived, 'Status');
        if (!defined $archived_status || !$terminal_status{$archived_status}) {
            push @errors,
                "$display: compact terminal $node_id retrieves nonterminal node $archived_id";
            next;
        }
        my @actual_children = sort_node_ids(grep {
            /^\Q$archived_id\E\.[1-9][0-9]*\z/ && $subtree{$_}
        } keys %retrieved_by_id);
        my @child_lines =
            $archived->{body} =~ /^  Children(?: continuation(?: \d+)?)?:\s*(.*)$/mg;
        my @listed_children = parse_child_lines(
            "$revision:$retrieval_path", $archived_id, \@child_lines
        );
        validate_child_closure(
            display         => "$revision:$retrieval_path",
            node_id         => $archived_id,
            status          => $archived_status,
            actual_children => \@actual_children,
            child_lines     => \@child_lines,
            listed_children => \@listed_children,
        );
        if (!@actual_children && !@child_lines) {
            validate_leaf_fields($archived, 1);
        }
    }
    $total_compact_terminals++;
}

sub validate_child_closure {
    my (%args) = @_;
    my @actual = @{$args{actual_children}};
    my @lines = @{$args{child_lines}};
    my @listed = @{$args{listed_children}};
    my $display = $args{display};
    my $node_id = $args{node_id};

    if (@actual || @lines) {
        if (!@lines) {
            push @errors, "$display: container $node_id has no Children field";
        }
        my %listed_count;
        $listed_count{$_}++ for @listed;
        for my $child (sort_node_ids(keys %listed_count)) {
            push @errors,
                "$display: container $node_id lists child $child more than once"
                if $listed_count{$child} > 1;
        }
        my %actual = map { $_ => 1 } @actual;
        my %listed = map { $_ => 1 } @listed;
        my @missing = sort_node_ids(grep { !$listed{$_} } keys %actual);
        my @extra = sort_node_ids(grep { !$actual{$_} } keys %listed);
        push @errors,
            "$display: container $node_id omits direct children "
                . join(', ', @missing)
            if @missing;
        push @errors,
            "$display: container $node_id lists nonexistent direct children "
                . join(', ', @extra)
            if @extra;
    }
}

sub validate_leaf_fields {
    my ($node, $require_closed_evidence) = @_;
    my $node_id = $node->{id};
    my $display = $node->{display};
    for my $field (qw(Acceptance Verification Commit)) {
        my $count = field_count($node, $field);
        push @errors,
            "$display: leaf $node_id must have exactly one $field field"
            if $count != 1;
    }
    return if !$require_closed_evidence;
    if (field_count($node, 'Verification') != 1
        || field_count($node, 'Commit') != 1
        || field_is_pending($node, 'Verification')
        || field_is_pending($node, 'Commit')) {
        push @errors,
            "$display: sealed terminal leaf $node_id has pending verification or commit evidence";
    }
}

sub parse_child_lines {
    my ($display, $node_id, $lines) = @_;
    my @listed;
    for my $child_line (@{$lines}) {
        if ($child_line !~ /^`(.*)`\s*$/) {
            push @errors,
                "$display: container $node_id has malformed Children field";
            next;
        }
        for my $child (split /,/, $1, -1) {
            $child =~ s/^\s+|\s+$//g;
            if ($child !~ /^\Q$node_id\E\.[1-9][0-9]*\z/) {
                push @errors,
                    "$display: container $node_id has malformed direct child $child";
                next;
            }
            push @listed, $child;
        }
    }
    return @listed;
}

sub parse_nodes {
    my ($section, $display, $origin) = @_;
    my @nodes;
    while ($section =~ /^- ID: `([^`]+)`\s*\n(.*?)(?=^- ID: `|\z)/msg) {
        push @nodes, {
            id      => $1,
            body    => $2,
            display => $display,
            origin  => $origin,
        };
    }
    return @nodes;
}

sub extract_section {
    my ($contents, $heading) = @_;
    my ($section) =
        $contents =~ /^## \Q$heading\E\s*\n(.*?)(?=^## |\z)/ms;
    return $section;
}

sub canonical_node {
    my ($node) = @_;
    my $body = $node->{body};
    $body =~ s/[ \t]+$//mg;
    $body =~ s/\s+\z//;
    return "- ID: `$node->{id}`\n$body\n";
}

sub field_values {
    my ($node, $field) = @_;
    return $node->{body} =~ /^  \Q$field\E: `(.*)`\s*$/mg;
}

sub narrative_field_values {
    my ($node, $field) = @_;
    my @values = $node->{body} =~ /^  \Q$field\E:\s*(.*)$/mg;
    for my $value (@values) {
        $value =~ s/[ \t]+\z//;
        $value =~ s/\A`//;
        $value =~ s/`\z//;
    }
    return @values;
}

sub field_count {
    my ($node, $field) = @_;
    my @matches = $node->{body} =~ /^  \Q$field\E:/mg;
    return scalar @matches;
}

sub field_is_pending {
    my ($node, $field) = @_;
    return $node->{body} =~ /^  \Q$field\E:\s*`pending`\s*$/m;
}

sub one_field {
    my ($node, $field) = @_;
    my @values = field_values($node, $field);
    return @values == 1 ? $values[0] : undef;
}

sub decode_jsonl {
    my ($raw, $display) = @_;
    my @records;
    my $json = JSON::PP->new->utf8;
    my $line_number = 0;
    my @lines = split /\n/, $raw, -1;
    for my $line (@lines) {
        $line_number++;
        next if $line_number == @lines && $line eq '';
        if ($line eq '') {
            push @errors, "$display:$line_number: blank JSONL line";
            next;
        }
        my $record = eval { $json->decode($line) };
        if ($@ || ref($record) ne 'HASH') {
            push @errors, "$display:$line_number: malformed JSON object";
            next;
        }
        push @records, $record;
    }
    push @errors, "$display: contains no JSONL records" if !@records;
    return @records;
}

sub check_keys {
    my ($record, $required, $optional, $where) = @_;
    my %allowed = map { $_ => 1 } (@{$required}, @{$optional});
    for my $key (@{$required}) {
        push @errors, "$where is missing required key $key"
            if !exists $record->{$key};
    }
    for my $key (sort keys %{$record}) {
        push @errors, "$where has unknown key $key" if !$allowed{$key};
    }
}

sub check_equal {
    my ($actual, $expected, $where) = @_;
    push @errors, "$where must be $expected"
        if !defined $actual || ref $actual || $actual ne $expected;
}

sub check_integer {
    my ($actual, $minimum, $maximum, $where) = @_;
    my $encoded = defined $actual && !ref $actual
        ? JSON::PP->new->allow_nonref->encode($actual)
        : '';
    if ($encoded !~ /\A[0-9]+\z/
        || $actual < $minimum
        || (defined $maximum && $actual > $maximum)) {
        my $range = defined $maximum
            ? "$minimum..$maximum"
            : ">=$minimum";
        push @errors, "$where must be an integer $range";
    }
}

sub is_positive_integer {
    my ($value) = @_;
    return defined $value && !ref $value
        && $value =~ /\A[1-9][0-9]*\z/;
}

sub line_count {
    my ($contents) = @_;
    return 0 if $contents eq '';
    my $lines = ($contents =~ tr/\n//);
    $lines++ if $contents !~ /\n\z/;
    return $lines;
}

sub load_retention_contracts {
    return if $retention_contracts_loaded++;
    my $path = checked_local_file(
        $retention_registry_relative, 'version-object retention registry'
    );
    return if !defined $path;
    my $raw = read_file($path, $retention_registry_relative);
    my @records = decode_jsonl($raw, $retention_registry_relative);
    return if !@records;
    my $registry = shift @records;
    check_keys(
        $registry,
        [qw(record_type schema_version max_records max_bytes max_record_bytes)], [],
        "$retention_registry_relative: registry record",
    );
    check_equal($registry->{record_type}, 'registry',
        "$retention_registry_relative: registry record_type");
    check_integer($registry->{schema_version}, 1, 1,
        "$retention_registry_relative: registry schema_version");
    check_integer($registry->{max_records}, 1, undef,
        "$retention_registry_relative: registry max_records");
    check_integer($registry->{max_bytes}, 1, undef,
        "$retention_registry_relative: registry max_bytes");
    check_integer($registry->{max_record_bytes}, 1, undef,
        "$retention_registry_relative: registry max_record_bytes");
    push @errors,
        "$retention_registry_relative: contract count " . scalar(@records)
            . " exceeds max_records $registry->{max_records}"
        if is_positive_integer($registry->{max_records})
            && @records > $registry->{max_records};
    push @errors,
        "$retention_registry_relative: size " . length($raw)
            . " exceeds max_bytes $registry->{max_bytes}"
        if is_positive_integer($registry->{max_bytes})
            && length($raw) > $registry->{max_bytes};
    if (is_positive_integer($registry->{max_record_bytes})) {
        my $line = 0;
        for my $encoded (split /\n/, $raw) {
            $line++;
            push @errors,
                "$retention_registry_relative: record $line exceeds max_record_bytes "
                    . $registry->{max_record_bytes}
                if length($encoded) > $registry->{max_record_bytes};
        }
    }
    my $number = 1;
    for my $record (@records) {
        $number++;
        my $where = "$retention_registry_relative: record $number";
        check_keys(
            $record,
            [qw(record_type schema_version contract_id owner guarantee recovery)],
            [], $where,
        );
        check_equal($record->{record_type}, 'contract', "$where record_type");
        check_integer($record->{schema_version}, 1, 1, "$where schema_version");
        my $id = $record->{contract_id};
        if (!defined $id || ref $id || $id !~ /\A[a-z][a-z0-9_.-]*\z/) {
            push @errors, "$where has invalid contract_id";
            next;
        }
        push @errors, "$where duplicates contract_id $id"
            if exists $retention_contracts{$id};
        for my $field (qw(owner guarantee recovery)) {
            my $value = $record->{$field};
            push @errors, "$where has empty or multiline $field"
                if !defined $value || ref $value || $value eq ''
                    || $value =~ /[\r\n\t]/;
        }
        $retention_contracts{$id} = $record;
    }
}

sub require_retention_contract {
    my ($id, $where) = @_;
    load_retention_contracts();
    if (!defined $id || ref $id
        || $id !~ /\A[a-z][a-z0-9_.-]*\z/) {
        push @errors, "$where has invalid or missing retention contract";
        return undef;
    }
    if (!exists $retention_contracts{$id}) {
        push @errors, "$where names unknown retention contract $id";
        return undef;
    }
    return $retention_contracts{$id};
}

sub retrieve_version_object {
    my ($revision, $path, $where, $retention_contract) = @_;
    my $contract = require_retention_contract($retention_contract, $where);
    return undef if !defined $contract;
    my ($ok, undef, undef, $stdout, $stderr) = run(
        command => ['git', '-C', $root, 'show', "$revision:$path"],
    );
    if (!$ok) {
        my $detail = join('', @{$stderr || []});
        $detail =~ s/\s+/ /g;
        $detail =~ s/^\s+|\s+$//g;
        push @errors,
            "$where cannot retrieve exact version object $revision:$path"
                . ($detail ne '' ? " ($detail)" : '')
                . "; retention contract $retention_contract owner "
                . "$contract->{owner} requires recovery: $contract->{recovery}";
        return undef;
    }
    return join('', @{$stdout || []});
}

sub checked_local_file {
    my ($relative, $where) = @_;
    if (!safe_relative_path($relative)) {
        push @errors, "$where uses unsafe path $relative";
        return undef;
    }
    my $path = local_path($relative);
    if (!-f $path) {
        push @errors, "$where file $relative is missing";
        return undef;
    }
    my $cursor = $root;
    for my $part (split m{/}, $relative) {
        $cursor = File::Spec->catfile($cursor, $part);
        if (-l $cursor) {
            push @errors, "$where path $relative crosses a symlink";
            return undef;
        }
    }
    my @root_stat = stat $root;
    my @file_stat = stat $path;
    if (!@root_stat || !@file_stat || $root_stat[0] != $file_stat[0]) {
        push @errors, "$where file $relative is not on the repository volume";
        return undef;
    }
    return $path;
}

sub safe_relative_path {
    my ($path) = @_;
    return 0 if !defined $path || ref $path || $path eq '';
    return 0 if File::Spec->file_name_is_absolute($path);
    return 0 if $path =~ /\\/;
    return 0 if $path =~ m{(?:^|/)\.{1,2}(?:/|$)};
    return 0 if $path =~ m{//};
    return 1;
}

sub report_duplicate_ids {
    my ($nodes, $where) = @_;
    my %seen;
    for my $node (@{$nodes}) {
        push @errors, "$where duplicates node ID $node->{id}"
            if $seen{$node->{id}}++;
    }
}

sub local_path {
    my ($relative) = @_;
    return File::Spec->catfile($root, split m{/}, $relative);
}

sub sort_node_ids {
    return sort {
        my ($a_tail) = $a =~ /\.([1-9][0-9]*)\z/;
        my ($b_tail) = $b =~ /\.([1-9][0-9]*)\z/;
        ($a_tail // 0) <=> ($b_tail // 0) || $a cmp $b;
    } @_;
}

sub read_file {
    my ($path, $display) = @_;
    open my $fh, '<:raw', $path or fail("cannot read $display: $!");
    local $/;
    my $contents = <$fh>;
    close $fh or fail("cannot close $display: $!");
    return $contents;
}

sub fail {
    my ($message) = @_;
    print STDERR "[task-tree-integrity] FAIL: $message\n";
    exit 1;
}

sub usage {
    my ($exit) = @_;
    print <<'USAGE';
Usage:
  scripts/check_task_tree_integrity.pl [--root PATH]

Checks active task trees indexed by docs/TASK_TREE.md. The live task file is
authoritative; optional bounded JSONL manifests may add exact-source sealed
subtree segments, and compact completed terminals must retrieve their full
terminal subtree from an exact version object. A bounded completed-history
manifest may prove query-first terminal index rows from an exact version while
the live PNT tables retain only active/proposed work. A bounded acceptance-
history manifest may authenticate an exact predecessor suffix while live node
narration remains independently capped. PATH is intended for focused
repository-local fixtures.
USAGE
    exit $exit;
}

