    }), qr/active repository RAM guard/,
        'a measured run cannot start outside active safety enforcement');

    like(dies(sub {
        $class->measure({
            repository_root => $repo_root,
            construction => $construction,
            run_class => 'gate_measurement',
            run_ordinal => 4,
            validation_record => $validation,
