sub construct_plan {
    my (%args) = @_;
    return probe_plan('construct', %args);
}

sub parse_validate_plan {
    my (%args) = @_;
    return probe_plan('parse_validate', %args);
}

sub probe_plan {
    my ($stage, %args) = @_;
    my $content = $stage eq 'construct'
        ? "foundation measurement output\n"
        : "foundation parse validation output\n";
    return {
        stage => $stage,
        classification => 'fsmgen_owned',
        command_identity => {
            logical_name => "foundation_${stage}_probe",
            arguments => [],
            thread_count => 1,
            job_count => 1,
        },
        input_counts => {
            files => 1,
            lines => 3,
            bytes => bytes::length($source),
            objects => 1,
        },
        backend_timeout_seconds => $args{backend_timeout_seconds},
        worker => sub {
            my ($context) = @_;
            sleep($args{delay_seconds}) if $args{delay_seconds};
            make_path($context->{output_root});
            my $path = File::Spec->catfile(
                $context->{output_root}, "$stage.txt",
            );
            write_raw($path, $content);
            return {
                ok => JSON::PP::true,
                status => "foundation_${stage}_completed",
                output_counts => {
                    files => 1,
                    lines => 1,
                    bytes => bytes::length($content),
                    objects => 1,
                },
                semantic_object_counts => {
                    "foundation_${stage}_records" => 1,
                },
                correctness_oracles => [{
                    oracle_id => "foundation_${stage}_content_exact",
                    ok => JSON::PP::true,
                    evidence => {
                        bytes => bytes::length($content),
                        sha256 => sha256_hex($content),
                    },
                }],
                artifacts => [{
                    relative_path => "$context->{output_identity}/$stage.txt",
                    kind => 'foundation_probe',
                    bytes => bytes::length($content),
                    lines => 1,
                    sha256 => sha256_hex($content),
                }],
                diagnostic => undef,
            };
        },
    };
}

sub failure_plan {
    return {
        stage => 'construct',
        classification => 'fsmgen_owned',
        command_identity => {
            logical_name => 'foundation_failure_probe',
            arguments => [],
            thread_count => 1,
            job_count => 1,
        },
        input_counts => {
            files => 1,
            lines => 3,
            bytes => bytes::length($source),
            objects => 1,
        },
        backend_timeout_seconds => undef,
        worker => sub {
            die "intentional measurement failure at $repo_root/private\n";
        },
    };
}

sub unreported_artifact_plan {
    my $plan = construct_plan(delay_seconds => 0);
    $plan->{worker} = sub {
        my ($context) = @_;
        make_path($context->{output_root});
        write_raw(
            File::Spec->catfile($context->{output_root}, 'unreported.txt'),
            "unreported\n",
        );
        return {
            ok => JSON::PP::true,
            status => 'foundation_unreported_probe_completed',
            output_counts => {
                files => 0, lines => 0, bytes => 0, objects => 0,
            },
            semantic_object_counts => {},
            correctness_oracles => [{
                oracle_id => 'foundation_unreported_probe_reached',
                ok => JSON::PP::true,
                evidence => {worker_completed => JSON::PP::true},
            }],
            artifacts => [],
            diagnostic => undef,
        };
    };
    return $plan;
}

sub cleanup_publication {
    my ($profile) = @_;
    my $target = repo_path(
        qw(.artifacts qualification vial-scale v1), $profile,
    );
    remove_tree($target) if -d $target && !-l $target;
    for my $parts (
        [qw(.artifacts qualification vial-scale v1)],
        [qw(.artifacts qualification vial-scale)],
        [qw(.artifacts qualification)],
    ) {
        my $path = repo_path(@$parts);
        rmdir $path if -d $path && !-l $path;
    }
}

sub validation_stage_relative {
    my ($value) = @_;
    my ($digest) = $value->{workload_identity}
        =~ m{\Aworkload/([0-9a-f]{64})\z};
    die "test construction has no workload digest\n" unless defined $digest;
    return ".artifacts/tmp/vial-scale/$digest/validation/00";
}

sub stage_lock_path {
    my ($stage_relative) = @_;
    return repo_path(
        '.artifacts', 'locks', 'vial-scale-measurement',
        sha256_hex($stage_relative) . '.lock',
    );
}

sub cleanup_stage_fixture {
    my ($relative) = @_;
    my $path = repo_path($relative);
    remove_tree($path) if -d $path && !-l $path;
    my @parts = split m{/}, $relative;
    pop @parts;
    while (@parts >= 2) {
        my $parent = repo_path(@parts);
        rmdir $parent if -d $parent && !-l $parent;
        pop @parts;
    }
}

sub validation_probe {
    return $class->measure({
        repository_root => $repo_root,
        construction => $construction,
        run_class => 'validation',
        run_ordinal => 0,
        validation_record => undef,
        stage_plan => [construct_plan(delay_seconds => 0)],
    });
}

sub repo_path {
    my (@parts) = @_;
    if (@parts == 1 && $parts[0] =~ m{/}) {
        @parts = split m{/}, $parts[0];
    }
    return File::Spec->catfile($repo_root, @parts);
}

sub write_raw {
    my ($path, $content) = @_;
    open my $fh, '>:raw', $path or die "cannot write $path: $!";
    print {$fh} $content;
    close $fh or die "cannot close $path: $!";
}

sub append_raw {
    my ($path, $content) = @_;
    open my $fh, '>>:raw', $path or die "cannot append $path: $!";
    print {$fh} $content;
    close $fh or die "cannot close $path: $!";
}

sub slurp_raw {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "cannot read $path: $!";
    local $/;
    my $content = <$fh>;
    close $fh or die "cannot close $path: $!";
    return $content;
}

sub dies {
    my ($code) = @_;
    my $ok = eval { $code->(); 1 };
    return $ok ? '' : "$@";
}

sub clone {
    my ($value) = @_;
    return $json->decode($json->encode($value));
}

sources.t/1671-vial-vhdl-portable-trace-v2.t:
#!/usr/bin/env perl

use strict;
use warnings;

use Digest::SHA qw(sha256_hex);
use File::Spec;
use FindBin;
use JSON::PP ();
use Test::More;

use lib File::Spec->catdir($FindBin::Bin, '..', 'perl');

use FSM::VIAL::Backend::VHDLPortableTraceValidator;

my $json = JSON::PP->new->canonical(1);
my $prefix = "FSMGEN_VIAL_TRACE_V2\t";
my $plan_id = 'plan/portable-vhdl-trace-v2-test';
my $run_id = "run/$plan_id/scenario/one";
my @kind = qw(
    header scenario_start events samples expectations scoreboards coverage faults
    scenario_end footer
);
my %expected = map { $_ => 0 } @kind;
@expected{qw(header scenario_start samples scenario_end footer)} = (1, 1, 2, 1, 1);

my $catalog_projection = {
    entries => [
        {sample_id => 'sample/endpoint/out', semantic_id => 'endpoint/out', width => 2},
        {sample_id => 'sample/probe/state', semantic_id => 'probe/state', width => 2},
    ],
    schema => 'fsmgen.vial_vhdl_observation_catalog.v1',
    total_width => 4,
};
my $catalog = {
    catalog_digest => 'sha256/' . sha256_hex($json->encode($catalog_projection)),
    %$catalog_projection,
};

my $checked_authority =
    FSM::VIAL::Backend::VHDLPortableTraceValidator->checked_reference_authority;
is_deeply([sort keys %$checked_authority], [sort qw(
    expected_diagnostic_codes expected_domain_id expected_fixture_id
    expected_observation_catalog expected_plan_id expected_random_decisions_sha256
    expected_run_ids
)], 'checked reference authority has one closed caller contract');
is($checked_authority->{expected_plan_id},
    'plan/e236297c8b434a9b374d1800112841e00327bdbd5d8d9130440bd20681fbed6e',
    'checked reference authority retains the emitted plan identity');
is($checked_authority->{expected_observation_catalog}{catalog_digest},
    'sha256/f315169a60ab43d9abc747aa42a2ae5fbe2dadd303bc965f0eafb1bbd95989e9',
    'checked reference authority retains the emitted catalog identity');
is($checked_authority->{expected_fixture_id},
    'ahb_subordinate_base_output_arbitration::fixture::base_output_arbitration',
    'checked reference authority retains the selected fixture identity');
is($checked_authority->{expected_domain_id}, 'domain/ahb_bus',
    'checked reference authority retains the selected plan domain identity');
is_deeply($checked_authority->{expected_diagnostic_codes},
    [qw(VIAL_EXPECT_SUCCESS VIAL_EXPECT_ERROR)],
    'checked reference authority retains ordered emitted diagnostic codes');
is($checked_authority->{expected_random_decisions_sha256},
    'eae7108383c875bde35ef072e5762ac9923996a69bcd6c455ae6cc5bfab9c0e2',
    'checked reference authority retains the canonical decision projection');
my $checked_snapshot = clone($checked_authority);
$checked_authority->{expected_plan_id} = 'plan/mutated';
$checked_authority->{expected_run_ids}[0] = 'run/mutated';
$checked_authority->{expected_fixture_id} = 'fixture/mutated';
$checked_authority->{expected_domain_id} = 'domain/mutated';
$checked_authority->{expected_diagnostic_codes}[0] = 'VIAL_MUTATED';
is_deeply(
    FSM::VIAL::Backend::VHDLPortableTraceValidator->checked_reference_authority,
    $checked_snapshot,
    'checked reference authority is returned as a defensive clone');

my @record = (
    record('header', undef, time_record(0, 0), {observation_catalog => $catalog}),
    record('scenario_start', $run_id, time_record(0, 0)),
    record('samples', $run_id, time_record(1, 1), {normalized_bits => '01XZ'}),
    record('samples', $run_id, time_record(2, 1), {normalized_bits => 'ZX10'}),
    record('scenario_end', $run_id, time_record(2, 3)),
    record('footer', undef, time_record(2, 3)),
);
number_records(\@record);

my $valid = validate_records(\@record);
ok($valid->{ok}, 'closed trace-v2 fixture validates');
is_deeply([sort keys %$valid],
    [sort @{FSM::VIAL::Backend::VHDLPortableTraceValidator->result_keys}],
    'validator result shell is closed');
is($valid->{trace}{schema}, 'fsmgen.vial_vhdl_runtime_trace.v2',
    'trace schema is exact revision 2');
is($valid->{trace}{record_count}, 6, 'record total is exact');
is($valid->{trace}{record_counts}{samples}, 2, 'sample total is exact');
is($valid->{trace}{observation_catalog}{catalog_digest}, $catalog->{catalog_digest},
    'validated result retains the authenticated catalog identity');
is($valid->{trace}{observation_catalog}{total_width}, 4,
    'validated result retains the exact normalized width');
is_deeply($valid->{trace}{observation_catalog}{sample_ids},
    ['sample/endpoint/out', 'sample/probe/state'],
    'validated result retains catalog order');
is_deeply($valid->{trace}{scenario_boundaries}, [{
        run_id => $run_id,
        start_time => time_record(0, 0),
        end_time => time_record(2, 3),
    }], 'validated result retains exact ordered scenario boundary times');

my $invocation = FSM::VIAL::Backend::VHDLPortableTraceValidator->validate({
    trace_text => trace_text(\@record),
});
failure($invocation, 'VIAL_VHDL_TRACE_SHAPE_ERROR',
    'open invocation record');

my $foreign_prefix = trace_text(\@record);
$foreign_prefix =~ s/FSMGEN_VIAL_TRACE_V2/FSMGEN_VIAL_TRACE_V1/;
failure(validate_text($foreign_prefix), 'VIAL_VHDL_TRACE_PREFIX_ERROR',
    'foreign prefix');

my $malformed = trace_text(\@record);
$malformed =~ s/}\n\z/\n/;
failure(validate_text($malformed), 'VIAL_VHDL_TRACE_JSON_ERROR',
    'malformed JSON');

my $noncanonical = trace_text(\@record);
$noncanonical =~ s/\{"payload"/\{ "payload"/;
failure(validate_text($noncanonical), 'VIAL_VHDL_TRACE_CANONICAL_ERROR',
    'noncanonical JSON');

my @missing = clone(\@record)->@*;
splice @missing, 3, 1;
number_records(\@missing);
failure(validate_records(\@missing), 'VIAL_VHDL_TRACE_COUNT_ERROR',
    'missing sample record');

my @duplicate = clone(\@record)->@*;
splice @duplicate, 4, 0, clone($duplicate[3]);
number_records(\@duplicate);
failure(validate_records(\@duplicate), 'VIAL_VHDL_TRACE_COUNT_ERROR',
    'duplicate sample record');

my @reordered = clone(\@record)->@*;
$reordered[2]{payload}{logical_time}{cycle} = 2;
$reordered[3]{payload}{logical_time}{cycle} = 1;
failure(validate_records(\@reordered), 'VIAL_VHDL_TRACE_TIME_ERROR',
    'reordered logical time');

my @foreign_plan = clone(\@record)->@*;
$_->{plan_id} = 'plan/foreign' for @foreign_plan;
failure(validate_records(\@foreign_plan), 'VIAL_VHDL_TRACE_ID_ERROR',
    'foreign plan identity');

my @foreign_run = clone(\@record)->@*;
$foreign_run[$_]{run_id} = 'run/foreign' for 1 .. 4;
failure(validate_records(\@foreign_run), 'VIAL_VHDL_TRACE_RUN_ERROR',
    'foreign run identity');

my @bad_digest = clone(\@record)->@*;
$bad_digest[0]{payload}{observation_catalog}{catalog_digest} = 'sha256/' . ('0' x 64);
failure(validate_records(\@bad_digest), 'VIAL_VHDL_TRACE_CATALOG_DIGEST_ERROR',
    'unauthenticated catalog');

my @foreign_catalog = clone(\@record)->@*;
$foreign_catalog[0]{payload}{observation_catalog}{entries}[0]{semantic_id}
    = 'endpoint/foreign';
my $foreign_projection = clone(
    $foreign_catalog[0]{payload}{observation_catalog});
delete $foreign_projection->{catalog_digest};
$foreign_catalog[0]{payload}{observation_catalog}{catalog_digest}
    = 'sha256/' . sha256_hex($json->encode($foreign_projection));
failure(validate_records(\@foreign_catalog), 'VIAL_VHDL_TRACE_CATALOG_ERROR',
    'foreign authenticated catalog');

my @bad_width = clone(\@record)->@*;
$bad_width[2]{payload}{normalized_bits} = '01X';
failure(validate_records(\@bad_width), 'VIAL_VHDL_TRACE_SAMPLE_WIDTH_ERROR',
    'wrong sample width');

my @unknown_symbol = clone(\@record)->@*;
$unknown_symbol[2]{payload}{normalized_bits} = '01UL';
failure(validate_records(\@unknown_symbol), 'VIAL_VHDL_TRACE_SAMPLE_ERROR',
    'unknown normalized symbol');

my @wrong_phase = clone(\@record)->@*;
$wrong_phase[2]{payload}{logical_time}{phase_rank} = 2;
failure(validate_records(\@wrong_phase), 'VIAL_VHDL_TRACE_SAMPLE_PHASE_ERROR',
    'sample outside SAMPLE phase');

my @unknown_phase = clone(\@record)->@*;
$unknown_phase[1]{payload}{logical_time}{phase_rank} = 4;
failure(validate_records(\@unknown_phase), 'VIAL_VHDL_TRACE_TIME_ERROR',
    'logical time outside the closed phase vocabulary');

my @foreign_start = clone(\@record)->@*;
$foreign_start[1]{payload}{logical_time}{static_rank} = 1;
failure(validate_records(\@foreign_start), 'VIAL_VHDL_TRACE_TIME_ERROR',
    'scenario start outside the exact logical-time origin');

my @foreign_end = clone(\@record)->@*;
$foreign_end[4]{payload}{logical_time}{phase_rank} = 0;
failure(validate_records(\@foreign_end), 'VIAL_VHDL_TRACE_TIME_ERROR',
    'scenario end outside the CHECK boundary');

my @unframed = clone(\@record)->@*;
$unframed[1]{record_kind} = 'samples';
$unframed[1]{payload}{normalized_bits} = '01XZ';
$unframed[1]{payload}{logical_time}{phase_rank} = 1;
$unframed[2]{record_kind} = 'scenario_start';
delete $unframed[2]{payload}{normalized_bits};
failure(validate_records(\@unframed), 'VIAL_VHDL_TRACE_RUN_ERROR',
    'sample before scenario start');

my @duplicate_catalog_id = clone(\@record)->@*;
$duplicate_catalog_id[0]{payload}{observation_catalog}{entries}[1]{sample_id}
    = 'sample/endpoint/out';
my $projection = clone($duplicate_catalog_id[0]{payload}{observation_catalog});
delete $projection->{catalog_digest};
$duplicate_catalog_id[0]{payload}{observation_catalog}{catalog_digest}
    = 'sha256/' . sha256_hex($json->encode($projection));
failure(validate_records(\@duplicate_catalog_id), 'VIAL_VHDL_TRACE_CATALOG_ERROR',
    'duplicate catalog sample identity');

done_testing();

sub record {
    my ($kind, $run, $time, $extra) = @_;
    return {
        payload => {logical_time => $time, %{clone($extra // {})}},
        plan_id => $plan_id,
        record_kind => $kind,
        run_id => $run,
        schema => 'fsmgen.vial_vhdl_runtime_trace.v2',
        schema_version => 2,
        sequence => 0,
    };
}

sub time_record {
    my ($cycle, $phase_rank) = @_;
    return {
        cycle => $cycle,
        local_index => 0,
        phase_rank => $phase_rank,
        static_rank => 0,
    };
}

sub number_records {
    my ($records) = @_;
    $records->[$_]{sequence} = $_ for 0 .. $#$records;
}

sub trace_text {
    my ($records) = @_;
    return join('', map { $prefix . $json->encode($_) . "\n" } @$records);
}

sub validate_records {
    my ($records) = @_;
    return validate_text(trace_text($records));
}

sub validate_text {
    my ($text) = @_;
    return FSM::VIAL::Backend::VHDLPortableTraceValidator->validate({
        trace_text => $text,
        expected_plan_id => $plan_id,
        expected_run_ids => [$run_id],
        expected_observation_catalog => $catalog,
        expected_record_counts => \%expected,
    });
}

sub failure {
    my ($result, $code, $label) = @_;
    ok(!$result->{ok}, "$label fails closed");
    is($result->{diagnostics}[0]{code}, $code, "$label has diagnostic $code");
}

sub clone {
    my ($value) = @_;
    return $json->decode($json->encode($value));
}

sources.t/1731-vial-ghdl-capture-evidence-admiss:
#!/usr/bin/env perl

use strict;
use warnings;

use Digest::SHA qw(sha256_hex);
use JSON::PP ();
use Test::More;

use lib 'perl';

use FSM::VIAL::Backend::GHDLLifecycle;

my $JSON = JSON::PP->new->canonical(1);

subtest 'portable capture evidence is rebound to policy and object bytes' => sub {
    my ($session, $record) = portable_tool_state();
    ok(validate_state($session, $record),
        'exact portable tool capture evidence is admitted');

    my $timeout = clone($record);
    $timeout->{evidence}{capture}{timeout_seconds} = 11;
    rejects_state($session, $timeout,
        'foreign portable timeout evidence rejects');

    my $bytes = clone($record);
    $bytes->{evidence}{capture}{output_bytes} = 6;
    rejects_state($session, $bytes,
        'portable output bytes must equal the sealed transcript object');

    my $status = clone($record);
    $status->{evidence}{capture}{ok} = '1';
    rejects_state($session, $status,
        'string success cannot masquerade as supervisor boolean true');

    my $timing = clone($record);
    $timing->{evidence}{capture}{execution_ns} = 19;
    rejects_state($session, $timing,
        'portable capture timing arithmetic is authenticated');

    my $digest = clone($record);
    $digest->{evidence}{version_sha256} = 'f' x 64;
    rejects_state($session, $digest,
        'portable transcript digest must equal the sealed object identity');
};

subtest 'OSVVM capture evidence is rebound to its profile policy' => sub {
    my ($session, $record) = osvvm_analysis_state();
    ok(validate_state($session, $record),
        'exact OSVVM analysis capture evidence is admitted');

    my $limit = clone($record);
    $limit->{evidence}{captures}[0]{capture_limit_bytes} = 65_536;
    rejects_state($session, $limit,
        'foreign OSVVM provider capture ceiling rejects');

    my $empty = clone($record);
    $empty->{evidence}{captures}[0]{first_output_monotonic_ns} = 115;
    $empty->{evidence}{captures}[0]{exec_to_first_output_ns} = 5;
    $empty->{evidence}{captures}[0]{first_output_to_exit_ns} = 15;
    rejects_state($session, $empty,
        'zero-byte OSVVM capture cannot claim first-output timing');

    my $digest = clone($record);
    $digest->{evidence}{output_sha256}[0] = 'f' x 64;
    rejects_state($session, $digest,
        'OSVVM transcript digest must equal its sealed object identity');
};

subtest 'OSVVM runtime and report-set evidence is rebound to sealed objects' => sub {
    my ($session, $record) = osvvm_run_state();
    ok(validate_state($session, $record),
        'exact OSVVM runtime and report-set evidence is admitted');

    my $fixture_limit = clone($record);
    $fixture_limit->{evidence}{fixture_captures}[0]
        {capture_limit_bytes} = 8_388_608;
    rejects_state($session, $fixture_limit,
        'OSVVM fixture capture retains its distinct 64-MiB ceiling');

    my $reports = clone($record);
    $reports->{evidence}{provider_report_sha256}[0] = 'f' x 64;
    rejects_state($session, $reports,
        'OSVVM report-set digest must derive from all sealed report objects');

    my $determinism = clone($record);
    $determinism->{evidence}{deterministic} = JSON::PP::true;
    rejects_state($session, $determinism,
        'one runtime repetition cannot claim deterministic-rerun evidence');
};

done_testing();

sub portable_tool_state {
    my $transcript = object('tool_version_output', 'b', 7);
    return ({
        role => 'qualification',
        storage_context => {containment => 'lifecycle_process_group'},
        validation => {run_repetitions => 1},
        commands => {},
    }, {
        state => 'tool_verified',
        objects => [object('lifecycle_authority', 'a', 11), $transcript],
        evidence => {
            version_sha256 => $transcript->{sha256},
            capture => capture(10, 65_536, 7),
            workspace_files => [],
            workspace_sha256 => sha256_hex($JSON->encode([])),
        },
    });
}

sub osvvm_analysis_state {
    my $provider = object('provider_analysis_output_00', 'd', 0);
    my $generated = object('generated_analysis_output', 'e', 0);
    my $provider_command = ['providers/ghdl', '-a', 'provider.vhd'];
    my $generated_command = ['providers/ghdl', '-a', 'generated.vhd'];
    return ({
        role => 'osvvm_qualification',
        storage_context => {containment => 'lifecycle_process_group'},
        validation => {run_repetitions => 1},
        commands => {
            provider_analyze => [$provider_command],
            analyze_generated => $generated_command,
            provider_reports => [],
            resource_controls => {
                version_timeout_seconds => 10,
                provider_analysis_timeout_seconds_per_source => 120,
                generated_analysis_timeout_seconds => 120,
                elaboration_timeout_seconds => 60,
                execution_timeout_seconds => 30,
                version_capture_limit_bytes => 65_536,
                provider_capture_limit_bytes => 8_388_608,
                fixture_capture_limit_bytes => 67_108_864,
            },
        },
    }, {
        state => 'analyzed',
        objects => [
            object('lifecycle_authority', 'a', 11),
            object('generated_settings', 'b', 13),
            object('tool_version_output', 'c', 7),
            $provider,
            $generated,
        ],
        evidence => {
            command_digests => [command_digest($provider_command)],
            captures => [capture(120, 8_388_608, 0)],
            output_sha256 => [$provider->{sha256}],
            generated_command_digest => command_digest($generated_command),
            generated_capture => capture(120, 8_388_608, 0),
            generated_output_sha256 => $generated->{sha256},
            workspace_files => [],
            workspace_sha256 => sha256_hex($JSON->encode([])),
        },
    });
}

sub osvvm_run_state {
    my @report_name = qw(
        OsvvmRun.yml AlertLogTop_alerts.yml AlertLogTop_cov.yml
        AlertLogTop_sb_slv.yml
    );
    my @report_object = map {
        object("provider_report_0_$_", $_ + 1, $_ + 1)
    } 0 .. $#report_name;
    my @report_identity = map {{
        name => $report_name[$_],
        bytes => $report_object[$_]{bytes},
        sha256 => $report_object[$_]{sha256},
    }} 0 .. $#report_name;
    my $fixture = object('fixture_runtime_output_0', 'd', 5);
    my $provider = object('provider_runtime_output_0', 'e', 6);
    my $resource = osvvm_resources();
    my $fixture_command = ['providers/ghdl', '-r', 'fixture'];
    my $provider_command = ['providers/ghdl', '-r', 'provider_probe'];
    return ({
        role => 'osvvm_qualification',
        storage_context => {containment => 'lifecycle_process_group'},
        validation => {run_repetitions => 1},
        commands => {
            provider_analyze => [[]],
            run_fixture => $fixture_command,
            run_provider_probe => $provider_command,
            provider_reports => [map {{
                name => $_,
                relpath => ".artifacts/tmp/tests/provider_reports/$_",
            }} @report_name],
            resource_controls => $resource,
        },
    }, {
        state => 'ran',
        objects => [
            object('lifecycle_authority', '6', 11),
            object('generated_settings', '7', 13),
            object('tool_version_output', '8', 7),
            object('provider_analysis_output_00', '9', 0),
            object('generated_analysis_output', 'a', 0),
            object('fixture_elaboration_output', 'b', 0),
            object('provider_probe_elaboration_output', 'c', 0),
            $fixture,
            $provider,
            @report_object,
        ],
        evidence => {
            command_digests => {
                fixture => command_digest($fixture_command),
                provider_probe => command_digest($provider_command),
            },
            fixture_captures => [capture(
                $resource->{execution_timeout_seconds},
                $resource->{fixture_capture_limit_bytes},
                $fixture->{bytes},
            )],
            provider_captures => [capture(
                $resource->{execution_timeout_seconds},
                $resource->{provider_capture_limit_bytes},
                $provider->{bytes},
            )],
            fixture_output_sha256 => [$fixture->{sha256}],
            provider_output_sha256 => [$provider->{sha256}],
            provider_report_sha256 => [
                sha256_hex($JSON->encode(\@report_identity)),
            ],
            deterministic => JSON::PP::false,
            workspace_files => [],
            workspace_sha256 => sha256_hex($JSON->encode([])),
        },
    });
}

sub osvvm_resources {
    return {
        version_timeout_seconds => 10,
        provider_analysis_timeout_seconds_per_source => 120,
        generated_analysis_timeout_seconds => 120,
        elaboration_timeout_seconds => 60,
        execution_timeout_seconds => 30,
        version_capture_limit_bytes => 65_536,
        provider_capture_limit_bytes => 8_388_608,
        fixture_capture_limit_bytes => 67_108_864,
    };
}

sub object {
    my ($kind, $hex, $bytes) = @_;
    return {
        kind => $kind,
        sha256 => $hex x 64,
        bytes => $bytes,
        executable => JSON::PP::false,
        relative_path => ".artifacts/tmp/tests/objects/$hex",
    };
}

sub capture {
    my ($timeout, $limit, $bytes) = @_;
    return {
        ok => JSON::PP::true,
        exit_code => 0,
        signal => 0,
        timed_out => JSON::PP::false,
        output_limited => JSON::PP::false,
        exec_failed => JSON::PP::false,
        exec_error => undef,
        started_monotonic_ns => 100,
        exec_handoff_monotonic_ns => 110,
        first_output_monotonic_ns => $bytes ? 120 : undef,
        finished_monotonic_ns => 130,
        spawn_to_exec_ns => 10,
        execution_ns => 20,
        exec_to_first_output_ns => $bytes ? 10 : undef,
        first_output_to_exit_ns => $bytes ? 10 : undef,
        containment => 'lifecycle_process_group',
        timeout_seconds => $timeout,
        capture_limit_bytes => $limit,
        output_bytes => $bytes,
    };
}

sub command_digest {
    return sha256_hex($JSON->encode($_[0]));
}

sub validate_state {
    my ($session, $record) = @_;
    my $ok = eval {
