#!/usr/bin/env perl

use v5.20;
use strict;
use warnings;

use bytes ();
use Cwd qw(realpath);
use Digest::SHA qw(sha256_hex);
use File::Copy qw(copy);
use File::Find qw(find);
use File::Path qw(make_path remove_tree);
use File::Spec;
use FindBin;
use IPC::Open3 qw(open3);
use JSON::PP ();
use POSIX qw(mkfifo);
use Symbol qw(gensym);
use Test::More;

my $root = realpath(File::Spec->catdir($FindBin::Bin, '..'))
    // die "cannot resolve repository root\n";
my $script_relative =
    'scripts/verify_vial_regression_promotion_evidence_transport.pl';
my $bundle_relative =
    'vial/qualification/regression_promotion_gate/evidence-v1';
my $script = repo_path($root, $script_relative);
my $bundle = repo_path($root, $bundle_relative);
my $manifest = repo_path($bundle, 'transport-manifest.json');
my $corpus = repo_path(
    $root,
    '.artifacts/qualification/vial-scale/v2/'
        . 'regression-promotion-corpus-v1',
);
my $qualification = repo_path(
    $root,
    '.artifacts/qualification/vial-scale/v2/'
        . 'regression-promotion-budget-qualification-v1',
);
my $scratch = repo_path(
    $root,
    ".artifacts/tmp/vial-regression-promotion-evidence-transport-tests-$$",
);
my $fixture_root = repo_path($scratch, 'repository');
my $fixture_script = repo_path($fixture_root, $script_relative);
my $fixture_bundle = repo_path($fixture_root, $bundle_relative);
my $fixture_manifest = repo_path($fixture_bundle, 'transport-manifest.json');
my $json = JSON::PP->new->canonical(1)->utf8(1);

die "evidence-transport test scratch path already exists\n"
    if -e($scratch) || -l($scratch);
END {
    remove_tree($scratch) if defined($scratch) && -d($scratch);
}

subtest 'verifier is repository-derived, production-independent, and read-only' => sub {
    ok(-f($script) && !-l($script), 'tracked verifier exists');
    ok(-x($script), 'tracked verifier is executable');
    ok(-f($manifest) && !-l($manifest), 'tracked transport manifest exists');
    my $source = read_raw($script);
    unlike(
        $source,
        qr/^\s*(?:use|require)\s+FSM::/m,
        'verifier imports no FSMGEN production module',
    );
    unlike(
        $source,
        qr/^\s*use\s+lib\b/m,
        'verifier does not expose the production library path',
    );
    unlike(
        $source,
        qr/(?:GetOptions|caller_(?:root|source|evidence)|source_root)/,
        'verifier has no caller-selected evidence seam',
    );

    my $bundle_before = tree_census($bundle);
    my $corpus_before = tree_census($corpus);
    my $qualification_before = tree_census($qualification);
    my $run = run_verifier($script);
    is($run->{status}, 0, 'real tracked evidence transport verifies')
        or diag($run->{stderr});
    is($run->{stderr}, '', 'successful verification is diagnostic-free');
    is_deeply(
        tree_census($bundle),
        $bundle_before,
        'verification leaves every tracked source path and byte unchanged',
    );
    is_deeply(
        tree_census($corpus),
        $corpus_before,
        'verification leaves generated corpus coordinates unchanged',
    );
    is_deeply(
        tree_census($qualification),
        $qualification_before,
        'verification leaves generated qualification coordinates unchanged',
    );
};

subtest 'bounded canonical result exposes the exact transport and source seals' => sub {
    my $first = run_verifier($script);
    my $second = run_verifier($script);
    is($first->{status}, 0, 'first result inspection succeeds')
        or diag($first->{stderr});
    is($second->{status}, 0, 'second result inspection succeeds')
        or diag($second->{stderr});
    is($second->{stdout}, $first->{stdout},
        'verification result is byte-deterministic');
    cmp_ok(bytes::length($first->{stdout}), '<=', 32_768,
        'result stays within its closed output ceiling');
    my $decoded = eval { $json->decode($first->{stdout}) };
    is($@, '', 'result is JSON');
    is($first->{stdout}, $json->encode($decoded) . "\n",
        'result is canonical newline JSON');
    is(
        $decoded->{schema},
        'fsmgen.vial_regression_promotion_gate_evidence_transport_verification.v1',
        'result exposes the independent transport-verification contract',
    );
    is($decoded->{schema_version}, 1, 'verification schema version is exact');
    is(
        $decoded->{bundle_identity},
        'regression-promotion-gate-evidence-transport/'
            . '3b4c486e8e3f853f626d85d2abc713846d0594230d922913c8655be3f682bbc6',
        'selected transport identity is exact',
    );
    is(
        $decoded->{verification_identity},
        'regression-promotion-gate-evidence-transport-verification/'
            . 'ae9c67c927912c96174422bc0ef0b754c25855597c9095be71b85ee767fb55b6',
        'verification result identity is exact',
    );
    is_deeply(
        $decoded->{manifest},
        {
            bytes => 8_725,
            sha256 =>
                'd20cae857a6799c1ea54a830d72552cb0587ea647018761007089587b21d94f7',
        },
        'canonical manifest byte and digest seal is exact',
    );
    is_deeply(
        $decoded->{summary},
        {
            manifest_file_count => 1,
            payload_file_count => 15,
            payload_total_bytes => 7_012_284,
            corpus_file_count => 13,
            qualification_file_count => 2,
        },
        'result exposes the closed manifest/payload census',
    );
    is(
        $decoded->{source_seals}{corpus}{file_set_sha256},
        'dc5b315b827389eb466776716f6851cdd9ddd13b2f1aec441f8a51b7d72dc66f',
        'corpus file-set seal is exact',
    );
    is(
        $decoded->{source_seals}{qualification}{file_set_sha256},
        '28ba972c3f8cbcc00d1d32c9db0d4015de57f0df49d11d7076262cd050069095',
        'qualification file-set seal is exact',
    );
    is(scalar(@{$decoded->{files}}), 15,
        'result inventories all fifteen ordered payloads');
    is_deeply(
        [map { $_->{ordinal} } @{$decoded->{files}}[2 .. 12]],
        [1 .. 11],
        'profile payload order is exact',
    );
};

subtest 'closed invocation rejects caller evidence selection' => sub {
    for my $argument ('foreign-root', '--source', '--evidence') {
        my $run = run_verifier($script, $argument);
        isnt($run->{status}, 0, "$argument rejects");
        like(
            $run->{stderr},
            qr/^usage: scripts\/verify_vial_regression_promotion_evidence_transport[.]pl/m,
            "$argument reports the closed invocation",
        );
        is($run->{stdout}, '', "$argument emits no result");
        cmp_ok(bytes::length($run->{stderr}), '<=', 4_096,
            "$argument diagnostic is bounded");
    }
};

subtest 'copied hostile transport mutations fail closed' => sub {
    make_path(repo_path($fixture_root, 'scripts'));
    copy($script, $fixture_script)
        or die "cannot copy evidence-transport verifier: $!\n";
    chmod 0755, $fixture_script
        or die "cannot make copied verifier executable: $!\n";
    copy_tree($bundle, $fixture_bundle);

    my $baseline = run_verifier($fixture_script);
    is($baseline->{status}, 0, 'copied baseline verifies')
        or diag($baseline->{stderr});
    my $manifest_bytes = read_raw($fixture_manifest);
    my $payload = repo_path(
        $fixture_bundle,
        'payload/regression-promotion-corpus-v1/complete/corpus-manifest.json',
    );
    my $payload_bytes = read_raw($payload);

    reject_manifest_mutation(
        'extra manifest key',
        sub { $_[0]{foreign} = 1 },
        qr/transport manifest keys changed/,
    );
    reject_manifest_mutation(
        'manifest schema',
        sub { $_[0]{schema} =~ s/[.]v1\z/.v2/ },
        qr/transport manifest schema changed/,
    );
    reject_manifest_mutation(
        'entry order',
        sub {
            my $first = $_[0]{entries}[0];
            $_[0]{entries}[0] = $_[0]{entries}[1];
            $_[0]{entries}[1] = $first;
        },
        qr/transport manifest entry order changed/,
    );
    reject_manifest_mutation(
        'unsafe source path',
        sub { $_[0]{entries}[0]{source_relative_path} = '../evidence.json' },
        qr/transport source path is unsafe/,
    );
    reject_manifest_mutation(
        'destination mapping',
        sub { $_[0]{entries}[0]{destination_relative_path} .= '.foreign' },
        qr/transport source\/destination mapping changed/,
    );
    reject_manifest_mutation(
        'entry byte count',
        sub { ++$_[0]{entries}[0]{bytes} },
        qr/transport manifest aggregate byte count changed/,
    );
    reject_manifest_mutation(
        'entry digest',
        sub { substr($_[0]{entries}[0]{sha256}, 0, 1, '0') },
        qr/transport manifest content identity changed/,
    );
    reject_manifest_mutation(
        'bundle identity',
        sub { substr($_[0]{bundle_identity}, -1, 1, '0') },
        qr/transport manifest content identity changed/,
    );
    reject_manifest_mutation(
        'source seal',
        sub { ++$_[0]{source_seals}{corpus}{file_count} },
        qr/transport manifest source seals changed/,
    );

    write_raw($fixture_manifest, substr($manifest_bytes, 0, -1) . ' ');
    reject_current(
        'noncanonical manifest',
        qr/transport manifest is not canonical newline JSON/,
    );
    write_raw($fixture_manifest, $manifest_bytes);

    write_raw($payload, substr($payload_bytes, 0, -1) . ' ');
    reject_current(
        'noncanonical payload',
        qr/evidence payload is not canonical newline JSON/,
    );
    write_raw($payload, $payload_bytes);

    my $payload_document = $json->decode($payload_bytes);
    $payload_document->{schema} =~ s/[.]v1\z/.v2/;
    my $schema_mutation = $json->encode($payload_document) . "\n";
    is(bytes::length($schema_mutation), bytes::length($payload_bytes),
        'payload schema mutation preserves the admitted byte count');
    write_raw($payload, $schema_mutation);
    reject_current(
        'payload schema',
        qr/evidence payload SHA-256 changed/,
    );
    write_raw($payload, $payload_bytes);

    write_raw($payload, $payload_bytes . 'x');
    reject_current(
        'payload byte count',
        qr/evidence payload byte count changed/,
    );
    write_raw($payload, $payload_bytes);

    my $extra = repo_path($fixture_bundle, 'payload/foreign.json');
    write_raw($extra, "{}\n");
    reject_current('extra payload', qr/evidence transport file census changed/);
    unlink($extra) or die "cannot remove copied extra payload: $!\n";

    my $held = repo_path($scratch, 'held-payload.json');
    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    reject_current('missing payload', qr/evidence transport file census changed/);
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    symlink($fixture_manifest, $payload)
        or die "cannot create copied payload symlink: $!\n";
    reject_current('payload symlink', qr/evidence transport contains a symlink/);
    unlink($payload) or die "cannot remove copied payload symlink: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    link($held, $payload) or die "cannot create copied payload hardlink: $!\n";
    reject_current('payload hardlink', qr/evidence transport contains an aliased file/);
    unlink($payload) or die "cannot remove copied payload hardlink: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    rename($payload, $held) or die "cannot hold copied payload: $!\n";
    mkfifo($payload, 0600) or die "cannot create copied payload FIFO: $!\n";
    reject_current('payload FIFO', qr/evidence transport contains a non-regular node/);
    unlink($payload) or die "cannot remove copied payload FIFO: $!\n";
    rename($held, $payload) or die "cannot restore copied payload: $!\n";

    my $restored = run_verifier($fixture_script);
    is($restored->{status}, 0, 'copied baseline verifies after every restoration')
        or diag($restored->{stderr});
    is($restored->{stdout}, $baseline->{stdout},
        'copied verification identity is restored exactly');
};

done_testing();

sub reject_manifest_mutation {
    my ($label, $mutate, $diagnostic) = @_;
    my $original = read_raw($fixture_manifest);
    my $document = $json->decode($original);
    $mutate->($document);
    write_raw($fixture_manifest, $json->encode($document) . "\n");
    reject_current($label, $diagnostic);
    write_raw($fixture_manifest, $original);
}

sub reject_current {
    my ($label, $diagnostic) = @_;
    my $run = run_verifier($fixture_script);
    isnt($run->{status}, 0, "$label rejects");
    like($run->{stderr}, $diagnostic, "$label reports its failing boundary");
    is($run->{stdout}, '', "$label emits no verification result");
    cmp_ok(bytes::length($run->{stderr}), '<=', 4_096,
        "$label diagnostic is bounded");
}

sub run_verifier {
    my ($executable, @arguments) = @_;
    my $error = gensym;
    my $pid = open3(
        my $input,
        my $output,
        $error,
        $^X,
        $executable,
        @arguments,
    );
    close $input;
    local $/;
    my $stdout = <$output> // '';
    my $stderr = <$error> // '';
    close $output;
    close $error;
    waitpid($pid, 0) == $pid or die "cannot wait for verifier\n";
    return {
        status => $? == -1 ? -1 : $? >> 8,
        signal => $? & 127,
        stdout => $stdout,
        stderr => $stderr,
    };
}

sub copy_tree {
    my ($source, $destination) = @_;
    find({
        no_chdir => 1,
        wanted => sub {
            my $path = $File::Find::name;
            die "copied fixture source contains a symlink\n" if -l($path);
            my $relative = File::Spec->abs2rel($path, $source);
            my $target = $relative eq '.'
                ? $destination
                : repo_path($destination, $relative);
            if (-d($path)) {
                make_path($target);
                return;
            }
            die "copied fixture source contains a non-file\n" unless -f($path);
            copy($path, $target) or die "cannot copy hostile fixture path: $!\n";
        },
    }, $source);
}

sub tree_census {
    my ($base) = @_;
    my @entries;
    find({
        no_chdir => 1,
        wanted => sub {
            my $path = $File::Find::name;
            my @stat = lstat($path);
            die "cannot stat verifier test path\n" unless @stat;
            my $relative = File::Spec->abs2rel($path, $base);
            $relative = '' if $relative eq '.';
            $relative =~ s{\\}{/}g;
            my $entry = {
                relative_path => $relative,
                device => $stat[0],
                inode => $stat[1],
                mode => $stat[2],
                links => $stat[3],
                owner => $stat[4],
                bytes => $stat[7],
                type => -l _ ? 'symlink'
                    : -d _ ? 'directory'
                    : -f _ ? 'file' : 'other',
            };
            $entry->{sha256} = sha256_hex(read_raw($path)) if -f _;
            push @entries, $entry;
        },
    }, $base);
    return [sort {
        $a->{relative_path} cmp $b->{relative_path}
    } @entries];
}

sub repo_path {
    my ($base, @parts) = @_;
    return File::Spec->catfile($base, map { split m{/} } @parts);
}

sub read_raw {
    my ($path) = @_;
    open my $fh, '<:raw', $path or die "cannot read verifier test path\n";
    local $/;
    my $bytes = <$fh> // '';
    close $fh or die "cannot close verifier test path\n";
    return $bytes;
}

sub write_raw {
    my ($path, $bytes) = @_;
    open my $fh, '>:raw', $path or die "cannot write verifier test path\n";
    print {$fh} $bytes or die "cannot write verifier test path\n";
    close $fh or die "cannot close verifier test path\n";
}

sources.t/1816-rust-proxy-integration.t:
#!/usr/bin/env perl
use strict;
use warnings;

use Cwd qw(abs_path);
use File::Basename qw(dirname);
use File::Path qw(make_path remove_tree);
use File::Spec;
use JSON::PP qw(decode_json encode_json);
use Test::More;
use lib 'perl', 't/lib';
use FSM::ProjectDataLocality qw(repository_root);
use FSM::Test::ProjectDataLocality;

# Execute only the extracted construction/assertion/retirement control, with
# inert builder and process observations. No original test or compiler runs.
my $root = repository_root();
open my $source_fh, '<', 't/1669-task-acceptance-fixture-runtime.t' or die $!;
my $source = do { local $/; <$source_fh> };
close $source_fh or die $!;
my ($body) = $source =~ /(subtest 'Rust parity rejects unresolved.*?)(?=subtest 'legacy RAM-guard)/s;
my ($retire) = $source =~ /(sub retire_rust_proxy_workspace \{.*?)(?=sub capture_error)/s;
my ($writer) = $source =~ /(sub write_executable \{.*?)(?=sub slurp)/s;
die 'original integration boundaries are missing' unless $body && $retire && $writer;

{
    package RustProxyIntegrationModel;
    our ($root, $scenario, @assertions, @diagnostics, @preparations, @watchers, @workspaces,
         @prepared_results, @events);
    sub ok { push @assertions, [$_[0] ? 1 : 0, $_[1]]; return $_[0]; }
    sub is { return ok(defined($_[0]) && defined($_[1]) && $_[0] eq $_[1], $_[2]); }
    sub fail { return ok(0, $_[0]); }
    sub diag {
        push @diagnostics, @_;
        for my $message (@_) {
            next if ref($message) || $message !~ /^Rust proxy preparation: (.*)\z/s;
            my $receipt = eval { JSON::PP::decode_json($1) };
            my $mode = ref($receipt) eq 'HASH' ? $receipt->{mode} : 'invalid';
            push @events, ['receipt', $mode];
        }
    }
    sub explain { return @_; }
    sub subtest { $_[1]->(); }
    sub cleanup { return {leader_started => 1, leader_reaped => 1, group_gone => 1}; }
    sub prepare_rust_proxy {
        my ($workspace, $mode, @extra) = @_;
        die 'unexpected preparation arguments' if @extra || ref($workspace)
            || ($mode ne 'proxy_nonzero' && $mode ne 'proxy_decoy');
        push @preparations, [$workspace, $mode];
        push @workspaces, $workspace;
        push @events, ['prepare', $mode];
        my $result = {
            schema => 'fsmgen.test.rust_proxy_fixture.v1', ok => 0,
            status => 'timed_out', failure_stage => 'compile',
            diagnostic => "controlled preparation failure\n",
            implementation => $scenario eq 'perl' ? 'perl' : 'native',
            selection_reason => 'controlled_selection',
            executable => undef, sources => [], compilation => undef,
            compilation_argv => undef,
        };
        if ($scenario eq 'prepare_failure') {
            push @prepared_results, {mode => $mode, prepared => {%$result}};
            return $result;
        }
        my $bin = "$workspace/rust-tools";
        mkdir($bin, 0700) or die $!;
        open my $fh, '>', "$bin/rustup" or die $!;
        print {$fh} "inert $mode fixture\n" or die $!;
        close $fh or die $!;
        chmod 0500, "$bin/rustup" or die $!;
        $result->{ok} = 1;
        $result->{status} = 'success';
        $result->{failure_stage} = undef;
        $result->{diagnostic} = 'controlled fixture prepared';
        $result->{executable} = File::Spec->abs2rel("$bin/rustup", $root);
        # Opaque test identities exercise lossless transfer, not native custody.
        $result->{sources} = [{path => $result->{executable}, device => 7, inode => 11,
                              size_bytes => 23, sha256 => 'a' x 64}];
        if ($scenario ne 'perl') {
            $result->{compilation} = {ok => 1, status => 'success', cleanup => cleanup()};
            $result->{compilation_argv} = ['controlled-clang', '-o', $result->{executable}];
            $result->{compilation}{cleanup}{group_gone} = 0 if $scenario eq 'compiler_group';
        }
        push @prepared_results, JSON::PP::decode_json(JSON::PP::encode_json({mode => $mode, prepared => $result}));
        return $result;
    }
    sub supervise_process {
        my %args = @_;
        my ($perl, $include, $test_include, $probe, $bin) = @{$args{argv}};
        die 'changed wrapper argv' unless @{$args{argv}} == 5
            && $perl eq Cwd::abs_path($^X) && $include eq '-Iperl' && $test_include eq '-It/lib'
            && $probe eq File::Basename::dirname($bin) . '/rust-tool-resolution';
        die 'changed wrapper policy' unless $args{cwd} eq $root
            && $args{bounds}{timeout_seconds} == 20 && $args{bounds}{capture_limit_bytes} == 65_536
            && $args{schema} eq 'fsmgen.test.rust_tool_resolution_probe.v1'
            && $args{stage} eq 'probe' && $args{containment} eq 'rust_tool_resolution_probe_group';
        my $mode = -d "$bin/cargo" ? 'directory' : $preparations[-1][1];
        die 'proxy canonical identity changed' if $mode ne 'directory'
            && (!-l "$bin/cargo" || Cwd::abs_path("$bin/cargo") ne "$bin/rustup");
        push @watchers, [$mode, \%args];
        push @events, ['watcher', $mode];
        push @workspaces, File::Basename::dirname($bin);
        my $cleanup = cleanup();
        $cleanup->{leader_started} = 0 if $mode eq 'directory';
        $cleanup->{leader_reaped} = 0 if $mode eq 'directory';
        my $status = $mode eq 'proxy_nonzero' ? 'nonzero_exit' : 'invocation_error';
        my $stage = $mode eq 'proxy_decoy' ? 'tool_admission' : 'tool_resolution';
        my $result = {ok => 0, status => $status, failure_stage => $stage,
                      stages => [{stage => $stage, cleanup => $cleanup}]};
        my $outer = {ok => 1, cleanup => cleanup()};
        if ($mode ne 'directory') {
            $cleanup->{group_gone} = 0 if $scenario eq 'inner_group';
            $cleanup->{leader_reaped} = 0 if $scenario eq 'inner_unreaped';
            delete $cleanup->{leader_started} if $scenario eq 'missing_cleanup';
            $cleanup->{leader_started} = undef if $scenario eq 'undefined_cleanup';
            $cleanup->{group_gone} = 'unknown' if $scenario eq 'nonboolean_cleanup';
            $outer->{cleanup}{group_gone} = 0 if $scenario eq 'outer_group';
            $result->{stages} = [] if $scenario eq 'empty_stages';
            $result->{status} = 'success' if $scenario eq 'wrong_status';
            push @{$result->{stages}}, {stage => 'cargo_build', cleanup => cleanup()}
                if $scenario eq 'unexpected_build';
        }
        $outer->{stdout} = $scenario eq 'bad_json' && $mode ne 'directory'
            ? '{broken' : JSON::PP::encode_json($result);
        return $outer;
    }
}

my $case = 0;
for my $scenario (qw(native perl prepare_failure compiler_group inner_group inner_unreaped
                     missing_cleanup undefined_cleanup nonboolean_cleanup outer_group
                     empty_stages bad_json wrong_status unexpected_build)) {
    subtest $scenario => sub {
        $RustProxyIntegrationModel::root = $root;
        $RustProxyIntegrationModel::scenario = $scenario;
        @RustProxyIntegrationModel::assertions = ();
        @RustProxyIntegrationModel::diagnostics = ();
        @RustProxyIntegrationModel::preparations = ();
        @RustProxyIntegrationModel::watchers = ();
        @RustProxyIntegrationModel::workspaces = ();
        @RustProxyIntegrationModel::prepared_results = ();
        @RustProxyIntegrationModel::events = ();
        my $package = 'RustProxyIntegrationCase' . ++$case;
        my $aliases = join "\n", map { "*$_ = \\&RustProxyIntegrationModel::$_;" }
            qw(ok is fail diag explain subtest prepare_rust_proxy supervise_process);
        my $program = "package $package; BEGIN { $aliases }\n" . <<'PRELUDE';
use Cwd qw(abs_path);
use File::Basename qw(dirname);
use File::Path qw(make_path remove_tree);
use File::Spec;
use File::Temp ();
use JSON::PP qw(decode_json);
use FSM::ProjectDataLocality qw(ensure_project_artifact_dir);
my $repo_root = $RustProxyIntegrationModel::root;
my $perl = abs_path($^X);
PRELUDE
        my $finished = eval "$program\n$body\n$retire\n$writer\n1;";
        my $error = $@;
        my %workspaces = map { $_ => 1 } @RustProxyIntegrationModel::workspaces;
        my @retained = grep { -d $_ } keys %workspaces;
        # These paths had only inert observations; this control owns their cleanup.
        remove_tree($_) for @retained;
        ok($finished, 'isolated original control executes') or diag $error;
        my @failed = grep { !$_->[0] } @RustProxyIntegrationModel::assertions;
        my $success = $scenario eq 'native' || $scenario eq 'perl';
        is(scalar(@failed) == 0 ? 1 : 0, $success ? 1 : 0, 'independent outcome distinguishes hostile inputs');
        my $retains = !$success && $scenario ne 'wrong_status' && $scenario ne 'unexpected_build';
        is(scalar(@retained), $retains ? 1 : 0, 'only unproved lifecycle retains its mode workspace');
        is(scalar(@RustProxyIntegrationModel::preparations), $retains ? 1 : 2,
            'each attempted proxy mode is prepared once without fallback or retry');
        is(scalar(@RustProxyIntegrationModel::watchers), $scenario eq 'prepare_failure' ? 1 : $retains ? 2 : 3,
            'preparation failure cannot launch its wrapper or advance to another mode');
        my @receipts = map { /^Rust proxy preparation: (.*)\z/s ? $1 : () }
            grep { !ref($_) } @RustProxyIntegrationModel::diagnostics;
        my @expected_receipts = map { JSON::PP->new->ascii->canonical->encode($_) }
            @RustProxyIntegrationModel::prepared_results;
        is_deeply(\@receipts, \@expected_receipts,
            'every preparation retains its complete canonical mode-linked receipt');
        my @expected_events = (['watcher', 'directory']);
        for my $mode ($retains ? ('proxy_nonzero') : qw(proxy_nonzero proxy_decoy)) {
            push @expected_events, ['prepare', $mode], ['receipt', $mode];
            push @expected_events, ['watcher', $mode] unless $scenario eq 'prepare_failure';
        }
        is_deeply(\@RustProxyIntegrationModel::events, \@expected_events,
            'receipt follows preparation and precedes any wrapper launch');
        ok(!grep(-e $_, keys %workspaces), 'controlled fixture cleanup leaves no workspace');
    };
}
done_testing();

sources.t/1832-process-coordinator-admission.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Scalar::Util qw(refaddr);
use FindBin;
use lib "$FindBin::Bin/../perl", "$FindBin::Bin/lib";
use FSM::Test::ProjectDataLocality;
use FSM::Support::ProcessSupervisor::Admission ();

# Model-only test. No fabricated numeric process identity reaches a syscall.
my $class = 'FSM::Support::ProcessSupervisor::Admission';
my $now = '100000000000';
no warnings 'redefine';
local *FSM::Support::ProcessSupervisor::Admission::_now_ns = sub { $now };
local *FSM::Support::ProcessSupervisor::GatedPair::prepare = sub { die 'native preparation forbidden' };
local *FSM::Support::ProcessSupervisor::GatedPair::start = sub { die 'native start forbidden' };
sub ledger { return FSM::Support::ProcessSupervisor::Admission::prepare(
    started_ns => '99000000000', timeout_seconds => 20) }
sub rejects {
    my ($code, $pattern, $label) = @_;
    my $ok = eval { $code->(); 1 };
    ok(!$ok && $@ =~ $pattern, $label) or diag($@ || 'unexpected acceptance');
}
sub active {
    my ($ledger, $grant) = @_;
    $ledger->begin_prepare($grant);
    $ledger->prepared($grant, 15);
    $ledger->begin_start($grant);
    $ledger->activate($grant, 7);
}
sub nested {
    my ($ledger, $parent, %extra) = @_;
    return $ledger->reserve_job(parent => $parent, started_ns => $now,
        timeout_seconds => 30, %extra);
}
sub settle {
    my ($ledger, $grant) = @_;
    $ledger->cancel($grant);
    $ledger->release_resources($grant, children => 0, descriptors => 0);
    $ledger->finish($grant);
}

subtest 'original timing and retained one-use transitions' => sub {
    my $l = ledger(); my $r = $l->root;
    is_deeply($l->describe($r), {id => 1, parent => 0, depth => 1,
        started_ns => '99000000000', timeout_seconds => '20', deadline_ns => '119000000000',
        phase => 'reserved', accepting => 1, children => 0, descriptors => 0,
        reserved_children => 2, reserved_descriptors => 16}, 'root retains literal original timing and peak charges');
    is_deeply($l->usage, {jobs => 1, children => 0, descriptors => 0,
        reserved_children => 2, reserved_descriptors => 16,
        charged_children => 2, charged_descriptors => 16}, 'unallocated capacity is distinct from actual effects');
    rejects(sub { nested($l, $r) }, qr/parent is not active/, 'unstarted parent cannot admit');
    rejects(sub { $l->begin_start($r) }, qr/expected prepared/, 'fork cannot precede preparation');
    $l->begin_prepare($r);
    rejects(sub { $l->begin_prepare($r) }, qr/expected reserved/, 'preparation is single-use');
    $l->prepared($r, 15);
    is($l->usage->{reserved_descriptors}, 0, 'prepared effects replace their reservation');
    is($l->usage->{descriptors}, 15, 'actual prepared descriptors remain charged');
    rejects(sub { $l->prepared($r, 15) }, qr/expected preparing/, 'cannot replay preparation completion');
    rejects(sub { $l->release_resources($r, children => 0, descriptors => 0) }, qr/only after launch/, 'future forks keep their full child reservation');
    $l->begin_start($r);
    rejects(sub { $l->begin_start($r) }, qr/expected prepared/, 'start grant is single-use');
    $l->activate($r, 7);
    is_deeply($l->usage, {jobs => 1, children => 2, descriptors => 7,
        reserved_children => 0, reserved_descriptors => 0,
        charged_children => 2, charged_descriptors => 7}, 'ready effects have no outstanding allocation credit');
    my $c = nested($l, $r);
    is_deeply([@{$l->describe($c)}{qw(id parent depth started_ns deadline_ns)}],
        [2, 1, 2, '100000000000', '119000000000'], 'nested deadline clips to original ancestor');
    active($l, $c);
    my $g = nested($l, $c, timeout_seconds => 2);
    is($l->describe($g)->{deadline_ns}, '102000000000', 'shorter child wall is never extended');
    $l->describe($g)->{deadline_ns} = '999999999999';
    is($l->describe($g)->{deadline_ns}, '102000000000', 'projection mutation grants no renewed wall');
    $now = '102000000000';
    rejects(sub { $l->begin_prepare($g) }, qr/deadline expired/, 'inclusive expiry prevents allocation');
    $now = '100000000000';
};

subtest 'deadline validation and expiry after retained preparation' => sub {
    for my $case (
        ['100000000001', 20, qr/future/], ['99000000000', 1, qr/expired/],
        ['099000000000', 20, qr/noncanonical/], ['99000000000', 0, qr/positive/],
    ) {
        rejects(sub { FSM::Support::ProcessSupervisor::Admission::prepare(
            started_ns => $case->[0], timeout_seconds => $case->[1]) }, $case->[2], 'invalid original invocation rejects');
    }
    my $l = ledger(); my $r = $l->root;
    $l->begin_prepare($r); $now = '119000000000';
    $l->prepared($r, 15);
    rejects(sub { $l->begin_start($r) }, qr/expired/, 'effects can be recorded after expiry but cannot start');
    is($l->usage->{charged_descriptors}, 15, 'expiry does not erase retained effects');
    settle($l, $r); $l->retire($r);
    $now = '100000000000';
    $l = ledger(); $r = $l->root; active($l, $r);
    rejects(sub { nested($l, $r, started_ns => '98000000000') }, qr/precedes its parent/, 'child cannot predate logical parent');
    my $c = nested($l, $r, timeout_seconds => 1);
    $l->begin_prepare($c); $l->prepared($c, 15); $l->begin_start($c);
    $now = '101000000000';
    rejects(sub { $l->activate($c, 7) }, qr/expired/, 'handoff cannot activate an expired grant');
    $l->cancel($c);
    is($l->usage->{reserved_children}, 2, 'interrupted start retains possible child effects until owner reconciles');
    settle($l, $c); $l->retire($c);
    $now = '119000000000';
    rejects(sub { nested($l, $r) }, qr/expired/, 'expired ancestor cannot admit a fresh child');
    $now = '18446744073709551615';
    rejects(sub { FSM::Support::ProcessSupervisor::Admission::prepare(
        started_ns => $now, timeout_seconds => 1) }, qr/exceeds wire range/, 'u64 deadline cannot overflow');
    $now = '100000000000';
};

subtest 'grant identity, creator custody and monotonic retirement' => sub {
    my $l = ledger(); my $r = $l->root; my $other = ledger();
    rejects(sub { $other->describe($r) }, qr/foreign, copied/, 'job grant belongs to one ledger');
    my $copy = bless {%$r}, ref($r);
    rejects(sub { $l->begin_prepare($copy) }, qr/foreign, copied/, 'copied grant cannot allocate');
    rejects(sub { $l->describe(1) }, qr/invalid job grant/, 'wire identity alone grants no authority');
    my $clone = bless {%$l}, ref($l);
    rejects(sub { $clone->root }, qr/copied ledger/, 'copied owner cannot share authority');
    { local $l->{owner_pid} = $$ + 1;
      rejects(sub { $l->root }, qr/inherited ledger/, 'inherited-owner model rejects before native operations'); }
    active($l, $r);
    my $a = nested($l, $r); active($l, $a);
    my $b = nested($l, $a); my $sibling = nested($l, $r);
    $l->cancel($a);
    is($l->describe($b)->{phase}, 'closing', 'cancellation revokes entire retained subtree');
    is($l->describe($sibling)->{phase}, 'reserved', 'unrelated branch retains its state');
    rejects(sub { $l->begin_prepare($b) }, qr/revoked/, 'cancel after record before allocation forbids preparation');
    rejects(sub { nested($l, $a) }, qr/revoked/, 'cancelled parent cannot admit');
    rejects(sub { $l->finish($a) }, qr/resources remain/, 'finish cannot forget resources');
    $l->release_resources($a, children => 0, descriptors => 0);
    rejects(sub { $l->release_resources($a, children => 1, descriptors => 0) }, qr/out of range|noncanonical/, 'released child capacity cannot be reclaimed');
    rejects(sub { $l->finish($a) }, qr/descendant outcome/, 'parent waits for retained descendant outcome');
    settle($l, $b);
    rejects(sub { $l->finish($a) }, qr/descendant outcome/, 'closed child still owns delivery slot');
    is($l->usage->{jobs}, 4, 'result pending still consumes job capacity');
    $l->retire($b); $l->finish($a); $l->retire($a);
    rejects(sub { $l->describe($b) }, qr/retired job grant/, 'retired job grant is stale');
    my $later = nested($l, $r);
    is($l->describe($later)->{id}, 5, 'retirement never recycles a wire identity');
    is_deeply([map { $l->describe($_)->{id} } @{$l->grants}], [1, 4, 5], 'owner can recover every still-retained grant');
    $l->cancel($r);
    settle($l, $_), $l->retire($_) for ($later, $sibling);
    settle($l, $r); $l->retire($r);
    is($l->usage->{jobs}, 0, 'child-first delivery retirement empties the ledger');
    rejects(sub { $l->reserve_descriptors(1) }, qr/root is retired/, 'retired run cannot reacquire resources');
};

subtest 'independent inclusive capacity census and closed outcome pressure' => sub {
    my $l = ledger(); my @jobs = ($l->root); active($l, $jobs[0]);
    for (2 .. 8) { push @jobs, nested($l, $jobs[-1]); active($l, $jobs[-1]); }
    is_deeply([@{$l->usage}{qw(jobs children charged_children descriptors)}],
        [8, 16, 16, 56], 'eight retained pairs independently account for sixteen children');
    is($l->describe($jobs[-1])->{depth}, 8, 'inclusive logical depth is eight');
    rejects(sub { nested($l, $jobs[-1]) }, qr/depth exhausted/, 'ninth logical level rejects');
    rejects(sub { nested($l, $jobs[0]) }, qr/job capacity exhausted/, 'ninth job rejects even at shallow depth');
    settle($l, $jobs[-1]);
    is($l->usage->{children}, 14, 'exact declared closure releases its two child charges');
    rejects(sub { nested($l, $jobs[0]) }, qr/job capacity exhausted/, 'zero-resource outcome does not reopen job slot');
    $l->retire(pop @jobs);
    my $next = nested($l, $jobs[0]);
    is($l->describe($next)->{id}, 9, 'settled delivery reopens capacity with a fresh identity');

    my $d = ledger(); my $r = $d->root;
    my $external = $d->reserve_descriptors(112);
    is($d->usage->{charged_descriptors}, 128, 'root peak plus external reservations reaches inclusive descriptor bound');
    rejects(sub { $d->reserve_descriptors(1) }, qr/capacity exhausted/, 'one excess descriptor rejects before allocation');
    is(refaddr($d->descriptor_grants->[0]), refaddr($external), 'lost-return descriptor reservation is recoverable');
    my $forged = bless {}, ref($external);
    rejects(sub { $d->release_descriptors($forged, 0) }, qr/foreign, copied/, 'copied descriptor grant rejects');
    rejects(sub { $l->release_descriptors($external, 0) }, qr/foreign, copied/, 'descriptor grant cannot move to another owner');
    $d->descriptors_prepared($external, 111);
    is_deeply([@{$d->usage}{qw(descriptors reserved_descriptors charged_descriptors)}],
        [111, 16, 127], 'external effects are separate from job preparation credit');
    rejects(sub { $d->descriptors_prepared($external, 111) }, qr/already prepared/, 'external preparation cannot replay');
    rejects(sub { $d->release_descriptors($external, 112) }, qr/out of range/, 'external usage cannot grow without fresh credit');
    active($d, $r);
    rejects(sub { nested($d, $r) }, qr/descriptor capacity/, 'job admission includes external actual descriptors');
    $d->release_descriptors($external, 0);
    rejects(sub { $d->release_descriptors($external, 0) }, qr/retired descriptor/, 'released descriptor grant is stale');
    rejects(sub { $d->reserve_descriptors(0) }, qr/positive/, 'empty descriptor grant rejects');
    rejects(sub { $d->reserve_descriptors(129) }, qr/out of range/, 'single reservation beyond the bound rejects');
    my $cleanup = $d->reserve_descriptors(2);
    settle($d, $r);
    rejects(sub { $d->retire($r) }, qr/run descriptor/, 'run cannot retire while endpoint resources are charged');
    my $scratch = $d->reserve_descriptors(1);
    $d->release_descriptors($scratch, 0); $d->release_descriptors($cleanup, 0); $d->retire($r);
    is($d->usage->{charged_descriptors}, 0, 'bounded cleanup credit also retires exactly');
};

subtest 'identity exhaustion is final even after retirement' => sub {
    my $l = ledger(); my $r = $l->root; active($l, $r);
    $l->{next_id} = 4_294_967_295; # model seam; never a native PID or PGID
    my $last = nested($l, $r);
    is($l->describe($last)->{id}, 4_294_967_295, 'last u32 identity is usable');
    settle($l, $last); $l->retire($last);
    rejects(sub { nested($l, $r) }, qr/identity exhausted/, 'u32 exhaustion never wraps or reuses');
    is($l->usage->{jobs}, 1, 'exhaustion publishes no partial record or resource charge');
};

done_testing;

sources.t/1880-vial-public-source-inspection.t:
#!/usr/bin/env perl
use strict;
use warnings;
use Cwd qw(abs_path);
use Digest::SHA qw(sha256_hex);
use File::Find;
use FindBin;
use JSON::PP ();
use Test::More;
use lib "$FindBin::Bin/../perl";
use FSM::ProjectDataLocality qw(create_project_tempdir);
use FSM::Support::VIALToolingContract qw(build_vial_tooling_contract);
use FSM::VIAL::SourceInspection;
use FSM::VIAL::Tool qw(execute_vial_tool_request check_vial_source_file);
use FSM::VIAL::ToolCLI;

my $portable=FSM::VIAL::Tool->can('inspect_vial_source');
my $filesystem=FSM::VIAL::Tool->can('inspect_vial_source_file');
ok($portable,'portable source inspection API exists');
ok($filesystem,'filesystem source inspection API exists');
if (!$portable || !$filesystem) { done_testing();exit 0 }
my $repo=abs_path("$FindBin::Bin/..");
my $workspace=create_project_tempdir(purpose=>'vial-public-source-inspection');
my $id='inspect.vial';
my $json=JSON::PP->new->canonical;
my %base=map {$_=>read_file("$repo/vial/ahb_subordinate_base_output_arbitration".($_==2?'_v2':'').'.vial')} (1,2);
my $lifecycle=read_file("$repo/vial/ahb_subordinate_base_output_arbitration_lifecycle_v2.vial");
my $start=$lifecycle;$start =~ s/\(target fixture_background\)/(target fixture_background) (start_requires (reset_inactive bus))/;
my $empty=$lifecycle;
$empty =~ s/\(services\s+\(service background\s+\(target fixture_background\)\)\)/(services)/;
$empty =~ s/\(dependencies\s+\(dependency configured_gate \(when \(configured\)\)\)\s+\(dependency reset_gate \(when \(reset_inactive bus\)\)\)\)/(dependencies)/;

sub native {
    my ($version,$text,$catalog,$style)=@_;
    return execute_vial_tool_request({schema=>"fsmgen.vial_tool_request.v$version",schema_version=>$version,action=>'check',
        vial_source=>{source_id=>$id,source_kind_hint=>'vial',text=>$text,encoding=>'utf-8',origin=>'repository',
            display_name=>$id,canonical_id=>undef,relative_path=>$id,metadata=>{}},hial_source=>undef,
        options=>{source_style=>$style//'auto',output_style=>undef,fixture_id=>undef,scenario_ids=>[],
            execution_profile=>undef,backend_profile=>undef,replay_manifest=>undef,native_extension_catalogs=>[],
            artifact_policy=>undef,quiet=>JSON::PP::false}}, {source_catalog=>$catalog//{},artifact_sink=>[]});
}
sub invoke {
    my ($api,@args)=@_;my ($out,$err,$r)=('','');
    {open my $stdout,'>',\$out or die $!;open my $stderr,'>',\$err or die $!;
     local *STDOUT=$stdout;local *STDERR=$stderr;$r=$api->(@args)}
    is($out,'','API does not print stdout');is($err,'','API does not print stderr');return $r;
}
sub args { +{source_id=>$id,text=>$_[1],language_version=>$_[0],source_catalog=>$_[2]//{},source_style=>$_[3]//'auto'} }
sub snapshot {
    my %files;find({no_chdir=>1,wanted=>sub {
        return unless -f $_ && !-l $_;
        $files{substr($_,length($workspace)+1)}=sha256_hex(read_file($_));
    }},$workspace);return \%files;
}
sub failure_shape {
    my ($r)=@_;ok(!$r->{success},'inspection fails');ok(!defined $r->{inspection},'no partial inspection');
    ok(@{$r->{diagnostics}},'failure has diagnostics');
    is_deeply($r->{check_result}{artifacts},[],'failed check publishes no artifact');
}

subtest 'public typed detail covers both versions and current lifecycle features' => sub {
    ok(grep({$_ eq 'inspect_vial_source'} @FSM::VIAL::Tool::EXPORT_OK),'portable function exportable');
    ok(grep({$_ eq 'inspect_vial_source_file'} @FSM::VIAL::Tool::EXPORT_OK),'filesystem function exportable');
    for my $case ([1,$base{1}],[2,$base{2}],[2,$lifecycle],[2,$start],[2,$empty],[1,"; caf\xc3\xa9\n".$base{1}]) {
        my ($version,$text)=@$case;my $input=args($version,$text);my $before=$json->encode($input);
        my $checked=native($version,$text);ok($checked->{success},'native source checks');
        my $r=invoke($portable,$input);ok($r->{success},'portable inspection succeeds');
        is_deeply([sort keys %$r],[sort qw(schema schema_version success check_result inspection diagnostics)],'closed independent result envelope');
        is($r->{schema},'fsmgen.vial_source_inspection.v1','public inspection result schema independent of language');
        is($r->{schema_version},1,'inspection schema version');ok(JSON::PP::is_bool($r->{success}),'success is JSON boolean');
        is_deeply($r->{check_result},$checked,'complete native check report preserved');
        is_deeply($r->{diagnostics},[],'success has no diagnostics');
        is($r->{inspection}{root_source}{content_sha256},sha256_hex($text),'detail names the captured root bytes');
        is($r->{inspection}{language_version},$version,'explicit language version retained');
        is($r->{inspection}{packages}[0]{fixtures}[0]{scenarios}[0]{actions}[0]{kind},'reset','base action bodies available through public API');
        if ($text =~ /\(family lifecycle_control/) {
            my @nodes=@{$r->{inspection}{packages}[0]{intent_families}[0]{nodes}};
            my ($deadline)=grep {$_->{node_kind} eq 'deadline'} @nodes;
            is($deadline->{payload}{detail}{max_cycles},1024,'authored full lifecycle deadline inspectable');
            my ($ready)=grep {$_->{node_kind} eq 'readiness'} @nodes;
            is($ready->{payload}{condition}{kind},'all','complete lifecycle condition exposed');
        }
        write_file("$workspace/$id",$text);my $files=snapshot();
        my $file=invoke($filesystem,{workspace_root=>$workspace,source_id=>$id,language_version=>$version});
        is_deeply($file,$r,'filesystem and portable complete inspection results agree');
        is_deeply(snapshot(),$files,'filesystem inspection creates or changes no files');
        is($json->encode($input),$before,'portable caller input unchanged');
        my $saved=$json->decode($json->encode($r));$r->{inspection}{packages}[0]{name}='mutated';
        is_deeply($portable->($input),$saved,'later calls return fresh deterministic values');
    }
    ok($portable->({source_id=>$id,text=>$base{1}})->{success},'omitted version/style/catalog use documented defaults');
};

subtest 'styles imports and native failure diagnostics retain exact identity' => sub {
    for my $version (1,2) {
        my $library=$base{$version};$library =~ s/package ahb_subordinate_base_output_arbitration/package library/;
        my $text=$base{$version};$text =~ s/\(imports\)/(imports (import lib "library.vial"))/;
        my $catalog={'library.vial'=>$library};my $input=args($version,$text,$catalog);
        my $r=$portable->($input);ok($r->{success},'imported source inspects');
        is($r->{inspection}{packages}[1]{name},'library','imported declaration bodies retained');
        write_file("$workspace/$id",$text);write_file("$workspace/library.vial",$library);
        is_deeply($filesystem->({workspace_root=>$workspace,source_id=>$id,language_version=>$version}),$r,'complete imported file/memory result equality');
        my $terse=FSM::VIAL::SourceProjection->format_source({text=>$text,source_name=>$id,output_style=>'terse'})->{text};
        my $formatted=$portable->(args($version,$terse,$catalog,'terse'));ok($formatted->{success},'explicit terse style inspects');
        is($formatted->{check_result}{capability_evidence}{semantic_projection_sha256},$r->{check_result}{capability_evidence}{semantic_projection_sha256},'style preserves exact native meaning identity');
        for my $case (['(vial',{},'auto'],[$text,{},'auto'],[$text,$catalog,'terse'],[$base{$version==1?2:1},{},'auto']) {
            my ($bad,$imports,$style)=@$case;my $expected=native($version,$bad,$imports,$style);
            my $failed=invoke($portable,args($version,$bad,$imports,$style));failure_shape($failed);
            is_deeply($failed->{check_result},$expected,'complete native failure report preserved');
            is_deeply($failed->{diagnostics},$expected->{diagnostics},'ordered native diagnostics preserved');
        }
    }
};

subtest 'closed invocations and bounded filesystem admission fail without detail' => sub {
    my @invalid=([],[undef],[[]],[bless({},'InspectionForeign')],
        [{text=>$base{1}}],[{source_id=>$id}], [{source_id=>$id,text=>[]}],
        [{source_id=>$id,text=>$base{1},language_version=>3}], [{source_id=>$id,text=>$base{1},source_style=>undef}],
        [{source_id=>$id,text=>$base{1},source_catalog=>[]}], [{source_id=>$id,text=>$base{1},backend_profile=>'sv'}],
        [{source_id=>$id,text=>$base{1}},{}], [{source_id=>'../outside.vial',text=>$base{1}}]);
    for my $call (@invalid) {my $r=invoke($portable,@$call);failure_shape($r);is($r->{diagnostics}[0]{code},'VIAL_TOOL_INVOCATION_ERROR','closed portable invocation rejected specifically')}
    write_file("$workspace/$id",$base{1});symlink($id,"$workspace/link.vial") or die $!;
    for my $call ([],[undef],[{workspace_root=>$workspace,source_id=>$id,text=>$base{1}}],
        [{workspace_root=>$workspace,source_id=>'missing.vial'}],[{workspace_root=>$workspace,source_id=>'link.vial'}],
        [{workspace_root=>$workspace,source_id=>'../outside.vial'}],
        [{workspace_root=>$workspace,source_id=>$id,language_version=>2,source_style=>undef}]) {
        my $native=check_vial_source_file(@$call);my $r=invoke($filesystem,@$call);failure_shape($r);
        is_deeply($r->{check_result},$native,'filesystem refusal preserves exact established check report');
    }
    my $oversize=' ' x (build_vial_tooling_contract()->{limits}{source_bytes}+1);
    my $r=$portable->(args(1,$oversize));failure_shape($r);is_deeply($r->{check_result},native(1,$oversize),'portable byte limit preserves native refusal');
    write_file("$workspace/oversize.vial",$oversize);
    $r=$filesystem->({workspace_root=>$workspace,source_id=>'oversize.vial'});failure_shape($r);
    is($r->{diagnostics}[0]{code},'VIAL_LIMIT_ERROR','filesystem byte admission remains bounded');
};

subtest 'captured bytes are not reopened or borrowed from mutable caller data' => sub {
    my $text=$base{1};$text =~ s/\(imports\)/(imports (import lib "library.vial"))/;
    my $library=$base{1};$library =~ s/package ahb_subordinate_base_output_arbitration/package library/;
    write_file("$workspace/$id",$text);write_file("$workspace/library.vial",$library);
    my ($checks,%reads);my $read=\&FSM::VIAL::ToolCLI::_read_repo_source;my $execute=\&FSM::VIAL::Tool::execute_vial_tool_request;
    my $r;
    {no warnings qw(redefine once);
     local *FSM::VIAL::ToolCLI::_read_repo_source=sub {$reads{$_[1]}++;$read->(@_)};
     local *FSM::VIAL::Tool::execute_vial_tool_request=sub {my $c=$execute->(@_);$checks++;write_file("$workspace/$id",'changed after check');write_file("$workspace/library.vial",'changed import after check');return $c};
     $r=$filesystem->({workspace_root=>$workspace,source_id=>$id});}
    is($checks,1,'one native public check precedes detail');is_deeply(\%reads,{$id=>1,'library.vial'=>1},'each source captured once');
    ok($r->{success},'inspection uses validated captured bytes after files change');
    is($r->{inspection}{root_source}{content_sha256},sha256_hex($text),'original root identity retained');
    is($r->{inspection}{sources}[1]{content_sha256},sha256_hex($library),'original import identity retained');
    my $input=args(1,$text,{'library.vial'=>$library});
    {no warnings qw(redefine once);
     local *FSM::VIAL::Tool::execute_vial_tool_request=sub {my $c=$execute->(@_);$input->{text}='changed';$input->{source_catalog}{'library.vial'}='changed';return $c};
     $r=$portable->($input);}
    ok($r->{success},'portable inspection owns captured caller bytes');
    is($r->{inspection}{sources}[1]{content_sha256},sha256_hex($library),'caller catalog mutation cannot alter checked detail');
};

subtest 'inspection has no execution effects and projection faults are sanitized' => sub {
    {no warnings qw(redefine once);
     local *FSM::VIAL::ToolCLI::_read_repo_source=sub {die 'unexpected filesystem access'};
     local *FSM::VIAL::Tool::_execute_plan_action=sub {die 'unexpected v1 planning'};
     local *FSM::VIAL::Tool::_execute_plan_action_v2=sub {die 'unexpected v2 planning'};
     local *FSM::VIAL::ArtifactTransaction::publish=sub {die 'unexpected publication'};
     ok($portable->(args(1,$base{1}))->{success},'v1 portable inspection needs no filesystem/planning/publication');
     ok($portable->(args(2,$lifecycle))->{success},'v2 lifecycle inspection needs no filesystem/planning/publication');}
    for my $version (1,2) {
        my $checked=native($version,$base{$version});my $r;
        {no warnings qw(redefine once);local *FSM::VIAL::SourceInspection::build=sub {die 'secret compiler path /private/internal/source.pm'};
         $r=invoke($portable,args($version,$base{$version}));}
        failure_shape($r);is_deeply($r->{check_result},$checked,'projection failure preserves successful native check');
        is($r->{diagnostics}[0]{code},'VIAL_SOURCE_INSPECTION_ERROR','separate projection diagnostic');
        unlike($json->encode($r),qr/secret compiler|private\/internal/,'private exception never leaks');
    }
};
done_testing();
sub read_file {open my $fh,'<:raw',$_[0] or die $!;local $/;my $s=<$fh>;close $fh or die $!;return $s}
sub write_file {open my $fh,'>:raw',$_[0] or die $!;print {$fh} $_[1] or die $!;close $fh or die $!}

sources.t/1883-semantic-source-query-cohort.t:
#!/usr/bin/env perl
use strict;
use warnings;
use FindBin;
use JSON::PP ();
use Test::More;
use lib "$FindBin::Bin/../perl", "$FindBin::Bin/lib";
use FSM::Support::RegressionCorpus qw(regression_corpus_entries);
use FSM::Support::SemanticIntrospectionContract qw(semantic_introspection_source_query_kinds);
use FSM::Test::HostedCorpusShard qw(select_hosted_corpus_entries);
use FSM::VIAL::Tool qw(check_vial_source_file);

my $loaded=eval {require FSM::Test::SourceQueryCoverage;1};
ok($loaded,'source-query cohort selector exists');
if (!$loaded) {done_testing();exit 0}
my $build=FSM::Test::SourceQueryCoverage->can('build_source_query_cohort');
my $focus=FSM::Test::SourceQueryCoverage->can('select_source_query_cohort');
my $versions=FSM::Test::SourceQueryCoverage->can('vial_source_versions');
ok($build && $focus && $versions,'selector exposes cohort, focus and explicit VIAL version mapping');
if (!$build || !$focus || !$versions) {done_testing();exit 0}
my @catalog=regression_corpus_entries();
my $json=JSON::PP->new->canonical;
my $queries=semantic_introspection_source_query_kinds();
my $cohort=$build->();
sub clone {$json->decode($json->encode($_[0]))}
sub row {+{id=>$_[0]//'feature.example',relpath=>'fsm/example.fsm',source_kind=>'fsm',classification=>'supported_smoke',family=>'example',coverage=>'example_semantics',strict_supported=>1,expected_module_name=>'example'}}
sub sample {+{entries=>[row()],query_kinds=>clone($queries),vial_versions=>{}}}
sub rejected {my ($args,$message)=@_;eval {$build->($args)};like($@,$message,'invalid or unaccounted selection fails specifically')}

subtest 'live supported catalog is accounted exactly with source work deduplicated' => sub {
    my @supported=grep {$_->{classification} eq 'supported_smoke'} @catalog;
    my %expected;my @order;
    for my $entry (@supported) {push @order,$entry->{relpath} unless exists $expected{$entry->{relpath}};push @{$expected{$entry->{relpath}}},$entry}
    is_deeply([map {$_->{source_id}} @$cohort],\@order,'one source row in first catalog occurrence order');
    my @actual_ids;
    for my $r (@$cohort) {
        my $source=$r->{source_id};my @entries=@{$expected{$source}};
        is_deeply([map {$_->{id}} @{$r->{catalog_entries}}],[map {$_->{id}} @entries],'every source retains its exact catalog IDs and order');
        is_deeply([map {[$_->{id},$_->{family},$_->{coverage}]} @{$r->{catalog_entries}}],[map {[$_->{id},$_->{family},$_->{coverage}]} @entries],'ID-to-family/coverage allocation is retained');
        push @actual_ids,map {$_->{id}} @{$r->{catalog_entries}};
        my ($suffix)=$source =~ /\.([^.]+)$/;
        is($r->{file_kind},$suffix,'file kind comes from source suffix');
        is_deeply($r->{query_kinds},$queries->{$suffix},'every applicable public query is selected');
        if ($suffix eq 'vial') {
            is($r->{language_version},$versions->()->{$source},'VIAL version is explicitly mapped');
            ok(!$r->{strict},'VIAL uses versioned source admission');
            my $checked=check_vial_source_file({workspace_root=>"$FindBin::Bin/..",source_id=>$source,language_version=>$r->{language_version}});
            ok($checked->{success},'explicit mapping admits the actual public VIAL source') or diag($json->encode($checked->{diagnostics}));
        }
        else {ok($r->{strict},'hardware uses strict source admission');ok(!defined $r->{language_version},'hardware has no VIAL selector')}
    }
    is_deeply([sort @actual_ids],[sort map {$_->{id}} @supported],'no supported entry is lost or duplicated');
    my @public=map {s{^\Q$FindBin::Bin/..\E/}{}r} glob("$FindBin::Bin/../vial/*.vial");
    is_deeply([sort keys %{$versions->()}],[sort @public],'every public root VIAL example is explicitly versioned; runtime qualification fixtures are separate');
    is_deeply($build->(),$cohort,'selection is deterministic');
    my $mutated=$build->();$mutated->[0]{catalog_entries}[0]{coverage}='changed';
    is_deeply($build->(),$cohort,'selection returns independent records');
};

subtest 'focused selection is exact and preserves canonical order and shard compatibility' => sub {
    my @ids=map {$_->{source_id}} @$cohort;
    my $selected=$focus->({cohort=>$cohort,source_ids=>[$ids[-1],$ids[0]]});
    is_deeply([map {$_->{source_id}} @$selected],[$ids[0],$ids[-1]],'focus retains canonical order independent of argument order');
    is_deeply($focus->({cohort=>$cohort}),$cohort,'omitted focus selects all rows');
    for my $ids ([],['unknown.fsm'],[$ids[0],$ids[0]]) {eval {$focus->({cohort=>$cohort,source_ids=>$ids})};ok($@,'empty unknown or repeated focus is rejected')}
    my %seen;
    for my $i (0..2) {
        local $ENV{FSMGEN_HOSTED_CORPUS_SHARD_INDEX}=$i;local $ENV{FSMGEN_HOSTED_CORPUS_SHARD_COUNT}=3;
        my $shard=select_hosted_corpus_entries(entries=>$cohort);
        for my $r (@$shard) {ok(!$seen{$r->{source_id}}++,'hosted source partitions are disjoint');is_deeply($r->{query_kinds},$queries->{$r->{file_kind}},'all queries for each source remain together')}
    }
    is_deeply([sort keys %seen],[sort @ids],'hosted partitions cover the complete selected source set');
    $selected->[0]{query_kinds}[0]='changed';is_deeply($build->(),$cohort,'focused result does not alias original data');
};

subtest 'unknown source query version and conflicting metadata fail closed' => sub {
    my $a=sample();$a->{query_kinds}{vial}=[qw(check semantic)];rejected($a,qr/query applicability/);
    $a=sample();push @{$a->{query_kinds}{fsm}},'execute';rejected($a,qr/query applicability/);
    $a=sample();$a->{query_kinds}{future}=['check'];rejected($a,qr/source kind/);
    $a=sample();$a->{entries}[0]{relpath}='example.future';rejected($a,qr/source suffix/);
    $a=sample();$a->{entries}[0]{source_kind}='future';rejected($a,qr/source kind/);
    $a=sample();$a->{entries}[0]{strict_supported}=0;rejected($a,qr/strict/);
    $a=sample();$a->{entries}[0]{relpath}='../example.fsm';rejected($a,qr/relative source/);
    $a=sample();delete $a->{entries}[0]{coverage};rejected($a,qr/coverage/);
    $a=sample();push @{$a->{entries}},clone($a->{entries}[0]);rejected($a,qr/duplicate catalog ID/);
    $a=sample();my $second=row('feature.second');$second->{expected_module_name}='other';push @{$a->{entries}},$second;rejected($a,qr/conflicting.*expected_module_name/);
    $a=sample();$a->{vial_versions}{'vial/unused.vial'}=2;rejected($a,qr/unaccounted VIAL/);
    $a=sample();$a->{entries}[0]{relpath}='vial/new.vial';$a->{entries}[0]{source_kind}='vial';$a->{entries}[0]{strict_supported}=0;rejected($a,qr/unmapped VIAL/);
    $a->{vial_versions}{'vial/new.vial'}=3;rejected($a,qr/VIAL version/);
    $a=sample();$a->{entries}[0]{classification}='new_class';rejected($a,qr/classification/);
    $a=sample();$a->{entries}[0]{search_path_relpaths}=['../outside'];rejected($a,qr/relative search path/);
    for my $args (undef,[],{unknown=>1},{entries=>[]},{entries=>[undef]}) {rejected($args,qr/cohort|catalog/)}
};

subtest 'legitimate shared-source contracts retain all identities and defensive metadata' => sub {
    my $a=sample();my $second=row('feature.second');$second->{coverage}='another_surface';$second->{family}='another_family';push @{$a->{entries}},$second;
    $a->{entries}[0]{required_capabilities}=['feature.first'];$a->{entries}[0]{search_path_relpaths}=['fsm'];
    $second->{search_path_relpaths}=['fsm'];my $saved=clone($a);
    my $r=$build->($a);is(scalar(@$r),1,'shared physical source is queried once per kind');
    is_deeply([map {$_->{coverage}} @{$r->[0]{catalog_entries}}],['example_semantics','another_surface'],'distinct coverage memberships retained');
    is_deeply($r->[0]{search_path_relpaths},['fsm'],'explicit search paths retained for actual execution');
    $r->[0]{catalog_entries}[0]{required_capabilities}[0]='changed';is_deeply($a,$saved,'output never mutates or borrows caller input');
    $a->{entries}[0]{classification}='expected_failure';$r=$build->($a);is_deeply([map {$_->{id}} @{$r->[0]{catalog_entries}}],['feature.second'],'negative population does not become supported source evidence');
};
done_testing();

