#!/usr/bin/env perl
use strict;
use warnings;
use Test::More;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use lib 'perl', 't/lib';
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Scheduler::ISF::FormalClauseResolver;
use FSM::Scheduler::ISF::FormalIdentityPlan;
use FSM::Scheduler::ISF::PreparedFormalReservations;
use FSM::Scheduler::ISF::FormalReservationCoverage;

my $scheduler = FSM::Scheduler::ISF->new;
my $work = tempdir(CLEANUP => 1);
my $ordinal = 0;
sub allocation {
    my ($p) = @_;
    return FSM::Scheduler::ISF::FormalIdentityPlan->build($p->{actor},
        generated_children => $p->{generated_children},
        reserved_names => FSM::Scheduler::ISF::PreparedFormalReservations->collect($p)->{reserved_names});
}
sub verify {FSM::Scheduler::ISF::FormalReservationCoverage->verify(@_)}
sub qualify {
    my ($source, $label, $path) = @_;
    my $actor = ref($source) eq 'HASH' ? dclone($source)
        : FSM::Adapter::ISF->new->parse_source($source, $path // 'coverage.isf');
    my $p = $scheduler->{ir}->prepare_formal_source($actor);
    my $plan = allocation($p);
    my $physical = dclone($p->{actor});
    for my $tx (@{$physical->{transactions}}) {
        next if $p->{pruned_transactions}{$tx->{name}};
        $tx = FSM::Scheduler::ISF::FormalClauseResolver->transaction($tx,
            plan => $plan, %{$p->{transactions}{$tx->{name}}})->{transaction};
    }
    for my $rule (@{$physical->{rules}}) {
        $rule = FSM::Scheduler::ISF::FormalClauseResolver->rule($rule,
            plan => $plan, %{$p->{actor_context}})->{rule};
    }
    my %modules;
    my $build = \&FSM::Scheduler::ISF::LoweringIR::build_module;
    my $files;
    {
        no warnings 'redefine';
        local *FSM::Scheduler::ISF::LoweringIR::build_module = sub {
            my $ir = $build->(@_);
            $modules{$ir->{actor_name}} = dclone($ir);
            return $ir;
        };
        $files = $scheduler->lower($physical)->{files};
    }
    my $before = dclone([$p, $plan, \%modules]);
    my $result = verify($p, $plan, \%modules);
    ok(@{$result->{verified_scopes}}, "$label verifies actual lowered scopes");
    is_deeply([$p, $plan, \%modules], $before, "$label verification is read-only");
    my $dir = "$work/" . ++$ordinal; mkdir $dir or die $!;
    for my $name (sort keys %$files) {
        open my $out, '>', "$dir/$name" or die $!; print {$out} $files->{$name}; close $out or die $!;
    }
    my $top = exists $files->{"$actor->{actor_name}_top.fsm"}
        ? "$actor->{actor_name}_top.fsm" : "$actor->{actor_name}.fsm";
    my $check = FSM::Test::SourceQueryRunner::_capture([$^X, 'bin/fsmgen', '--strict', '--check', '--json', "$dir/$top"], '');
    is($check->{exit_code}, 0, "$label final exported carrier strict-checks") or diag($check->{stdout}, $check->{stderr});
    return ($p, $plan, \%modules);
}

my $source = <<'ISF';
(actor coverage (clock clk) (reset rst_n)
 (interface (input start) (input data (width 4)) (output result (width 4)) (output done) (output notice))
 (storage (var value_reg (width 8)))
 (drive (isf_port_main payload) (result payload))
 (transaction main (ports (input payload (width 4)) (input value_reg (width 4)))
  (on start) (set payload data) (set value_reg payload) (drive isf_port_main payload)
  (wait value_reg) (spawn worker as job) (await_all done) (complete done))
 (transaction worker (wait 1) (complete notice)))
ISF
my ($prepared, $plan, $modules);
subtest 'actual parent and generated child declarations pass independently' => sub {
    ($prepared, $plan, $modules) = qualify($source, 'generated child and storage shadow');
    (my $upper = $source) =~ s/isf_port_main/ISF_PORT_MAIN/g;
    qualify($upper, 'case-folded helper collision');
    my $reversed = FSM::Adapter::ISF->new->parse_source($source, 'coverage.isf');
    @{$reversed->{transactions}} = reverse @{$reversed->{transactions}};
    my $other = $scheduler->{ir}->prepare_formal_source($reversed);
    is_deeply(allocation($other), $plan, 'source declaration permutation preserves allocation');
    qualify($reversed, 'permuted actual declarations');
};

sub reject {
    my ($p, $allocation, $actual, $pattern, $label) = @_;
    my $before = dclone([$p, $allocation, $actual]);
    my $ok = eval {verify($p, $allocation, $actual); 1};
    ok(!$ok, "$label refused"); like($@, $pattern, "$label diagnosed");
    is_deeply([$p, $allocation, $actual], $before, "$label refusal preserves inputs");
}
subtest 'missing declarations, module sets and private ownership fail closed' => sub {
    my $private = $plan->{formals}{main}{payload}{physical_name};
    for my $case (
        [sub {$_[0]{coverage}{counters}{late_unreserved_helper} = 1}, qr/unreserved declarations:.*late_unreserved_helper/, 'late register'],
        [sub {push @{$_[0]{coverage}{states}[0]{assignments}}, {lhs => 'implicit_late_helper', rhs => '0', op => '<='}}, qr/unreserved declarations:.*implicit_late_helper/, 'implicit assignment declaration'],
        [sub {delete $_[0]{coverage}}, qr/incomplete parent\/domain modules/, 'missing parent'],
        [sub {$_[0]{extra} = dclone($_[0]{coverage})}, qr/incomplete parent\/domain modules/, 'unexpected module'],
        [sub {delete $_[0]{coverage}{children}{worker}}, qr/incomplete children/, 'missing child'],
        [sub {$_[0]{coverage}{children}{worker}{children}{nested} = {}}, qr/unplanned nested child scope/, 'unexpected nested child'],
        [sub {$_[0]{coverage}{children}{worker}{actor_name} = 'other'}, qr/mismatched module/, 'wrong child identity'],
        [sub {$_[0]{coverage}{children}{worker}{counters}{$private} = 4}, qr/unreserved declarations/, 'parent private name leaked into child'],
        [sub {$_[0]{coverage}{counters}{$private} = 9}, qr/wrong width or ownership/, 'wrong formal width'],
        [sub {$_[0]{coverage}{storage_roles}{$private} = 'drive_payload'}, qr/wrong width or ownership/, 'wrong formal role'],
        [sub {push @{$_[0]{coverage}{dt_blocks}}, {name => $private, assignments => []}}, qr/wrong width or ownership/, 'formal aliases a late block'],
    ) {
        my $actual = dclone($modules); $case->[0]->($actual);
        reject($prepared, $plan, $actual, $case->[1], $case->[2]);
    }
    my $bad_plan = dclone($plan); $bad_plan->{formals}{main}{payload}{physical_name} = 'isf_port_main_payload';
    reject($prepared, $bad_plan, $modules, qr/canonical complete allocation plan/, 'stale or incomplete allocation');
};

sub substitute_token {
    my ($value, $name) = @_;
    if (ref($value) eq 'HASH') {
        return {map {my $key = $_; $key =~ s/\b\Q$name\E\b/missing_reservation_placeholder/g;
            $key => substitute_token($value->{$_}, $name)} keys %$value};
    }
    return [map {substitute_token($_, $name)} @$value] if ref($value) eq 'ARRAY';
    my $copy = $value;
    $copy =~ s/\b\Q$name\E\b/missing_reservation_placeholder/g if defined($copy);
    return $copy;
}
subtest 'removing a real producer name is detected against independently lowered output' => sub {
    my ($helper) = grep {$modules->{coverage}{storage_roles}{$_} eq 'dynamic_wait_counter'}
        keys %{$modules->{coverage}{storage_roles}};
    ok(defined $helper, 'actual dynamic-wait producer selected');
    my $incomplete = substitute_token($prepared, $helper);
    my $inventory = FSM::Scheduler::ISF::PreparedFormalReservations->collect($incomplete);
    ok(!$inventory->{reserved_names}{$helper}, 'mutation really removed every reservation for the actual helper');
    my $same_plan = allocation($incomplete);
    is_deeply($same_plan, $plan, 'omission does not change the planned private names');
    reject($incomplete, $same_plan, $modules, qr/unreserved declarations:.*\Q$helper\E/, 'omitted real producer declaration');
};

subtest 'reusable children and rule payload source identities retain their own coverage' => sub {
    for my $fixture (qw(fifo_library_use storage_fields atl_resolved_child_pipeline
        atl_two_child_vector_data_pipeline atl_two_child_trigger_batch_pipeline)) {
        my $actor = FSM::Adapter::ISF->new->parse_file("isf/$fixture.isf");
        qualify($actor, $fixture);
    }
    qualify(<<'ISF', 'rule payload source identity');
(actor rule_coverage (clock clk) (reset rst_n)
 (interface (input fire) (input din (width 4)) (output observed (width 4)) (output done))
 (transaction main (ports (input payload (width 4)))
  (on main_start) (set observed payload) (complete done))
 (rule isf_port fire (trigger main (bind (input payload din)))))
ISF
};

subtest 'a real helper-looking formal is separated before final admission' => sub {
    my $source = <<'ISF';
(actor monitor_coverage (clock clk) (reset rst_n)
 (interface (input fire) (input ack) (output observed (width 4)))
 (transaction main (ports (input payload (width 4)))
  (on fire) (set payload 3) (assert (monitor (within ack 3))) (set observed payload)))
ISF
    my $actor = FSM::Adapter::ISF->new->parse_source($source, 'monitor_coverage.isf');
    my $p = $scheduler->{ir}->prepare_formal_source($actor);
    my ($monitor) = grep {$_->{kind} eq 'temporal_contract_monitor'} @{$p->{transaction_products}{main}{dt_blocks}};
    my ($failure) = grep {$_->{source_kind} eq 'contract_fail'} @{$monitor->{assignments}};
    ok($failure, 'actual monitor failure producer observed');
    $source =~ s/\bpayload\b/$failure->{lhs}/g;
    my ($prepared) = qualify($source, 'monitor helper formal');
    ok(@{$prepared->{deferred_formal_collisions}{main}}, 'source-only collision deferral remains distinct from executable verification');
};

done_testing();

sources.t/1983-isf-interface-port-metadata.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Support::ISFInterfacePortMetadata qw(
    capture_interface_port_metadata snapshot_interface_port_metadata
    interface_port_metadata_contract
);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $actor = $parser->parse_source(<<'ISF', 'port-metadata.isf');
(actor port_metadata
  (types
    (type byte (bits 8))
    (type frame_t
      (record
        (subtype (bits 4))
        (payload (record
          (count (signed (four_state (bits 3))))
          (lanes (list (two_state bit) (bits 2))))))))
  (clock clk) (reset rst)
  (interface (output unused (width 2)) (input start)
             (input data (type byte)) (output done))
  (storage (var frame (type frame_t)))
  (transaction main (on start) (complete done)))
ISF

subtest 'declared scalar ports retain ordering and alias facts' => sub {
    my $expected = [
        {name => 'start', direction => 'input', width => 1},
        {name => 'data', direction => 'input', width => 8, type => 'byte', type_kind => 'bits'},
        {name => 'unused', direction => 'output', width => 2},
        {name => 'done', direction => 'output', width => 1},
    ];
    my $before = dclone($actor);
    my $actual = capture_interface_port_metadata($actor->{interface});
    is_deeply($actual, $expected, 'input order followed by output order, including unused declarations');
    is_deeply($json->decode($json->encode($actual)), $expected, 'closed result is JSON-safe');
    $actual->[1]{width} = 99;
    is_deeply($actor, $before, 'projection does not share parser objects');
    my $domain_interface = dclone($actor->{interface});
    $domain_interface->{inputs}[1]{domain} = 'aux';
    my $scoped = capture_interface_port_metadata($domain_interface, 'core');
    is_deeply([map { $_->{domain} } @$scoped], [qw(core aux core core)],
        'explicit domains override the declared default');
    is_deeply(capture_interface_port_metadata({inputs => [{name => 'data-lane', width => 2}], outputs => []}),
        [{name => 'data-lane', direction => 'input', width => 2}],
        'metadata preserves nonempty opaque port names without inventing source restrictions');
};

my $fields = [
    {path => 'subtype', width => 4, lsb => 6, msb => 9, signed => 0},
    {path => 'payload.count', width => 3, lsb => 3, msb => 5, signed => 1, state_model => 'four_state'},
    {path => 'payload.lanes[0]', width => 1, lsb => 2, msb => 2, signed => 0, state_model => 'two_state'},
    {path => 'payload.lanes[1]', width => 2, lsb => 0, msb => 1, signed => 0},
];
my $record_interface = {
    inputs => [{name => 'packet', width => 10, type => 'frame_t', type_spec => $actor->{storage}[0]{type_spec}}],
    outputs => [],
};
my $record = [{name => 'packet', direction => 'input', width => 10,
    type => 'frame_t', type_kind => 'record', fields => $fields}];

sub stringify_numeric_properties {
    my ($value) = @_;
    if (ref($value) eq 'HASH') {
        for my $key (keys %$value) {
            if ($key =~ /\A(?:width|lsb|msb|signed)\z/ && !ref($value->{$key})) {
                $value->{$key} = "$value->{$key}";
            } else {
                stringify_numeric_properties($value->{$key});
            }
        }
    } elsif (ref($value) eq 'ARRAY') {
        stringify_numeric_properties($_) for @$value;
    }
}

subtest 'capture and snapshot detach before first numeric read on valid and refused facts' => sub {
    for my $case (
        ['capture',\&capture_interface_port_metadata,$record_interface],
        ['snapshot',\&snapshot_interface_port_metadata,$record],
    ) {
        my ($name,$produce,$template) = @$case;
        my $value=dclone($template);
        stringify_numeric_properties($value);
        my $before=$json->encode($value);
        my $actual=$produce->($value);
        is($json->encode($value),$before,"$name preserves original scalar kinds on its first read");
        is_deeply($actual,$record,"$name still returns the same independently expected numeric layout");
        $actual->[0]{fields}[0]{width}=99;
        is($json->encode($value),$before,"$name output mutation cannot reach source facts");
        $value=dclone($template);
        stringify_numeric_properties($value);
        if ($name eq 'capture') {
            push @{$value->{outputs}}, {name=>'invalid',width=>'bad'};
        } else {
            push @$value,undef;
        }
        $before=$json->encode($value);
        my $ok=eval {$produce->($value);1};
        my ($line)=split /\n/,$@;
        ok(!$ok,"$name rejects a malformed suffix after valid numeric facts");
        like($line // '',qr/\AInvalid ISF interface port metadata:/,"$name retains a classified first diagnostic");
        is($json->encode($value),$before,"$name refused first read cannot mutate valid prefix facts");
    }
};

subtest 'resolved record preparation preserves independently expected leaf ranges' => sub {
    my $before = dclone($record_interface);
    my $actual = capture_interface_port_metadata($record_interface);
    is_deeply($actual, $record, 'nested record/list leaves have authored order and exact packed ranges');
    $actual->[0]{fields}[0]{lsb} = 0;
    is_deeply($record_interface, $before, 'nested type objects remain detached');
    my $copy = snapshot_interface_port_metadata($record);
    $copy->[0]{fields}[1]{state_model} = 'two_state';
    is($record->[0]{fields}[1]{state_model}, 'four_state', 'snapshot does not share nested fields');
    my $ok = eval { $parser->parse_source(
        '(actor refused (types (type packet_t (record (flag bit))))'
        . ' (interface (output packet (type packet_t)) (output done))'
        . ' (transaction main (set packet.flag 1) (complete done)))', 'field-refused.isf'); 1 };
    ok(!$ok, 'record output field writer remains deferred');
    like($@, qr/record output field writes are not yet admitted/,
        'existing authored-field refusal remains precise');
};

subtest 'imported scalar and record aliases retain qualified identity' => sub {
    my $work = tempdir(CLEANUP => 1);
    write_file("$work/shared.fsm", '(?pkg:shared (+types (type byte (bits 8))'
        . ' (type packet_t (record (code (bits 2)) (flag bit)))))');
    my $path = "$work/imported.isf";
    write_file($path, '(actor imported (imports (package shared)) (clock clk) (reset rst)'
        . ' (interface (input data (type shared.byte)) (output done))'
        . ' (storage (var packet (type shared.packet_t))) (transaction main (complete done)))');
    my $parsed = $parser->parse_file($path);
    my $ports = capture_interface_port_metadata($parsed->{interface});
    is_deeply($ports->[0], {name => 'data', direction => 'input', width => 8,
        type => 'shared.byte', type_kind => 'bits'}, 'imported scalar alias is not flattened to an anonymous width');
    my $prepared = capture_interface_port_metadata({inputs => [{name => 'packet', width => 3,
        type => 'shared.packet_t', type_spec => $parsed->{storage}[0]{type_spec}}], outputs => []});
    is($prepared->[0]{type}, 'shared.packet_t', 'record producer retains imported alias');
    is_deeply($prepared->[0]{fields}, [
        {path => 'code', width => 2, lsb => 1, msb => 2, signed => 0},
        {path => 'flag', width => 1, lsb => 0, msb => 0, signed => 0},
    ], 'independent imported layout oracle');
};

subtest 'unknown and known empty metadata stay distinct' => sub {
    is(capture_interface_port_metadata(undef), undef, 'absent declarations are unknown');
    is(snapshot_interface_port_metadata(undef), undef, 'unknown snapshot remains null');
    is_deeply(capture_interface_port_metadata({inputs => [], outputs => []}), [], 'known empty declarations remain empty');
    is_deeply(snapshot_interface_port_metadata([]), [], 'known empty snapshot remains empty');
    my $contract = interface_port_metadata_contract();
    is_deeply($contract->{entry_keys}, [qw(name direction width)], 'required entry keys match decision 0113');
    is_deeply($contract->{optional_entry_keys}, [qw(type type_kind domain fields)], 'optional entry keys match the selected schema');
    is_deeply($contract->{field_keys}, [qw(path width lsb msb signed)], 'scalar field key family is explicit');
    is_deeply($contract->{type_kind_values}, [qw(bit bits record)], 'list roots remain outside the selected contract');
    $contract->{entry_keys}[0] = 'changed';
    is(interface_port_metadata_contract()->{entry_keys}[0], 'name', 'discovery values are detached');
};

subtest 'closed snapshots reject malformed and contradictory metadata' => sub {
    my @bad = ({}, [undef], [{}]);
    for my $change (
        sub { delete $_[0][0]{name} }, sub { $_[0][0]{extra} = [] },
        sub { $_[0][0]{name} = '' }, sub { $_[0][0]{direction} = 'inout' },
        sub { $_[0][0]{width} = 0 }, sub { $_[0][0]{width} = 'bad' },
        sub { $_[0][0]{domain} = [] }, sub { $_[0][0]{domain} = 'bad-domain' },
        sub { $_[0][0]{type} = [] }, sub { $_[0][0]{type} = 'bad-alias' },
        sub { $_[0][0]{type_kind} = 'list' },
        sub { delete $_[0][0]{type} }, sub { delete $_[0][0]{fields} },
        sub { $_[0][0]{fields} = [] }, sub { $_[0][0]{fields}[0]{extra} = 1 },
        sub { $_[0][0]{fields}[0]{path} = [] }, sub { $_[0][0]{fields}[1]{path} = 'subtype' },
        sub { $_[0][0]{fields}[0]{msb} = 8 }, sub { $_[0][0]{fields}[0]{lsb} = 5 },
        sub { $_[0][0]{fields}[0]{lsb} = 'bad' }, sub { $_[0][0]{fields}[0]{width} = 'bad' },
        sub { $_[0][0]{fields}[-1]{lsb} = 1; $_[0][0]{fields}[-1]{width} = 1 },
        sub { $_[0][0]{fields}[0]{signed} = 2 }, sub { $_[0][0]{fields}[0]{state_model} = 'unknown' },
        sub { push @{$_[0]}, dclone($_[0][0]) },
    ) {
        my $value = dclone($record);
        $change->($value);
        push @bad, $value;
    }
    push @bad, [{name => 'out', direction => 'output', width => 1},
        {name => 'in', direction => 'input', width => 1}];
    push @bad, [{name => 'scalar', direction => 'input', width => 'bad'}],
        [{name => 'scalar', direction => 'input', width => 8, type => 'byte', type_kind => 'unknown'}];
    for my $index (0 .. $#bad) {
        my $bad = $bad[$index];
        rejects(sub { snapshot_interface_port_metadata($bad) }, "malformed snapshot $index", $bad);
    }
};

subtest 'producer rejects inconsistent resolved declarations without warnings' => sub {
    my @bad = ({}, {inputs => [undef], outputs => []});
    for my $change (
        sub { $_[0]{inputs}[0]{name} = undef }, sub { $_[0]{inputs}[0]{width} = 'bad' },
        sub { $_[0]{inputs}[0]{width} = 9 }, sub { delete $_[0]{inputs}[0]{type_spec} },
        sub { $_[0]{inputs}[0]{type_spec}{width} = 9 },
        sub { $_[0]{inputs}[0]{type_spec}{member_order} = ['subtype', 'subtype'] },
        sub { $_[0]{inputs}[0]{type_spec}{members}{subtype}{state_model} = [] },
        sub { $_[0]{inputs}[0]{type_spec}{members}{subtype}{signed} = [] },
        sub { delete $_[0]{inputs}[0]{type} },
        sub { $_[0]{inputs}[0]{type_spec} = {kind => 'list', width => 1, items => [{kind => 'bit', width => 1}]} },
    ) {
        my $value = dclone($record_interface);
        $change->($value);
        push @bad, $value;
    }
    my $cycle = {kind => 'record', width => 1, member_order => ['loop'], members => {}};
    $cycle->{members}{loop} = $cycle;
    push @bad, {inputs => [{name => 'cycle', width => 1, type => 'cycle_t', type_spec => $cycle}], outputs => []};
    for my $bad (@bad) { rejects(sub { capture_interface_port_metadata($bad) }, 'invalid producer input'); }
    delete $cycle->{members}{loop};
};

done_testing();

sub rejects {
    my ($operation, $label, $value) = @_;
    my @warnings;
    local $SIG{__WARN__} = sub { push @warnings, @_ };
    my $ok = eval { $operation->(); 1 };
    diag($json->encode($value)) if $ok && defined $value;
    ok(!$ok, "$label fails closed");
    like($@, qr/Invalid ISF interface port metadata:/, 'contextual bounded diagnostic');
    is_deeply(\@warnings, [], 'invalid metadata does not emit incidental Perl warnings');
}

sub write_file {
    my ($path, $text) = @_;
    open my $fh, '>', $path or die $!;
    print {$fh} $text or die $!;
    close $fh or die $!;
}

sources.t/1986-isf-record-port-value-gates.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Carp qw(confess);
use Storable qw(dclone);
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Package::PayloadTypeSupport;
use FSM::Support::ISFRecordPortValues qw(
    record_value_scope record_value_reference validate_record_port_copy
);

my $parser = FSM::Adapter::ISF->new;
my $actor = $parser->parse_source(<<'ISF', 'record-value-controls.isf');
(actor controls
  (types
    (type frame (record (flag bit) (data (bits 7))))
    (type alias frame)
    (type renamed (record (tag bit) (data (bits 7))))
    (type reordered (record (data (bits 7)) (flag bit)))
    (type signed_data (record (flag bit) (data (signed (bits 7)))))
    (type four (record (flag bit) (data (four_state (bits 7)))))
    (type two (record (flag bit) (data (two_state (bits 7)))))
    (type bit_kind (record (flag (bits 1)) (data (bits 7))))
    (type nested (record (header (bits 2))
      (body (record (count (signed (four_state (bits 3))))
        (lanes (list (two_state bit) (bits 2)))))))
    (type flat (record (header (bits 2)) (count (signed (four_state (bits 3))))
      (lane0 (two_state bit)) (lane1 (bits 2))))
    (type lanes (list bit (bits 2))))
  (interface (input start) (output done))
  (storage (var a (type frame)) (var b (type alias)) (var c (type renamed))
    (var d (type reordered)) (var e (type signed_data)) (var f (type four))
    (var g (type two)) (var h (type bit_kind)) (var i (type nested))
    (var j (type flat)) (var k (type lanes)))
  (transaction main (on start) (complete done)))
ISF
my %types = map { $_->{type} => $_->{type_spec} } @{$actor->{storage}};
my $scalar = {kind => 'bits', width => 7, signed => 0};

subtest 'validation preserves caller JSON kinds on first touch' => sub {
    my $json = JSON::PP->new->canonical;
    my $string_frame = $json->decode('{"kind":"record","width":"8","signed":0,"member_order":["flag","data"],'
        . '"members":{"flag":{"kind":"bit","width":"1","signed":0},'
        . '"data":{"kind":"bits","width":"7","signed":0}}}');
    my $roots = {packet => {role => 'input', type_spec => $string_frame}};
    my $before = $json->encode($roots);
    record_value_scope(outer => $roots, local => {});
    is($json->encode($roots), $before, 'scope validation retains original typed JSON');
    my $scope = {packet => {role => 'input', type_spec => $json->decode($before)->{packet}{type_spec}}};
    $before = $json->encode($scope);
    record_value_reference(scope => $scope, token => 'packet.data', access => 'read', context => 'first touch');
    is($json->encode($scope), $before, 'reference validation retains original typed JSON');
    my $source = {root => 'packet', role => 'input', path_text => '', width => '8',
        type_spec => $json->decode($before)->{packet}{type_spec}};
    my $target = dclone($source);
    @{$target}{qw(root role)} = ('held', 'storage');
    $before = $json->encode([$source, $target]);
    validate_record_port_copy(source => $source, target => $target, context => 'first touch');
    is($json->encode([$source, $target]), $before, 'copy validation retains original typed JSON');
};

sub scope_for {
    my ($source_type, $target_type, $local) = @_;
    return record_value_scope(outer => {
        packet => {role => 'input', type_spec => $source_type},
        held => {role => 'storage', type_spec => $target_type},
        output => {role => 'output', type_spec => $target_type},
        scalar => {role => 'output', type_spec => $scalar},
    }, local => $local || {});
}
sub reference {
    my ($scope, $token, $access, $whole) = @_;
    return record_value_reference(scope => $scope, token => $token,
        access => $access || 'read', allow_whole => $whole || 0, context => 'control');
}
sub copy {
    my ($scope, $source, $target) = @_;
    return validate_record_port_copy(source => reference($scope, $source, 'read', 1),
        target => reference($scope, $target, 'write', 1), context => 'copy control');
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval { $run->(); 1 };
    my $diagnostic = diagnostic_line($@);
    ok(!$ok, "$name refuses");
    like($diagnostic, $pattern, "$name names the cause in its diagnostic line");
}
sub diagnostic_line { (split /\n/, $_[0] // '')[0] // '' }
sub wrong_cause_with_pattern_in_stack {
    my ($expected) = @_;
    eval { confess "Deliberately wrong diagnostic\n" };
    return $@;
}

subtest 'diagnostic oracle rejects an expected pattern present only in the stack' => sub {
    my $error = wrong_cause_with_pattern_in_stack(qr/expected_cause_only_in_argument/);
    like($error, qr/expected_cause_only_in_argument/, 'known bad full trace contains the caller pattern');
    is(diagnostic_line($error), 'Deliberately wrong diagnostic', 'oracle selects the actual message');
    unlike(diagnostic_line($error), qr/expected_cause_only_in_argument/,
        'the same false cause cannot satisfy the diagnostic oracle');
};

subtest 'resolved alias identity and allowed root roles' => sub {
    my $scope = scope_for($types{frame}, $types{alias});
    ok(copy($scope, 'packet', 'held'), 'input to owner storage accepts resolved alias equivalence');
    ok(copy($scope, 'held', 'output'), 'prepared storage to output contract accepts identity');
    ok(copy($scope, 'packet', 'output'), 'prepared input to output contract accepts identity');
    my $source = reference($scope, 'packet', 'read', 1);
    my $target = reference($scope, 'packet', 'read', 1);
    refuses(sub { validate_record_port_copy(source => $source, target => $target,
        context => 'forged write') }, qr/forged write cannot write declared input 'packet'/,
        'copy independently enforces target role');
    refuses(sub { reference($scope, 'packet', 'write', 1) }, qr/cannot write declared input 'packet'/,
        'whole input target');
    refuses(sub { reference($scope, 'packet.data', 'write') }, qr/cannot write declared input 'packet.data'/,
        'scalar input target');
    ok(reference($scope, 'output.data', 'write'), 'prepared scalar output target retains allowed role');
    my $before = dclone($actor);
    $scope->{packet}{type_spec}{members}{data}{width} = 99;
    is_deeply($actor, $before, 'prepared scope does not share parser types');
};

subtest 'same packed width does not establish record identity' => sub {
    for my $name (qw(renamed reordered signed_data four two bit_kind)) {
        is($types{$name}{width}, 8, "$name has independently expected equal packed width");
        my $scope = scope_for($types{frame}, $types{$name});
        refuses(sub { copy($scope, 'packet', 'held') }, qr/requires the same resolved record type/,
            "$name copy identity");
    }
    my $scope = scope_for($types{four}, $types{two});
    refuses(sub { copy($scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'explicit state-model difference');
    for my $name (qw(signed_data four two bit_kind)) {
        ok(FSM::Package::PayloadTypeSupport->payload_compatible_with_type_spec($types{frame}, $types{$name}),
            "$name retains the established payload compatibility contract");
    }
    my $nested_scope = scope_for($types{nested}, $types{flat});
    is($types{nested}{width}, 8, 'independent nested packed width');
    is($types{flat}{width}, 8, 'independent flattened packed width');
    refuses(sub { copy($nested_scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'nested shape cannot be flattened for copy identity');
    my $swapped = dclone($types{nested});
    @{$swapped->{members}{body}{members}{lanes}{items}} =
        reverse @{$swapped->{members}{body}{members}{lanes}{items}};
    my $list_scope = scope_for($types{nested}, $swapped);
    refuses(sub { copy($list_scope, 'packet', 'held') }, qr/requires the same resolved record type/,
        'nested list item order retains type identity');
};

subtest 'core scalar paths retain exact packed range and property facts' => sub {
    my $scope = scope_for($types{nested}, $types{nested});
    is_deeply(reference($scope, 'packet.body.count'), {
        root => 'packet', role => 'input', path_text => '.body.count',
        type_spec => {kind => 'bits', width => 3, signed => 1, state_model => 'four_state'},
        width => 3, low => 3, high => 5,
    }, 'independent nested signed/four-state leaf range');
    is_deeply(reference($scope, 'packet.body.lanes[0]'), {
        root => 'packet', role => 'input', path_text => '.body.lanes[0]',
        type_spec => {kind => 'bit', width => 1, signed => 0, state_model => 'two_state'},
        width => 1, low => 2, high => 2,
    }, 'independent nested list-item leaf range');
    my $leaf = reference($scope, 'packet.body.count');
    $leaf->{type_spec}{signed} = 0;
    is(reference($scope, 'packet.body.count')->{type_spec}{signed}, 1,
        'leaf results do not share scope facts');
    for my $pair (
        ['packet', qr/requires a scalar value/],
        ['packet.body', qr/requires a scalar leaf/],
        ['packet.body.lanes', qr/requires a scalar leaf/],
        ['packet.unknown', qr/invalid declared path.*unknown_member/],
        ['packet.body.lanes[2]', qr/invalid declared path.*list_index_out_of_range/],
        ['packet.body.count[3]', qr/invalid declared path.*scalar_index_out_of_range/],
        ['packet..count', qr/invalid declared path.*parse_error/],
    ) {
        refuses(sub { reference($scope, $pair->[0]) }, $pair->[1], $pair->[0]);
    }
    refuses(sub { reference($scope, 'held.body', 'write', 1) }, qr/requires a scalar leaf/,
        'whole-value permission does not allow subaggregate writes');
};

subtest 'nearest lexical declarations mask outer type and role facts' => sub {
    my $unresolved = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'local', type_spec => undef},
    });
    is(reference($unresolved, 'packet.data'), undef, 'unresolved local masks the outer record type');
    my $formal = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'output', type_spec => $types{nested}},
    });
    my $leaf = reference($formal, 'packet.body.count', 'write');
    is($leaf->{role}, 'output', 'nearest formal output is writable despite outer input name');
    is($leaf->{width}, 3, 'formal type owns local path width');
    refuses(sub { reference($formal, 'packet.data') }, qr/unknown_member/,
        'formal does not borrow an outer member');
    my $scalar_shadow = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'local', type_spec => $scalar},
    });
    is(reference($scalar_shadow, 'packet', 'write')->{width}, 7,
        'scalar local retains its width and writable role');
    refuses(sub { reference($scalar_shadow, 'packet.data') }, qr/member_on_non_record/,
        'scalar local cannot borrow an outer record');
    is_deeply(reference($scalar_shadow, 'packet[5:3]', 'write'), {
        root => 'packet', role => 'local', path_text => '[5:3]',
        type_spec => {kind => 'bits', width => 3, signed => 0},
        width => 3, low => 3, high => 5,
    }, 'scalar local slice retains core range and writable local role');
    is(reference($scalar_shadow, 'packet[0]')->{width}, 1,
        'scalar local bit index stays scalar');
    my $unresolved_input = scope_for($types{frame}, $types{frame}, {
        packet => {role => 'input', type_spec => undef},
    });
    refuses(sub { reference($unresolved_input, 'packet', 'write') }, qr/cannot write declared input/,
        'an unresolved type cannot erase a known input role');
    is(reference($formal, 'mode.BUSY'), undef, 'unrelated enum roots stay with existing enum validation');
    is(reference($formal, 'shared.CONSTANT'), undef, 'unrelated package roots stay with package validation');
};

subtest 'record copy gates preserve existing scalar and storage-only contracts' => sub {
    my $scope = scope_for($types{frame}, $types{signed_data});
    $scope->{old} = {role => 'storage', type_spec => dclone($types{frame})};
    is(copy($scope, 'old', 'held'), 0, 'different storage-only types use the prior assignment contract');
    is(copy($scope, 'scalar', 'scalar'), 0, 'scalar ports introduce no record copy obligation');
    is(validate_record_port_copy(source => undef, target => undef, context => 'literal'), 0,
        'unrelated literal/expression handling remains with caller');
    refuses(sub { copy($scope, 'scalar', 'output') }, qr/requires declared record roots/,
        'equal/unequal scalar carrier is not a record copy');
    refuses(sub { validate_record_port_copy(source => undef,
        target => reference($scope, 'output', 'write', 1), context => 'expression') },
        qr/requires declared record roots/, 'record target cannot treat an expression as a same-type root');
    $scope->{lanes} = {role => 'storage', type_spec => dclone($types{lanes})};
    is(reference($scope, 'lanes[1]')->{width}, 2, 'existing list storage scalar leaves remain resolvable');
    refuses(sub { copy($scope, 'lanes', 'output') }, qr/requires declared record roots/,
        'root list is not a same-type record copy');
};

subtest 'imported and local aliases with identical resolved records match' => sub {
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (flag bit) (data (bits 7))))))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (output done)) (storage (var value (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    my $scope = scope_for($imported->{storage}[0]{type_spec}, $types{frame});
    ok(copy($scope, 'packet', 'held'), 'package spelling does not affect resolved identity');
};

subtest 'closed malformed facts fail before comparison or path traversal' => sub {
    for my $pair (
        ['unknown key', sub { $_[0]{extra} = 1 }, qr/unknown facts/],
        ['bad root width', sub { $_[0]{width} = 9 }, qr/width disagrees/],
        ['bad scalar signed', sub { $_[0]{members}{data}{signed} = 2 }, qr/signed property/],
        ['missing signed', sub { delete $_[0]{members}{data}{signed} }, qr/lacks required facts/],
        ['aggregate signed', sub { $_[0]{signed} = 1 }, qr/scalar signed overlay/],
        ['aggregate state', sub { $_[0]{state_model} = 'two_state' }, qr/unknown facts/],
        ['bad state', sub { $_[0]{members}{data}{state_model} = 'unknown' }, qr/state model/],
        ['duplicate order', sub { $_[0]{member_order} = [qw(flag flag)] }, qr/duplicate record member/],
        ['unlisted member', sub { $_[0]{members}{extra} = dclone($scalar) }, qr/inventory disagrees/],
        ['cyclic member', sub { $_[0]{members}{data} = $_[0] }, qr/cyclic resolved type/],
        ['deferred kind', sub { $_[0]{kind} = 'deferred_imported_alias' }, qr/unsupported resolved type kind/],
    ) {
        my $spec = dclone($types{frame});
        $pair->[1]->($spec);
        refuses(sub { scope_for($spec, $types{frame}) }, $pair->[2], $pair->[0]);
    }
    refuses(sub { record_value_scope(outer => {packet => {role => 'inout', type_spec => $types{frame}}},
        local => {}) }, qr/invalid role/, 'unknown role');
    refuses(sub { record_value_scope(outer => {}, local => {}, surprise => 1) }, qr/unknown facts/,
        'unknown scope argument');
    my $scope = scope_for($types{frame}, $types{frame});
    refuses(sub { record_value_reference(scope => $scope, token => 'packet', access => 'read',
        context => 'permission', allow_whole => 2) }, qr/whole-value permission/,
        'nonbinary whole-value permission');
    my $value = reference($scope, 'packet', 'read', 1);
    $value->{width} = 9;
    refuses(sub { validate_record_port_copy(source => $value,
        target => reference($scope, 'held', 'write', 1), context => 'hostile') }, qr/width disagrees/,
        'contradictory copy descriptor');
};

subtest 'output member writes and list-root source carriers remain closed' => sub {
    for my $pair (
        ['output', 'frame', '(set value.flag 1)', qr/record output field writes are not yet admitted/],
        ['input', 'lanes', '(complete done)', qr/interface port 'value' references aggregate type/],
    ) {
        my ($direction, $type, $clause, $pattern) = @$pair;
        my $source = '(actor refused (types (type frame (record (flag bit))) (type lanes (list bit bit)))'
            . " (interface ($direction value (type $type)) (output done))"
            . " (transaction main $clause))";
        refuses(sub { $parser->parse_source($source, 'still-refused.isf') }, $pattern,
            "$direction $type source");
    }
};

done_testing;

sources.t/1987-isf-record-port-declaration-scope:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Storable qw(dclone);
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortScopes qw(
    record_actor_scope record_transaction_scope record_drive_scope
);
use FSM::Support::ISFRecordPortValues qw(record_value_reference);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor scopes
  (params (W 8))
  (types (type frame (record (header (bits 2))
      (payload (signed (four_state (bits 6))))))
    (type word (signed (two_state (bits 5)))))
  (interface (input start) (input data (width W)) (output seen (width 8)) (output done))
  (storage (var packet (type frame)) (var backup (type frame)))
  (drive (publish packet) (seen packet))
  (transaction worker (ports (output packet (type word)) (input arg (width W)))
    (local count (width 3) (default 0)) (set packet arg))
  (transaction main (on start) (set seen packet.payload) (complete done)))
ISF
my $actor = $parser->parse_source($source, 'scope-controls.isf');

subtest 'first projection preserves complete fresh copied parsed scalar kinds' => sub {
    my $unread = $source =~ s/\(set seen packet.payload\)/(set seen 0)/r;
    for my $kind (qw(actor transaction drive)) {
        my $fresh = dclone($parser->parse_source($unread, 'first-touch-scope.isf'));
        my $before = $json->encode($fresh);
        record_actor_scope(actor => $fresh) if $kind eq 'actor';
        record_transaction_scope(actor => $fresh, transaction => $fresh->{transactions}[0]) if $kind eq 'transaction';
        record_drive_scope(actor => $fresh, drive => $fresh->{drives}{publish}) if $kind eq 'drive';
        is($json->encode($fresh), $before, "$kind first projection preserves complete actor JSON kinds");
    }
};

sub reference {
    my ($scope, $token, $access) = @_;
    return record_value_reference(scope => $scope, token => $token,
        access => $access || 'read', context => 'scope control');
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
}

subtest 'actual finalized actor declarations retain role and type facts' => sub {
    my $scope = record_actor_scope(actor => $actor);
    is_deeply([sort keys %$scope], [qw(backup data done packet seen start)], 'declared roots only');
    is_deeply($scope->{data}, {role => 'input',
        type_spec => {kind => 'bits', width => 8, signed => 0}},
        'resolved symbolic input retains declared width and role');
    is($scope->{packet}{role}, 'storage', 'record root retains storage role');
    is_deeply(reference($scope, 'packet.payload'), {
        root => 'packet', role => 'storage', path_text => '.payload', width => 6, low => 0, high => 5,
        type_spec => {kind => 'bits', width => 6, signed => 1, state_model => 'four_state'},
    }, 'independent packed leaf witness retains signed/state and range');
    is_deeply([@{reference($scope, 'packet.header')}{qw(width low high)}], [2, 6, 7],
        'first authored member is most significant');
    refuses(sub {reference($scope, 'data', 'write')}, qr/cannot write declared input 'data'/,
        'declared actor input cannot become a write');
    my $conflicting = dclone($actor);
    push @{$conflicting->{storage}}, {kind => 'var', name => 'data', width => 8,
        type => 'frame', type_spec => dclone($actor->{storage}[0]{type_spec})};
    is(record_actor_scope(actor => $conflicting)->{data}{role}, 'input',
        'caller-supplied conflicting storage cannot erase a pin role');
    refuses(sub {$parser->parse_source($source =~ s/backup/data/r, 'conflicting.isf')},
        qr/storage signal 'data' conflicts with interface input port 'data'/,
        'projection does not admit authored actor/storage collisions');
    ok(!exists($scope->{publish}) && !exists($scope->{worker}), 'drive and transaction names are not value declarations');
};

subtest 'actual transaction formals and locals mask outer facts' => sub {
    my $scope = record_transaction_scope(actor => $actor, transaction => $actor->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'output',
        type_spec => {kind => 'bits', width => 5, signed => 1, state_model => 'two_state'}},
        'formal replaces outer record with its own resolved scalar');
    is_deeply($scope->{arg}, {role => 'input', type_spec => {kind => 'bits', width => 8, signed => 0}},
        'formal symbolic width is finalized');
    is_deeply($scope->{count}, {role => 'local', type_spec => {kind => 'bits', width => 3, signed => 0}},
        'explicit local width has no borrowed alias, reset or state overlay');
    is_deeply([@{reference($scope, 'packet[3:1]')}{qw(width low high)}], [3, 1, 3],
        'formal slice resolves against local scalar width');
    refuses(sub {reference($scope, 'packet.payload')}, qr/member_on_non_record/,
        'shadow cannot borrow outer member');
    refuses(sub {reference($scope, 'arg', 'write')}, qr/cannot write declared input 'arg'/,
        'formal input retains its own role');
};

subtest 'unresolved declarations mask without using parser placeholders' => sub {
    my $unresolved = dclone($actor);
    delete $unresolved->{transactions}[0]{ports}{outputs}[0]{type_spec};
    $unresolved->{transactions}[0]{ports}{outputs}[0]{width} = 1;
    my $scope = record_transaction_scope(actor => $unresolved, transaction => $unresolved->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'output', type_spec => undef},
        'typed formal placeholder remains unknown');
    is(reference($scope, 'packet.payload'), undef, 'unresolved formal never falls through to outer record');
    my $symbolic = $parser->parse_source($source =~ s/\(width 3\)/\(width W\)/r, 'symbolic-local.isf');
    $scope = record_transaction_scope(actor => $symbolic, transaction => $symbolic->{transactions}[0]);
    is_deeply($scope->{count}, {role => 'local', type_spec => undef},
        'local symbolic width is not finalized by actor port-width resolution');
    refuses(sub {FSM::Scheduler::ISF->new->lower($symbolic)}, qr/requires a '\(width N\)' with a positive integer/,
        'projection does not admit unsupported symbolic locals');
    my $local_shadow = dclone($actor);
    push @{$local_shadow->{transactions}[0]{clauses}}, ['local', 'packet', ['width', 'UNKNOWN']];
    $scope = record_transaction_scope(actor => $local_shadow, transaction => $local_shadow->{transactions}[0]);
    is_deeply($scope->{packet}, {role => 'local', type_spec => undef},
        'explicit unresolved local masks formal and actor type facts');
    my $unknown_input = dclone($actor);
    $unknown_input->{interface}{inputs}[1] = {name => 'data', type => 'unresolved', width => 1};
    $scope = record_actor_scope(actor => $unknown_input);
    is_deeply($scope->{data}, {role => 'input', type_spec => undef},
        'unresolved actor input retains role without its placeholder width');
    refuses(sub {reference($scope, 'data', 'write')}, qr/cannot write declared input 'data'/,
        'unknown type cannot erase known input role');
    my $collision = $parser->parse_source($source =~ s/\(local count/\(local data/r, 'local-collision.isf');
    refuses(sub {FSM::Scheduler::ISF->new->lower($collision)},
        qr/collides with interface port 'data'/, 'projection does not admit explicit local pin collisions');
};

subtest 'drive parameter names mask records without inferred type facts' => sub {
    my $scope = record_drive_scope(actor => $actor, drive => $actor->{drives}{publish});
    is_deeply($scope->{packet}, {role => 'local', type_spec => undef}, 'untyped parameter is unknown');
    is(reference($scope, 'packet.payload'), undef, 'parameter cannot inherit actor record layout');
    is(reference($scope, 'seen')->{width}, 8, 'unshadowed actor output retains actual width');
    $scope = record_drive_scope(actor => $actor, drive => {params => ['data'], body => []});
    is_deeply($scope->{data}, {role => 'local', type_spec => undef}, 'parameter masks actor role as well as type');
};

subtest 'scopes add no inferred declarations and detach from actor facts' => sub {
    my $before = $json->encode($actor);
    my $tx = dclone($actor->{transactions}[1]);
    push @{$tx->{clauses}}, ['set', 'data', 0], ['set', 'invented', 1];
    my $scope = record_transaction_scope(actor => $actor, transaction => $tx);
    is($scope->{data}{role}, 'input', 'assignment does not redefine actor input');
    ok(!exists($scope->{invented}), 'assignment target is not a declaration');
    $scope->{packet}{type_spec}{members}{payload}{width} = 999;
    $scope->{data}{role} = 'local';
    is($json->encode($actor), $before, 'mutating projection leaves complete actor unchanged');
    is(record_actor_scope(actor => $actor)->{packet}{type_spec}{members}{payload}{width}, 6,
        'fresh projection does not reuse mutated output');
};

subtest 'imported alias and prepared record pin keep actual resolved facts' => sub {
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (header (bits 2)) '
        . '(payload (signed (four_state (bits 6))))))))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (output done)) (storage (var value (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    is_deeply(record_actor_scope(actor => $imported)->{value}{type_spec},
        record_actor_scope(actor => $actor)->{packet}{type_spec}, 'local and imported resolved identity matches');
    my $prepared = dclone($imported);
    $prepared->{interface}{inputs} = [dclone($prepared->{storage}[0])];
    my $scope = record_actor_scope(actor => $prepared);
    is($scope->{value}{role}, 'input', 'supplied resolved record declaration retains input role');
    refuses(sub {reference($scope, 'value.payload', 'write')}, qr/cannot write declared input 'value.payload'/,
        'prepared input leaf cannot become a write');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (x bit))))'
        . ' (interface (output value (type frame)) (output done))'
        . ' (transaction main (set value.x 1) (complete done)))', 'field-refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer stays refused');
};

subtest 'scope preparation leaves complete parser and scheduled products unchanged' => sub {
    my $safe = $parser->parse_source($source, 'scope-controls.isf');
    my $before_actor = $json->encode($safe);
    my $before_lowered = $json->encode(FSM::Scheduler::ISF->new->lower(dclone($safe)));
    record_actor_scope(actor => $safe);
    record_transaction_scope(actor => $safe, transaction => $_) for @{$safe->{transactions}};
    record_drive_scope(actor => $safe, drive => $_) for values %{$safe->{drives}};
    is($json->encode($safe), $before_actor, 'complete parsed actor unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower(dclone($safe))), $before_lowered,
        'complete scheduled object and actual emitted file bytes unchanged');
};

subtest 'malformed declaration facts fail without accidental fallback' => sub {
    my $bad = dclone($actor);
    $bad->{interface}{outputs}[0]{name} = 'start';
    refuses(sub {record_actor_scope(actor => $bad)}, qr/duplicate port 'start'/, 'duplicate interface role');
    $bad = dclone($actor);
    $bad->{storage}[0]{width} = 9;
    refuses(sub {record_actor_scope(actor => $bad)}, qr/resolved type disagrees with declared width/,
        'mismatched declared packed width');
    refuses(sub {record_drive_scope(actor => $actor, drive => {params => ['bad.name']})},
        qr/drive parameter requires an identifier/, 'invalid parameter root');
    refuses(sub {record_actor_scope(actor => $actor, extra => 1)}, qr/unknown scope argument/,
        'closed helper arguments');
};

done_testing;

sources.t/1988-isf-record-port-context-gates.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Storable qw(dclone);
use JSON::PP;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor contexts
  (types (type frame (record (flag bit) (data (signed (four_state (bits 7))))))
    (type alias frame) (type other (record (flag bit) (data (bits 7)))))
  (enums (mode (IDLE 0) (BUSY 1)))
  (interface (input start) (input scalar (width 8)) (output seen (width 8)) (output done))
  (storage (var packet (type frame)) (var held (type alias)) (var mismatch (type other)))
  (transaction main (on start) (set held packet) (set seen packet.data) (complete done)))
ISF
my $original = $parser->parse_source($source, 'record-context-controls.isf');
my $prepared = dclone($original);
my $port = shift @{$prepared->{storage}};
push @{$prepared->{interface}{inputs}}, {map {$_ => $port->{$_}} qw(name width type type_spec)};

sub transaction {
    my (@clauses) = @_;
    my $actor = dclone($prepared);
    $actor->{transactions}[0]{clauses} = \@clauses;
    return $actor;
}
sub rules {
    my ($guard, @actions) = @_;
    my $actor = transaction();
    $actor->{rules} = [{name => 'copy', when => ['when', $guard], actions => \@actions}];
    return $actor;
}
sub drives {
    my ($params, @body) = @_;
    my $actor = transaction();
    $actor->{drives} = {publish => {params => $params, body => \@body}};
    return $actor;
}
sub accepts {
    my ($actor, $name) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {validate_actor_record_contexts(actor => $actor); 1};
    ok($ok, "$name validates") or diag((split /\n/, $@)[0]);
    is($json->encode($actor), $before, "$name leaves complete actor unchanged");
}
sub refuses {
    my ($actor, $pattern, $name) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {validate_actor_record_contexts(actor => $actor); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
    is($json->encode($actor), $before, "$name leaves complete actor unchanged");
}

subtest 'selected transaction scalar contexts retain scalar leaves' => sub {
    accepts(transaction(['set', 'seen', 'packet.data']), 'set scalar leaf');
    accepts(transaction(['update', 'seen', ['+', 'packet.data[3:1]', 'scalar']]), 'update expression and leaf slice');
    for my $head (qw(when while until)) {
        accepts(transaction([$head, ['==', 'packet.flag', 1], ['set', 'seen', 'packet.data']]), "$head body");
        accepts(transaction([$head, '!packet.flag', ['set', 'seen', 1]]), "$head compact negation");
        accepts(transaction([$head, '1==packet.flag', ['set', 'seen', 1]]), "$head compact comparison");
    }
    accepts(transaction(['repeat', 2, ['when', 'packet.flag', ['set', 'seen', 'packet.data']]]), 'repeat nested body');
    accepts(transaction(['switch', 'packet.data', ['packet.flag', ['set', 'seen', 'packet.data']],
        ['default', ['set', 'seen', 0]]]), 'switch selector and branch values');
};

subtest 'whole record copies consume strict type and declared roles' => sub {
    accepts(transaction(['set', 'held', 'packet']), 'set input to equivalent alias storage');
    accepts(transaction(['update', 'held', 'packet']), 'update whole copy');
    accepts(rules('packet.flag', ['set', 'held', 'packet']), 'rule whole copy');
    accepts(rules(['==', 'packet.flag', 1], ['held', 'packet']), 'rule shorthand whole copy');
    accepts(drives([], ['held', 'packet']), 'named drive whole copy');
    accepts(transaction(['drive', 'inline', ['held', 'packet']]), 'inline drive whole copy');
    for my $head (qw(set update)) {
        refuses(transaction([$head, 'mismatch', 'packet']), qr/requires the same resolved record type/,
            "$head equal-width signed/state mismatch");
        refuses(transaction([$head, 'seen', 'packet']), qr/whole record port copy requires declared record roots/,
            "$head whole record to scalar");
        refuses(transaction([$head, 'held.data', 'packet']), qr/whole record port copy requires declared record roots/,
            "$head whole record to scalar leaf");
    }
};

subtest 'rule and drive scalar reads keep selected scope' => sub {
    accepts(rules('packet.flag', ['set', 'seen', ['+', 'packet.data', 'scalar']]), 'rule scalar guard and RHS');
    accepts(rules(['==', 'packet.data', 3], ['seen', 'packet.data']), 'rule expression guard and shorthand RHS');
    accepts(drives([], ['seen', ['+', 'packet.data', 'scalar']]), 'named drive leaf expression');
    accepts(transaction(['drive', 'inline', ['seen', 'packet.data']]), 'labeled inline drive');
    accepts(transaction(['drive', ['seen', 'packet.data']]), 'unlabeled inline drive');
    my $actor = transaction(['drive', 'publish', ['+', 'packet.data', 'scalar']]);
    $actor->{drives} = {publish => {params => ['value'], body => [['seen', 'value']]}};
    accepts($actor, 'named drive scalar actual');
    accepts(drives(['packet'], ['seen', 'packet']), 'untyped drive parameter masks actor record');
};

subtest 'scalar-only drive parameters reject members without inventing widths' => sub {
    for my $name (qw(packet value)) {
        accepts(drives([$name], ['seen', $name]), "$name bare scalar parameter");
        accepts(drives([$name], ['seen', "${name}[0]"]), "$name scalar slice remains delegated");
        for my $token ("$name.member", "$name.payload.data", "$name.member[0]",
            "${name}[0].member", "${name}[1:0].member") {
            refuses(drives([$name], ['seen', $token]), qr/member_on_non_record/,
                "$token parameter RHS");
            refuses(drives([$name], ['seen', ['+', 1, $token]]), qr/member_on_non_record/,
                "$token nested parameter RHS");
            refuses(drives([$name], [$token, 0]), qr/member_on_non_record/,
                "$token parameter target");
        }
    }
    my $shadow = drives(['packet'], ['seen', 'packet.data']);
    $shadow->{enum_symbols}{local}{packet} = {data => 1};
    refuses($shadow, qr/member_on_non_record/, 'enum cannot lend a masked record layout');
    my $namespaces = drives(['mode', 'shared'], ['seen', 'mode.BUSY'], ['seen', 'shared.LIMIT']);
    $namespaces->{constant_symbols}{packages}{shared} = {LIMIT => 1};
    accepts($namespaces, 'existing local enum and package namespaces retain their owner');
};

subtest 'every selected scalar context rejects whole record ports' => sub {
    for my $value ('packet', '!packet', 'packet==1', '1==packet', ['+', 1, 'packet']) {
        for my $head (qw(when while until)) {
            refuses(transaction([$head, $value, ['set', 'seen', 1]]), qr/requires a scalar value.*whole record port/,
                "$head whole record condition " . $json->encode($value));
        }
        refuses(transaction(['switch', $value, [0, ['set', 'seen', 1]]]),
            qr/requires a scalar value.*whole record port/, 'whole record switch selector');
        refuses(rules($value, ['seen', 1]), qr/requires a scalar value.*whole record port/, 'whole record rule guard');
        my $actor = transaction(['drive', 'publish', $value]);
        $actor->{drives} = {publish => {params => ['value'], body => [['seen', 'value']]}};
        refuses($actor, qr/requires a scalar value.*whole record port/, 'whole record drive actual');
    }
    refuses(transaction(['switch', 'scalar', ['packet', ['set', 'seen', 1]]]),
        qr/switch branch value requires a scalar value/, 'whole record switch branch');
    refuses(transaction(['set', 'seen', ['+', 1, 'packet']]), qr/requires a scalar value.*whole record port/,
        'whole record arithmetic RHS');
    refuses(transaction(['set', 'seen', ['packet.data', 1]]), qr/operator cannot use declared aggregate reference/,
        'leaf reference in expression operator position');
};

subtest 'known input targets and invalid paths fail in each assignment family' => sub {
    for my $target ('packet', 'packet.data') {
        for my $actor (
            transaction(['set', $target, 0]), transaction(['update', $target, 0]),
            rules('start', ['set', $target, 0]), rules('start', [$target, 0]),
            drives([], [$target, 0]), transaction(['drive', 'inline', [$target, 0]]),
            rules('start', ['pulse', $target]),
        ) {
            refuses($actor, qr/cannot write declared input '\Q$target\E'/, "input target $target");
        }
    }
    refuses(transaction(['set', 'seen', 'packet.missing']), qr/invalid declared path 'packet.missing': unknown_member/,
        'unknown declared record member');
    refuses(transaction(['set', 'seen', 'packet.data[7]']), qr/scalar_index_out_of_range/,
        'leaf index outside resolved width');
    my $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 3}]};
    refuses($shadow, qr/member_on_non_record/, 'scalar formal prevents outer record lookup');
    $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 1, type => 'unresolved'}]};
    accepts($shadow, 'unresolved formal is delegated without outer type borrowing');
};

subtest 'unselected source contexts do not inherit leaf-read permission' => sub {
    for my $clause (
        ['wait', 'packet.data'], ['repeat', 'packet.data', ['set', 'seen', 1]],
        ['on', 'packet.flag'],
    ) {
        refuses(transaction($clause), qr/does not admit record port reference/,
            'unselected ' . $clause->[0]);
    }
};

subtest 'legacy storage and unrelated tokens remain under existing validators' => sub {
    accepts(dclone($original), 'actual admitted record storage and scalar-port source');
    my $actor = transaction(['set', 'held', 'mismatch'], ['set', 'seen', 'mode.BUSY'],
        ['when', ['==', 'shared.LIMIT', "scalar'8"], ['set', 'seen', 1]],
        ['when', ['state_active', 'packet'], ['set', 'seen', 1]]);
    accepts($actor, 'storage-only packed transfers and enum/package/scalar annotations');
    accepts(transaction(['set', 'seen', 'unknown.member']), 'unknown token remains delegated');
    my $enum_pin = $parser->parse_source('(actor enum_pin (enums (mode (BUSY 1)))'
        . ' (interface (input mode) (output seen)) (transaction main (set seen mode.BUSY)))', 'enum-pin.isf');
    accepts($enum_pin, 'actual admitted enum namespace sharing a scalar pin name');
    my $shadow = transaction(['set', 'seen', 'packet.data']);
    $shadow->{enum_symbols}{local}{packet} = {data => 1};
    $shadow->{transactions}[0]{ports} = {inputs => [], outputs => [{name => 'packet', width => 3}]};
    refuses($shadow, qr/member_on_non_record/,
        'enum token cannot supply a shadowed actor aggregate member');
    my $before = $json->encode($original);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower(dclone($original)));
    validate_actor_record_contexts(actor => $original);
    is($json->encode($original), $before, 'complete actual parsed actor unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower(dclone($original))), $lowered,
        'complete scheduled object and emitted source bytes unchanged');
};

done_testing;

sources.t/1989-isf-record-port-root-classificati:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Support::ISFRecordPortScopes qw(record_context_scope record_reference_root_kind);
use FSM::Support::ISFRecordPortValues qw(record_value_reference);
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $actor = $parser->parse_source(<<'ISF', 'root-controls.isf');
(actor roots
  (params (W 8)) (constants (K 1))
  (types (type frame (record (flag bit) (payload (bits 7)))) (type alias frame))
  (enums (mode (BUSY 1)) (packet (payload 1)))
  (interface (input start) (input mode) (output seen (width W)) (output done))
  (storage (var packet (type frame)) (var held (type alias)))
  (drive (publish packet) (seen packet))
  (transaction worker (ports (output packet (width 3)))
    (local count (width 2)) (set packet 1))
  (transaction main (on start) (set seen packet.payload) (complete done)))
ISF

sub classify {
    my ($context, $token) = @_;
    return record_reference_root_kind(context => $context, token => $token);
}
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names its first-line cause");
}

subtest 'actual declarations produce one coherent consumer projection' => sub {
    my $context = record_context_scope(actor => $actor);
    is_deeply([sort keys %$context], [qw(aggregate_roots enum_exclusion_roots namespaces roots rule_declared_roots scalar_parameter_roots)],
        'complete projection has only the selected consumer maps');
    is_deeply($context->{scalar_parameter_roots}, {}, 'outer actor statics do not invent lexical drive masks');
    is_deeply([sort keys %{$context->{roots}}], [qw(done held mode packet seen start)],
        'values are declarations rather than inferred assignment/constant names');
    is_deeply([sort keys %{$context->{aggregate_roots}}], [qw(held packet)], 'actor aggregates retain resolved identities');
    is_deeply($context->{enum_exclusion_roots}, {held => 1, packet => 1},
        'aggregate roots prevent namespace interpretation');
    is_deeply($context->{namespaces}, {mode => 1, packet => 1}, 'actual local enum families remain namespaces');
    is_deeply([sort keys %{$context->{rule_declared_roots}}], [qw(K W clk done held mode packet rst_n seen start)],
        'independent rule-declaration witness includes actor statics and system pins');
    is(classify($context, 'mode.BUSY'), 'namespace', 'scalar pin can share enum family name');
    is(classify($context, 'packet.payload'), 'declaration', 'declared record wins over same-named enum family');
    is(classify($context, 'packet.missing'), 'declaration', 'unknown member remains with declared path validator');
    is(classify($context, 'mode.MISSING'), 'namespace', 'unknown enum member remains with enum validator');
    is(classify($context, 'seen[3:0]'), 'declaration', 'scalar bit/slice root retains declaration');
    is(classify($context, 'not_declared.member'), undef, 'unknown namespace does not invent a declaration');
    is(classify($context, 17), undef, 'literal is not a declaration reference');
};

subtest 'nearest formal and local scopes suppress borrowed aggregate namespaces' => sub {
    my $context = record_context_scope(actor => $actor, transaction => $actor->{transactions}[0]);
    is_deeply([sort keys %{$context->{aggregate_roots}}], ['held'], 'scalar formal removes outer aggregate from traversal roots');
    is_deeply($context->{enum_exclusion_roots}, {held => 1, packet => 1},
        'shadowed outer record remains excluded from enum fallback');
    is(classify($context, 'packet.payload'), 'declaration', 'formal path is not borrowed enum token');
    refuses(sub {record_value_reference(scope => $context->{roots}, token => 'packet.payload',
        access => 'read', context => 'formal path')}, qr/member_on_non_record/, 'scalar formal member access');
    is_deeply([@{record_value_reference(scope => $context->{roots}, token => 'packet[2:1]',
        access => 'read', context => 'formal slice')}{qw(width low high)}], [2, 1, 2],
        'formal slice uses its independent local width');
    ok(exists($context->{roots}{count}) && !exists($context->{rule_declared_roots}{count}),
        'transaction local cannot become an actor rule read operand');
    my $unknown = dclone($actor->{transactions}[0]);
    $unknown->{ports}{outputs}[0] = {name => 'packet', width => 1, type => 'unresolved'};
    $context = record_context_scope(actor => $actor, transaction => $unknown);
    is($context->{roots}{packet}{type_spec}, undef, 'unresolved type stays unknown');
    is(classify($context, 'packet.payload'), 'declaration', 'unresolved formal still masks namespace and outer layout');
    is(record_value_reference(scope => $context->{roots}, token => 'packet.payload', access => 'read',
        context => 'unknown formal'), undef, 'unknown fact is delegated without invented type');
};

subtest 'drive and supplied record pin scopes retain real declaration roles' => sub {
    my $context = record_context_scope(actor => $actor, drive => $actor->{drives}{publish});
    is_deeply($context->{scalar_parameter_roots}, {packet => 1}, 'explicit drive formal supplies its exact scalar mask');
    is_deeply($context->{roots}{packet}, {role => 'local', type_spec => undef}, 'parameter masks outer record');
    is(classify($context, 'packet.payload'), 'declaration', 'untyped parameter cannot borrow enum member');
    my $prepared = dclone($actor);
    my $packet = shift @{$prepared->{storage}};
    push @{$prepared->{interface}{inputs}}, {map {$_ => $packet->{$_}} qw(name width type type_spec)};
    $context = record_context_scope(actor => $prepared);
    is($context->{roots}{packet}{role}, 'input', 'supplied record declaration keeps input role');
    is_deeply([sort keys %{$context->{aggregate_roots}}], [qw(held packet)], 'record pins and storage share resolved traversal facts');
    refuses(sub {record_value_reference(scope => $context->{roots}, token => 'packet.payload',
        access => 'write', context => 'input field')}, qr/cannot write declared input/, 'declared input field');
};

subtest 'package namespace and named-domain rules retain existing owners' => sub {
    my $supplied = dclone($actor);
    $supplied->{enum_symbols}{packages} = {shared => {mode => {BUSY => 1}}};
    $supplied->{constant_symbols}{packages} = {limits => {MAX => {kind => 'scalar', payload => 8}}};
    push @{$supplied->{interface}{inputs}}, {name => 'shared', width => 1}, {name => 'limits', width => 1};
    my $context = record_context_scope(actor => $supplied);
    is(classify($context, 'shared.mode.BUSY'), 'namespace', 'package enum is not a scalar-pin member');
    is(classify($context, 'limits.MAX'), 'namespace', 'package constant remains with existing static/value validator');
    my $work = tempdir(CLEANUP => 1);
    open my $file, '>', "$work/shared.fsm" or die $!;
    print {$file} '(?pkg:shared (+types (type frame (record (flag bit) (payload (bits 7)))))'
        . ' (+enums (mode (BUSY 1))) (+constants (MAX 8)))';
    close $file or die $!;
    my $imported = $parser->parse_source('(actor imported (imports (package shared))'
        . ' (interface (input shared) (output done)) (storage (var frame (type shared.frame)))'
        . ' (transaction main (complete done)))', "$work/imported.isf");
    $context = record_context_scope(actor => $imported);
    is(classify($context, 'shared.mode.BUSY'), 'namespace', 'actual imported enum remains in package namespace');
    is(classify($context, 'shared.MAX'), 'namespace', 'actual imported constant retains its package owner');
    is_deeply($context->{aggregate_roots}{frame}, record_context_scope(actor => $actor)->{aggregate_roots}{packet},
        'actual imported aggregate retains equivalent resolved traversal facts');
    my $named = $parser->parse_source('(actor named (clock-domains'
        . ' (domain core (clock core_clk) (reset (core_rst async active_low)) :default)'
        . ' (domain aux (clock aux_clk) (reset (aux_rst sync active_high))))'
        . ' (interface (input start) (output done)) (transaction main (on start) (complete done)))',
        'named-rule-roots.isf');
    $context = record_context_scope(actor => $named);
    is_deeply([sort keys %{$context->{rule_declared_roots}}], [qw(aux_clk aux_rst core_clk core_rst done start)],
        'independent named-domain clock/reset declaration witness');
    is_deeply([sort keys %{$context->{roots}}], [qw(done start)], 'system names are not invented value/type roots');
};

subtest 'fresh copied facts stay detached across every consumer map' => sub {
    for my $kind (qw(actor transaction drive)) {
        my $fresh = dclone($actor);
        my %selection;
        $selection{transaction} = $fresh->{transactions}[0] if $kind eq 'transaction';
        $selection{drive} = $fresh->{drives}{publish} if $kind eq 'drive';
        my $before = $json->encode($fresh);
        my $context = record_context_scope(actor => $fresh, %selection);
        is($json->encode($fresh), $before, 'first complete projection preserves caller JSON kinds');
        $context->{aggregate_roots}{held}{members}{payload}{width} = 999;
        $context->{rule_declared_roots}{invented} = 1;
        $context->{namespaces}{invented} = 1;
        is($json->encode($fresh), $before, 'mutating any projection leaves source facts unchanged');
        is($context->{roots}{held}{type_spec}{members}{payload}{width}, 7,
            'traversal map is detached from value map within projection');
    }
};

subtest 'closed context selection and current source admission remain unchanged' => sub {
    refuses(sub {record_context_scope(actor => $actor, transaction => $actor->{transactions}[0],
        drive => $actor->{drives}{publish})}, qr/cannot select both transaction and drive/, 'ambiguous lexical selection');
    refuses(sub {record_context_scope(actor => $actor, extra => 1)}, qr/unknown scope argument/, 'unknown context argument');
    refuses(sub {record_reference_root_kind(context => {}, token => 'packet')},
        qr/requires declaration context/, 'missing classification maps');
    my $before = $json->encode($actor);
    ok(validate_actor_record_contexts(actor => $actor), 'existing contextual consumer uses common projection');
    is($json->encode($actor), $before, 'complete parsed source unchanged');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (data bit))))'
        . ' (interface (output packet (type frame))) (transaction main (set packet.data 1)))', 'refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer still refused');
};

done_testing;

