use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortSamples qw(record_transaction_samples record_sample_type_products);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor samples
  (types
    (type leaf (record (count (four_state (signed (bits 3)))) (ready (two_state bit))))
    (type frame (record (tag (bits 2)) (nested leaf) (lanes (list bit (bits 2)))))
    (type alias frame))
  (enums (mode (BUSY 1)))
  (interface (input start) (input mode) (output seen (width 3)) (output done))
  (storage (var packet (type frame) (reset 0)) (var held (type alias)))
  (transaction worker (ports (output packet (width 2)))
    (local count (width 3)) (set packet 1))
  (transaction main (on start) (set seen packet.nested.count) (complete done)))
ISF
my $actor = $parser->parse_source($source, 'sample-facts.isf');

sub sample_plan {
    my ($a, $clauses, $tx) = @_;
    $tx = dclone($tx || $a->{transactions}[1]);
    $tx->{clauses} = $clauses;
    return record_transaction_samples(actor => $a, transaction => $tx);
}
sub sample { ['sample', $_[0], 'as', $_[1]] }
sub refuses {
    my ($run, $pattern, $name) = @_;
    my $ok = eval {$run->(); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$name refuses");
    like($line // '', $pattern, "$name names the first-line cause");
}
sub render {
    my ($value) = @_;
    return ref($value) eq 'ARRAY' ? '(' . join(' ', map {render($_)} @$value) . ')' : $value;
}

subtest 'independent packed-layout and scalar-property witnesses' => sub {
    my $p = sample_plan($actor, [
        ['on', 'start', sample('packet.nested.count', 'count_q')],
        sample('packet.nested.ready', 'ready_q'),
        ['when', 'mode', sample('packet.lanes[1][1:0]', 'lane_q')],
        ['switch', 'mode', [1, sample('packet.tag', 'tag_q')]],
        ['repeat', 2, sample('count_q', 'again_q')],
    ]);
    is_deeply([map {[$_->{source}, $_->{alias}, $_->{record_derived}]} @{$p->{samples}}],
        [['packet.nested.count','count_q',1], ['packet.nested.ready','ready_q',1],
         ['packet.lanes[1][1:0]','lane_q',1], ['packet.tag','tag_q',1], ['count_q','again_q',1]],
        'entry/body/branches preserve authored order and chained record-leaf provenance');
    is_deeply([map {[@{$_->{reference}}{qw(width low high)}]} @{$p->{samples}}[0..3]],
        [[3,4,6], [1,3,3], [2,0,1], [2,7,8]], 'independent nine-bit packed layout');
    is_deeply($p->{bindings}{count_q}, {role=>'local', type_spec=>{kind=>'bits',width=>3,signed=>1,state_model=>'four_state'}},
        'signed four-state scalar facts survive sampling');
    is_deeply($p->{bindings}{ready_q}, {role=>'local', type_spec=>{kind=>'bit',width=>1,signed=>0,state_model=>'two_state'}},
        'bit kind and explicit two-state property survive');
    is_deeply($p->{bindings}{again_q}, $p->{bindings}{count_q}, 'explicit sampled alias has the same detached scalar type');
    ok(!exists($p->{bindings}{lane_q}{type_spec}{state_model}), 'unspecified state model stays unspecified');
};

subtest 'actual lexical masks and namespaces do not lend a record layout' => sub {
    my $p = sample_plan($actor, [['local','count',['width',3]], sample('packet[1:0]', 'p_q'), sample('count', 'c_q')], $actor->{transactions}[0]);
    is_deeply([map {$_->{reference}{width}} @{$p->{samples}}], [2,3], 'formal and explicit local widths are nearest');
    is_deeply($p->{record_aliases}, {}, 'scalar shadows do not invent record provenance');
    refuses(sub {sample_plan($actor, [sample('packet.nested.count','q')], $actor->{transactions}[0])},
        qr/member_on_non_record/, 'scalar formal member');
    my $unknown = dclone($actor->{transactions}[0]);
    $unknown->{ports}{outputs}[0] = {name=>'packet',width=>1,type=>'unresolved'};
    $p = sample_plan($actor, [sample('packet.nested.count','q')], $unknown);
    is($p->{bindings}{q}{type_spec}, undef, 'unknown formal masks outer record without placeholder inference');
    $p = sample_plan($actor, [sample('mode.BUSY','enum_q'), sample('not_declared','packet'), sample('packet.nested.count','q')]);
    is($p->{bindings}{enum_q}{type_spec}, undef, 'enum token retains existing namespace/static validation owner');
    is($p->{bindings}{q}{type_spec}, undef, 'explicit unknown sample alias masks old record facts');
};

subtest 'whole aggregates paths roles and inconsistent aliases fail precisely' => sub {
    for my $case (
        ['packet', qr/whole record/], ['packet.nested', qr/requires a scalar leaf/],
        ['packet.lanes', qr/requires a scalar leaf/], ['packet.missing', qr/unknown_member/],
        ['packet.lanes[2]', qr/index_out_of_range/],
    ) {
        refuses(sub {sample_plan($actor, [sample($case->[0],'q')])}, $case->[1], $case->[0]);
    }
    for my $alias (qw(packet held seen count)) {
        my $tx = dclone($actor->{transactions}[1]);
        unshift @{$tx->{clauses}}, ['local','count',['width',3]];
        refuses(sub {sample_plan($actor, [@{$tx->{clauses}},sample('packet.nested.count',$alias)],$tx)},
            qr/collides with a declaration/, "private alias $alias");
    }
    refuses(sub {sample_plan($actor, [sample('packet.tag','start')])}, qr/cannot write declared input/, 'input alias');
    my $prepared = dclone($actor);
    my $packet = shift @{$prepared->{storage}};
    push @{$prepared->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};
    my $read = sample_plan($prepared, [sample('packet.nested.count','q')]);
    is($read->{samples}[0]{reference}{role}, 'input', 'supplied record input retains readable declared role');
    refuses(sub {sample_plan($prepared, [sample('packet.nested.count','packet')])},
        qr/cannot write declared input/, 'supplied record input target');
    refuses(sub {sample_plan($actor, [sample('packet.tag','q'),sample('packet.nested.count','q')])},
        qr/requires the same resolved scalar type/, 'different width/type repeated sample');
    refuses(sub {sample_plan($actor, [sample('packet.nested.count','q'),sample('not_declared','q')])},
        qr/requires the same resolved scalar type/, 'unknown repeated sample');
    my $collision = dclone($actor);
    push @{$collision->{interface}{inputs}}, {name=>'scalar',width=>2};
    refuses(sub {sample_plan($collision, [sample('scalar','held'),sample('packet.tag','held')])},
        qr/collides with a declaration/, 'prior scalar sample cannot erase an authored storage collision');
    my $p = sample_plan($actor, [sample('packet.tag','q'),sample('held.tag','q')]);
    is(scalar(@{$p->{samples}}), 2, 'same resolved scalar type permits repeated explicit captures');
    refuses(sub {sample_plan($actor, [['sample','packet.tag','as',['q']]])}, qr/requires '\(sample scalar as identifier\)'/, 'malformed sample');
};

subtest 'private core scalar type products are deterministic and collision-safe' => sub {
    my $p = sample_plan($actor, [sample('packet.nested.count','count_q'),sample('packet.nested.ready','ready_q'),sample('packet.tag','tag_q')]);
    my %args = (bindings=>$p->{bindings}, record_aliases=>$p->{record_aliases}, reserved_names=>['_isf_sample_count_q','_isf_sample_count_q_1']);
    my $types = record_sample_type_products(%args);
    is_deeply($types, {
        type_declarations=>[
            ['type','_isf_sample_count_q_2',['four_state',['signed',['bits',3]]]],
            ['type','_isf_sample_ready_q',['two_state','bit']],
            ['type','_isf_sample_tag_q',['bits',2]],
        ],
        signal_type_refs=>{count_q=>'_isf_sample_count_q_2',ready_q=>'_isf_sample_ready_q',tag_q=>'_isf_sample_tag_q'},
        signal_widths=>{count_q=>3,ready_q=>1,tag_q=>2},
    }, 'independently authored complete carrier product has no reset/default leakage');
    is_deeply(record_sample_type_products(%args), $types, 'same reserved names produce the same declaration identity');
    my $declarations = join(' ', map {render($_)} @{$types->{type_declarations}});
    my $storage = join(' ', map {'(var '.$_.' (type '.$types->{signal_type_refs}{$_}.'))'} sort keys %{$types->{signal_type_refs}});
    my $a = $parser->parse_source('(actor type_contract (types '.$declarations.') (storage '.$storage.') (transaction main (wait 1)))', 'private-type-contract.isf');
    for my $entry (@{$a->{storage}}) {
        is_deeply($entry->{type_spec}, $p->{bindings}{$entry->{name}}{type_spec}, 'actual public type resolver reconstructs the exact selected scalar facts');
    }
    refuses(sub {record_sample_type_products(%args, extra=>1)}, qr/unknown sample argument/, 'unknown type-product argument');
    refuses(sub {record_sample_type_products(%args, record_aliases=>{count_q=>[]})}, qr/requires a local sample binding/, 'malformed record-alias fact');
};

subtest 'imported aliases and first-read caller facts are detached' => sub {
    my $work = tempdir(CLEANUP=>1);
    open my $f, '>', "$work/shared.fsm" or die $!;
    print {$f} '(?pkg:shared (+types (type frame (record (data (four_state (signed (bits 3))))))))';
    close $f or die $!;
    my $a = $parser->parse_source('(actor imported (imports (package shared)) (storage (var packet (type shared.frame))) (transaction main (wait 1)))', "$work/imported.isf");
    my $p = sample_plan($a, [sample('packet.data','q')], $a->{transactions}[0]);
    is_deeply($p->{bindings}{q}{type_spec}, {kind=>'bits',width=>3,signed=>1,state_model=>'four_state'}, 'actual imported leaf has exact scalar properties');
    my $fresh = dclone($actor);
    my $tx = dclone($fresh->{transactions}[1]);
    $tx->{clauses} = [sample('packet.nested.count','q')];
    my $before = $json->encode([$fresh,$tx]);
    $p = record_transaction_samples(actor=>$fresh,transaction=>$tx);
    is($json->encode([$fresh,$tx]), $before, 'first plan preserves complete copied caller JSON kinds');
    $p->{record_aliases}{q} = '1';
    $p->{bindings}{q}{type_spec}{width} = '3';
    $before = $json->encode($p);
    my $products = record_sample_type_products(bindings=>$p->{bindings},record_aliases=>$p->{record_aliases},reserved_names=>[]);
    is($json->encode($p), $before, 'first type projection preserves string-valued width and provenance facts');
    $products->{type_declarations}[0][2][1][1][1] = 999;
    is($json->encode($p), $before, 'mutating generated declaration does not mutate facts');
    $p->{samples}[0]{reference}{type_spec}{width} = 999;
    is($p->{bindings}{q}{type_spec}{width}, '3', 'sample reference and binding are detached sibling maps');
};

subtest 'preparation does not mutate complete currently admitted products' => sub {
    my $a = $parser->parse_source($source, 'sample-facts.isf');
    my $before = $json->encode($a);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower($a));
    record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[1]);
    is($json->encode($a), $before, 'complete parsed object unchanged');
    is($json->encode(FSM::Scheduler::ISF->new->lower($a)), $lowered, 'complete scheduled object and emitted bytes unchanged');
    refuses(sub {$parser->parse_source('(actor refused (types (type frame (record (data bit)))) (interface (output packet (type frame))) (transaction main (set packet.data 1)))', 'field-refused.isf')},
        qr/record output field writes are not yet admitted/, 'authored record output field writer remains refused');
};

done_testing;

sources.t/1991-isf-record-port-sample-contexts.t:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;
use FSM::Support::ISFRecordPortContexts qw(validate_actor_record_contexts);
use FSM::Support::ISFRecordPortSamples qw(actor_has_record_input record_transaction_samples);

my $parser = FSM::Adapter::ISF->new;
my $json = JSON::PP->new->canonical;
my $source = <<'ISF';
(actor contexts
  (types (type frame (record (count (four_state (signed (bits 3)))) (ready bit))))
  (interface (input start) (output seen (width 3)) (output done))
  (storage (var packet (type frame)) (var held (type frame)))
  (transaction main (on start) (set seen packet.count) (complete done)))
ISF
my $ordinary = $parser->parse_source($source, 'sample-contexts.isf');
my $prepared = dclone($ordinary);
my $packet = shift @{$prepared->{storage}};
push @{$prepared->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};

sub sample { ['sample',$_[0],'as',$_[1]] }
sub actor_with {
    my ($clauses) = @_;
    my $a = dclone($prepared);
    $a->{transactions}[0]{clauses} = $clauses;
    return $a;
}
sub accepts {
    my ($a, $label) = @_;
    my $before = $json->encode($a);
    my $ok = eval {validate_actor_record_contexts(actor=>$a); 1};
    ok($ok, $label) or diag($@);
    is($json->encode($a), $before, "$label preserves the complete actor");
}
sub refuses {
    my ($a, $pattern, $label) = @_;
    my $before = $json->encode($a);
    my $ok = eval {validate_actor_record_contexts(actor=>$a); 1};
    my ($line) = split /\n/, $@;
    ok(!$ok, "$label refuses");
    like($line // '', $pattern, "$label has the correct first-line cause");
    is($json->encode($a), $before, "$label preserves the complete actor");
}

subtest 'selector refuses malformed facts without autovivifying callers' => sub {
    my $empty = {};
    is(actor_has_record_input(actor=>$empty), 0, 'absent interface has no known record input');
    is_deeply($empty, {}, 'selection never invents an interface');
    for my $entry (undef, 'not_a_map', []) {
        my $a = {interface=>{inputs=>[$entry]}};
        my $before = $json->encode($a);
        my $ok = eval {actor_has_record_input(actor=>$a); 1};
        ok(!$ok, 'malformed declared entry refuses');
        like((split /\n/,$@)[0] // '', qr/record-input selection requires declared input maps/, 'failure names the entry shape');
        is($json->encode($a), $before, 'first selection preserves complete malformed caller JSON');
    }
    my $a = {interface=>{inputs=>[dclone($prepared->{interface}{inputs}[1]), undef]}};
    my $before = $json->encode($a);
    my $ok = eval {actor_has_record_input(actor=>$a); 1};
    ok(!$ok, 'a valid record prefix cannot hide a malformed remaining declaration');
    like((split /\n/,$@)[0], qr/record-input selection requires declared input maps/, 'complete input inventory is validated');
    is($json->encode($a), $before, 'failed suffix validation leaves the complete caller unchanged');
};

subtest 'selected explicit entry body and control samples feed real scalar bindings' => sub {
    ok(!actor_has_record_input(actor=>$ordinary), 'ordinary scalar/storage source is outside the input consumer');
    ok(actor_has_record_input(actor=>$prepared), 'actual supplied record-input role selects the consumer');
    for my $clauses (
        [['on','start',sample('packet.count','q')],['set','seen','q']],
        [sample('packet.count','q'),['update','seen','q[2:1]']],
        [['when','start',sample('packet.count','q'),['set','seen','q']]],
        [['switch','start',[1,sample('packet.count','q'),['set','seen','q']]]],
        [['while','start',sample('packet.ready','q'),['set','done','q']]],
        [['until','start',sample('packet.ready','q'),['set','done','q']]],
        [['repeat',2,sample('packet.count','q'),['drive','inline',['seen','q']]]],
        [sample('packet.count','q'),sample('q','again'),['set','seen','again']],
    ) {
        accepts(actor_with($clauses), 'selected explicit scalar sample context');
    }
};

subtest 'sample aliases cannot erase declaration roles or invalid scalar shapes' => sub {
    refuses(actor_with([sample('packet.count','q'),['set','seen','q.member']]),
        qr/member_on_non_record/, 'sample alias is a scalar rather than an inferred record');
    refuses(actor_with([sample('packet.count','q'),['set','seen','q[3]']]),
        qr/scalar_index_out_of_range/, 'sample alias has exact leaf width');
    refuses(actor_with([sample('packet','q')]), qr/whole record/, 'whole record snapshot');
    refuses(actor_with([sample('packet.count','packet')]), qr/cannot write declared input/, 'input target');
    refuses(actor_with([sample('packet.count','held')]), qr/collides with a declaration/, 'storage target');
    refuses(actor_with([sample('packet.missing','q')]), qr/unknown_member/, 'missing input member');
    refuses(actor_with([sample('packet.count','q'),sample('packet.ready','q')]),
        qr/requires the same resolved scalar type/, 'inconsistent repeated captures');
    refuses(actor_with([sample('q','earlier'),sample('packet.count','q')]),
        qr/uses record-derived alias 'q' before its declaration/, 'unresolved forward sample chain');
};

subtest 'nearest formals locals and explicit unknown aliases mask input layouts' => sub {
    my $a = actor_with([sample('packet[1:0]','q'),['set','seen','q']]);
    $a->{transactions}[0]{ports} = {inputs=>[],outputs=>[{name=>'packet',width=>2}]};
    accepts($a, 'scalar formal has its own sampled width and writable role');
    $a->{transactions}[0]{clauses} = [sample('packet.count','q')];
    refuses($a, qr/member_on_non_record/, 'scalar formal cannot borrow input layout');
    $a->{transactions}[0]{ports}{outputs}[0] = {name=>'packet',width=>1,type=>'unresolved'};
    accepts($a, 'unknown formal remains delegated');
    $a = actor_with([['local','local_word',['width',2]],sample('local_word','q'),['set','seen','q[1:0]']]);
    accepts($a, 'explicit local AST has its own sampled width');
    $a = actor_with([sample('not_declared','held'),sample('held.member','q')]);
    accepts($a, 'unknown sampled alias masks outer storage rather than borrowing its record type');
};

subtest 'port consumer delegates established packed storage and namespace samples' => sub {
    my $a = actor_with([sample('held','packed_q'),['set','held','packed_q']]);
    my $p = record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[0],port_only=>1);
    is($p->{bindings}{packed_q}{type_spec}, undef, 'packed storage width/inference remains with its existing owner');
    is_deeply($p->{record_aliases}, {}, 'storage sampling gains no new record-input type carrier');
    accepts($a, 'existing storage-only packed sample and transfer context remains delegated');
    $a->{enum_symbols}{local} = {mode=>{BUSY=>1}};
    $a->{transactions}[0]{clauses} = [sample('mode.BUSY','enum_q')];
    accepts($a, 'enum sample remains with namespace/static-value validation');
    my $before = $json->encode($a);
    my $ok = eval {record_transaction_samples(actor=>$a,transaction=>$a->{transactions}[0],port_only=>[]); 1};
    ok(!$ok, 'malformed selection refuses');
    like((split /\n/,$@)[0], qr/port-only selection must be binary/, 'closed selection diagnostic');
    is($json->encode($a), $before, 'failed selection is detached');
};

subtest 'complete ordinary products and source admission remain unchanged' => sub {
    my $a = $parser->parse_source($source, 'sample-contexts.isf');
    my $before = $json->encode($a);
    my $lowered = $json->encode(FSM::Scheduler::ISF->new->lower($a));
    accepts($a, 'currently admitted scalar/storage actor');
    is($json->encode($a), $before, 'first context consumer preserves current source facts');
    is($json->encode(FSM::Scheduler::ISF->new->lower($a)), $lowered, 'complete scheduled object and actual emitted bytes unchanged');
    my $ok = eval {$parser->parse_source('(actor refused (types (type frame (record (data bit)))) (interface (output packet (type frame))) (transaction main (sample packet as q)))', 'whole-sample-refused.isf'); 1};
    ok(!$ok, 'whole record-output inferred sample remains refused');
    like((split /\n/,$@)[0], qr/whole record/, 'whole-value sample boundary remains exact');
};

done_testing;

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable qw(dclone);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $parser = FSM::Adapter::ISF->new;
my $scheduler = FSM::Scheduler::ISF->new;
my $json = JSON::PP->new->canonical;
my $work = tempdir(CLEANUP=>1);

sub authored {
    my ($transactions, $rules) = @_;
    return $parser->parse_source(<<"ISF", 'sample-ownership.isf');
(actor sample_owners
 (types (type frame (record (data (four_state (signed (bits 3)))) (ready (two_state bit)))))
 (interface (input start) (input alternate) (input scalar (width 3))
  (output seen (width 3)) (output done))
 (storage (var packet (type frame) (reset 0)))
 (drive (publish value) (seen value))
 $transactions
 ${\($rules // '')})
ISF
}
sub prepared {
    my ($actor) = @_;
    $actor = dclone($actor);
    my $packet = shift @{$actor->{storage}};
    push @{$actor->{interface}{inputs}}, {map {$_=>$packet->{$_}} qw(name width type type_spec)};
    return $actor;
}
sub sample { ['sample',$_[0],'as',$_[1]] }
sub reject {
    my ($actor,$pattern,$label) = @_;
    my $before = $json->encode($actor);
    my $ok = eval {$scheduler->lower($actor); 1};
    my ($line) = split /\n/,$@;
    ok(!$ok, "$label refuses before emission");
    like($line // '', $pattern, "$label first diagnostic identifies ownership");
    is($json->encode($actor),$before,"$label leaves caller facts unchanged");
}
sub strict_carrier {
    my ($name,$text) = @_;
    open my $f,'>',"$work/$name" or die $!;
    print {$f} $text;
    close $f or die $!;
    open my $cli,'-|','./bin/fsmgen','--quiet','--strict','--check','--json',"$work/$name" or die $!;
    my $out = do {local $/; <$cli>};
    close $cli;
    is($? >> 8,0,"$name strictly replays");
    ok($json->decode($out)->{success},"$name replay reports success");
}

subtest 'actual drive and dynamic-counter products reserve sample identities' => sub {
    for my $case (
        ['drive_request','(drive publish scalar)','packet.ready'],
        ['drive_payload','(drive publish scalar)','packet.data'],
        ['dynamic_wait_counter','(wait scalar)','packet.data'],
    ) {
        my ($role,$operation,$source) = @$case;
        my $ordinary = authored("(transaction main (on start) $operation (complete done))");
        my $ir = $scheduler->{ir}->build_module($ordinary);
        my @helpers = sort grep {($ir->{storage_roles}{$_}//'') eq $role} keys %{$ir->{storage_roles}};
        is(scalar(@helpers),1,"ordinary production has one actual $role helper");
        next unless @helpers==1;
        my $helper = $helpers[0];
        ok(exists $ir->{counters}{$helper},"actual $role helper has a real declaration");
        my $actor = prepared($ordinary);
        push @{$actor->{transactions}[0]{clauses}[0]}, sample($source,$helper);
        reject($actor,qr/record-derived sample alias '\Q$helper\E'.*collides with a generated (?:declaration|storage role)/,
            "actual $role $helper collision");
    }
};

subtest 'actual spawn handoff ports reserve private sample identities' => sub {
    my $ordinary = authored('(transaction main (on start) (spawn worker as job) (await_all done) (complete done))
        (transaction worker (wait 1))');
    my $ir = $scheduler->{ir}->build_module($ordinary);
    for my $role (qw(activation_start_handoff activation_done_handoff)) {
        my @helpers = sort grep {($ir->{storage_roles}{$_}//'') eq $role} keys %{$ir->{storage_roles}};
        is(scalar(@helpers),1,"ordinary production has one $role declaration");
        next unless @helpers==1;
        my $helper = $helpers[0];
        ok((grep {$_->{name} eq $helper} @{$ir->{ports}}),"actual $role is a module handoff port");
        my $actor = prepared($ordinary);
        push @{$actor->{transactions}[0]{clauses}[0]},sample('packet.ready',$helper);
        reject($actor,qr/record-derived sample alias '\Q$helper\E'.*collides with (?:a module port|a generated declaration)/,
            "actual spawn $role collision");
    }
};

subtest 'private samples cannot share a transaction owner or accept other writers' => sub {
    my $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    push @{$a->{transactions}[1]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has multiple transaction owners/,'two record sample owners');
    $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    push @{$a->{transactions}[1]{clauses}[0]},sample('scalar','q');
    reject($a,qr/record-derived sample alias 'q' has multiple sample owners/,'record and ordinary sample owners');
    $a = prepared(authored('(transaction first (on start) (complete done))
        (transaction second (on alternate) (set q scalar))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has a different state writer/,'different transaction writer');
    $a = prepared(authored('(transaction first (on start) (complete done))',
        '(rule overwrite alternate (set q scalar))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    reject($a,qr/record-derived sample alias 'q' has a decision-tree writer/,'actor rule writer');
};

subtest 'repeated private captures and separate generated module owners are valid' => sub {
    my $a = prepared(authored('(transaction main (on start) (set seen scalar) (complete done))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    splice @{$a->{transactions}[0]{clauses}},1,0,sample('packet.data','q');
    my $before = $json->encode($a);
    my $result = $scheduler->lower($a);
    is($json->encode($a),$before,'repeated same-owner captures preserve caller facts');
    my $fsm = $result->{files}{'sample_owners.fsm'};
    is(scalar(()=$fsm =~ /\(type _isf_sample_q /g),1,'same-owner scalar type declared once');
    like($fsm,qr/\(internal q\)/,'unused sampled value remains private');
    unlike($fsm,qr/\((?:input|output) q\)/,'unused sample creates no authored pin');
    strict_carrier('sample_owners.fsm',$fsm);

    $a = prepared(authored('(transaction main (on start) (spawn worker as job) (await_all done) (complete done))
        (transaction worker (wait 1))'));
    push @{$a->{transactions}[0]{clauses}[0]},sample('packet.data','q');
    unshift @{$a->{transactions}[1]{clauses}},sample('packet.data','q');
    $before=$json->encode($a);
    $result=$scheduler->lower($a);
    is($json->encode($a),$before,'separate physical owners preserve caller facts');
    for my $name ('sample_owners.fsm','worker.fsm') {
        like($result->{files}{$name},qr/\(q _isf_sample_q\)/,"$name owns its own typed sample");
        strict_carrier($name,$result->{files}{$name});
    }
};

done_testing;

sources.t/1998-isf-record-input-source-admission:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $parser = FSM::Adapter::ISF->new;
my $scheduler = FSM::Scheduler::ISF->new;
my $json = JSON::PP->new->canonical;
my $work = tempdir(CLEANUP => 1);
my $header = <<'ISF';
(actor records
 (types (type frame (record (kind (bits 2))
   (payload (record (data (signed (four_state (bits 5))))
    (flags (list bit (two_state (bits 2))))))))
  (type alias frame)
  (type other (record (kind (bits 2))
   (payload (record (data (four_state (bits 5))) (flags (list bit (two_state (bits 2)))))))))
 (enums (packet (OTHER 1)) (mode (ON 1)))
 (interface (input start) (input scalar (width 5)) (input mode)
  (input packet (type frame)) (output seen (width 5)) (output sliced (width 3)) (output tag (width 2)) (output done))
 (storage (var held (type alias)) (var mismatch (type other)))
ISF
my $fields = [
    {path => 'kind', width => 2, lsb => 8, msb => 9, signed => 0},
    {path => 'payload.data', width => 5, lsb => 3, msb => 7, signed => 1, state_model => 'four_state'},
    {path => 'payload.flags[0]', width => 1, lsb => 2, msb => 2, signed => 0},
    {path => 'payload.flags[1]', width => 2, lsb => 0, msb => 1, signed => 0, state_model => 'two_state'},
];
sub write_file {
    my ($path, $text) = @_;
    open my $file, '>', $path or die $!;
    print {$file} $text;
    close $file or die $!;
}
sub source { return $header . $_[0] . ')'; }
sub qualify {
    my ($name, $text, $type) = @_;
    my $path = "$work/$name.isf";
    write_file($path, $text);
    my $actor;
    my $ok = eval { $actor = $parser->parse_source($text, $path); 1 };
    my ($error) = split /\n/, $@;
    ok($ok, "$name actual authored source parses") or diag($error // '');
    return unless $ok;
    my $before = $json->encode($actor);
    my ($port) = grep { $_->{name} eq 'packet' } @{$actor->{interface_port_metadata}};
    is_deeply($port, {name => 'packet', direction => 'input', width => 10,
        type => $type, type_kind => 'record', fields => $fields}, "$name complete independently expected input declaration");
    my $result;
    $ok = eval { $result = $scheduler->lower($actor); 1 };
    ($error) = split /\n/, $@;
    ok($ok, "$name actual authored source lowers") or diag($error // '');
    is($json->encode($actor), $before, "$name complete caller JSON stays unchanged");
    return unless $ok;
    my $report = $json->decode($scheduler->report($actor));
    is_deeply([grep {$_->{name} eq 'packet'} @{$report->{interface_ports}}], [$port], "$name actual schedule retains exact record declaration");
    my $dir = "$work/$name";
    mkdir $dir or die $!;
    write_file("$dir/$_", $result->{files}{$_}) for sort keys %{$result->{files}};
    for my $file (sort keys %{$result->{files}}) {
        my $fsm = $result->{files}{$file};
        open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', "$dir/$file" or die $!;
        my $output = do {local $/; <$native>};
        close $native;
        my $exit = $? >> 8;
        is($exit, 0, "$name actual $file strictly replays") or diag($output);
        ok($json->decode($output)->{success}, "$name $file reports strict success");
        like($fsm, qr/\(packet \Q$type\E\)/, "$name typed record input reuses the authored alias")
            if $file eq 'records.fsm';
    }
    # Check the authored source too; carrier success alone cannot prove ingress.
    open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', $path or die $!;
    my $output = do {local $/; <$native>};
    close $native;
    is($? >> 8, 0, "$name original authored source succeeds natively") or diag($output);
    my $native_report = $json->decode($output);
    ok($native_report->{success}, "$name native source reports complete success");
    is_deeply([grep {$_->{name} eq 'packet'} @{$native_report->{source}{interface_ports}}], [$port],
        "$name native source retains independently expected full metadata");
}
sub refuses {
    my ($text, $pattern, $label) = @_;
    my $ok = eval {
        my $actor = $parser->parse_source($text, 'record-input-negative.isf');
        $scheduler->lower($actor);
        1;
    };
    my ($error) = split /\n/, $@;
    ok(!$ok, "$label refuses before successful lowering");
    like($error // '', $pattern, "$label names the first contextual cause");
}

subtest 'authored local record input contexts use exact packed facts' => sub {
    qualify('copy', source('(transaction main (on start) (set held packet) (set seen packet.payload.data) (complete done))'), 'frame');
    qualify('leaves', source('(transaction main (on start) (when mode.ON (set sliced packet.payload.data[3:1]))'
        . ' (when packet.payload.flags[1] (update tag packet.kind)) (complete done))'), 'frame');
    qualify('sample', source('(transaction main (on start (sample packet.payload.data as held_leaf))'
        . ' (set seen held_leaf) (complete done))'), 'frame');
    qualify('rule', source('(rule observe packet.payload.flags[0] (seen packet.payload.data))'), 'frame');
    qualify('drive', source('(drive publish (seen packet.payload.data))'
        . ' (transaction main (on start) (drive publish) (complete done))'), 'frame');
    qualify('generated', source('(transaction worker (ports (output result (width 5))) (set result packet.payload.data) (complete done))'
        . ' (transaction main (on start) (spawn worker as job (bind (output result seen))) (await_all done) (complete done))'), 'frame');
    qualify('unused', source('(transaction main (on start) (set seen scalar) (complete done))'), 'frame');
};

subtest 'actual imported aliases preserve the same resolved identity' => sub {
    write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame (record (kind (bits 2))'
        . ' (payload (record (data (signed (four_state (bits 5)))) (flags (list bit (two_state (bits 2))))))))))');
    my $text = $header;
    my $start = index($text, ' (types');
    my $end = index($text, ' (enums');
    substr($text, $start, $end - $start, ' (imports (package shared))' . "\n");
    $text =~ s/\(type (?:frame|alias|other)\)/(type shared.frame)/g;
    qualify('imported', $text . '(transaction main (on start) (set held packet) (set seen packet.payload.data) (complete done)))', 'shared.frame');
};

subtest 'first authored source admission has every mandatory negative gate' => sub {
    for my $case (
        ['unknown member', '(set seen packet.missing)', qr/unknown_member/],
        ['out of range', '(set seen packet.payload.flags[1][2])', qr/scalar_index_out_of_range/],
        ['subaggregate scalar', '(set seen packet.payload)', qr/requires a scalar leaf.*resolves to record/],
        ['input field target', '(set packet.payload.data 1)', qr/cannot write declared input/],
        ['input whole target', '(set packet held)', qr/cannot write declared input/],
        ['equal width mismatch', '(set mismatch packet)', qr/requires the same resolved record type/],
        ['whole to scalar', '(set seen packet)', qr/whole record port copy requires declared record roots/],
        ['whole arithmetic', '(set seen (+ packet 1))', qr/requires a scalar value.*whole record port/],
        ['whole condition', '(when packet (set seen 1))', qr/requires a scalar value.*whole record port/],
        ['member operator', '(set seen (packet.payload.data 1))', qr/operator cannot use declared aggregate reference/],
        ['whole sample', '(sample packet as q)', qr/scalar.*whole record|whole record.*scalar/],
        ['input alias', '(sample scalar as packet)', qr/cannot write declared input/],
        ['unsupported trigger', '(await packet.payload.flags[0])', qr/does not admit record port reference/],
    ) {
        refuses(source('(transaction main (on start) ' . $case->[1] . ')'), $case->[2], $case->[0]);
    }
    my $foreign = $header;
    $foreign =~ s/\(actor records/\(actor records (clock-domains (domain core (clock clk) :default) (domain aux (clock aux_clk)))/;
    $foreign =~ s/\(input packet \(type frame\)\)/\(input packet (type frame) (domain aux)\)/;
    refuses($foreign . '(transaction main (on start) (set seen packet.payload.data)))',
        qr/clock-domain violation: .* read signal 'packet.payload.data' owned by domain 'aux' from domain 'core'/,
        'authored foreign record leaf');
};

subtest 'unbound generated outputs remain closed for record and ordinary sources' => sub {
    my $unbound = source('(transaction worker (set seen packet.payload.data) (complete done))'
        . ' (transaction main (on start) (spawn worker as job) (await_all done) (complete done))');
    my $ordinary = $unbound;
    $ordinary =~ s/\(input packet \(type frame\)\)/(input packet (width 10))/;
    $ordinary =~ s/packet\.payload\.data/scalar/g;
    for my $case (['record', $unbound], ['ordinary', $ordinary]) {
        my $path = "$work/unbound-$case->[0].isf";
        write_file($path, $case->[1]);
        open my $native, '-|', './bin/fsmgen', '--quiet', '--strict', '--check', '--json', $path or die $!;
        my $output = do {local $/; <$native>};
        close $native;
        is($? >> 8, 1, "$case->[0] unbound generated output refuses natively");
        my $report = $json->decode($output);
        ok(!$report->{success}, "$case->[0] unbound output cannot report source success");
        ok(!$report->{generated_output}{emitted}, "$case->[0] unbound output emits no HDL");
        like($report->{diagnostics}[0]{message}, qr/leaves child port 'job.seen' unconnected/,
            "$case->[0] first native diagnostic retains existing explicit child binding contract");
    }
};

subtest 'unqualified aggregate carriers and unknown aliases stay closed' => sub {
    for my $case (
        ['output field', '(actor refused (types (type frame (record (flag bit)))) (interface (output packet (type frame))) (transaction main (set packet.flag 1)))', qr/record output field writes are not yet admitted/],
        ['root list', '(actor refused (types (type lanes (list bit bit))) (interface (input packet (type lanes))))', qr/interface port 'packet' references aggregate type/],
        ['transaction', '(actor refused (types (type frame (record (flag bit)))) (transaction main (ports (input packet (type frame)))))', qr/transaction 'main' port 'packet' references aggregate type/],
        ['unknown alias', '(actor refused (interface (input packet (type missing))))', qr/interface port 'packet' references unknown type 'missing'/],
        ['width and type', '(actor refused (interface (input packet (type missing) (width 8))))', qr/cannot specify both/],
    ) {
        refuses($case->[1], $case->[2], $case->[0]);
    }
};

done_testing;

sources.t/2021-isf-record-input-generated-refusa:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Digest::SHA qw(sha256_hex);
use Cwd qw(abs_path);
use File::Spec;
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner qw(normalize_repository_paths);
use FSM::Support::SemanticIntrospectionMCPAdapter;
use FSM::Adapter::ISF;
use FSM::Scheduler::ISF;

my $root = abs_path('.');
my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical;
my $api = FSM::Support::SemanticIntrospectionMCPAdapter->new(repo_root => $root, workspace_root => $root);
my %flags = (check => [qw(--strict --check --json)], semantic => [qw(--strict --emit-semantic-json)],
    schedule => ['--emit-schedule-json']);
my %tools = (check => 'fsmgen_check', semantic => 'fsmgen_semantic_introspect', schedule => 'fsmgen_schedule_preview');
my $definition = '(record (kind (bits 2)) (payload (record (data (signed (four_state (bits 5))))'
    . ' (flags (list bit (two_state (bits 2)))))))';
write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame ' . $definition . ')))');
my $package_before = sha256_hex(read_file("$work/shared.fsm"));
my @producers = qw(bin/fsmgen bin/fsmgen-mcp perl/FSM/Support/SemanticIntrospectionMCPAdapter.pm
    perl/FSM/Support/ISFRecordPortContexts.pm perl/FSM/Support/ISFRecordPortScopes.pm
    perl/FSM/Scheduler/ISF/ChildStorageOwnership.pm);
my $producer_before = {map {$_ => sha256_hex(read_file($_))} @producers};

sub source {
    my ($body, %args) = @_;
    my $types = $args{imported} ? '(imports (package shared)) (types (type frame shared.frame))'
        : '(types (type frame ' . $definition . '))';
    my $domain = $args{foreign} ? 'aux' : 'core';
    my $width = $args{width} // 5;
    return '(actor contextual_records (clock-domains (domain core (clock clk) (reset (rst_n async active_low)) :default)'
        . ' (domain aux (clock aux_clk))) ' . $types
        . ' (enums (packet (OTHER 1)) (mode (ON 1)))'
        . ' (interface (input start) (input scalar (width 5)) (input mode (domain aux))'
        . " (input packet (type frame) (domain $domain)) (output seen (width $width)) (output whole (width 5)) (output flag) (output done))"
        . ' (storage (var held (type frame) (reset 5))) ' . $body . ')';
}
sub parent {return '(transaction main (domain core) (on start) ' . $_[0] . ' (complete done))'}
sub child {
    return '(transaction worker (domain core) (ports (output result (width ' . ($_[1] // 5) . '))) '
        . $_[0] . ' (complete done))'
        . ' (transaction main (domain core) (on start) (spawn worker as job (bind (output result seen)))'
        . ' (await_all done) (complete done))';
}

subtest 'actual parent and generated foreign paths retain the declared root owner' => sub {
    for my $path (
        ['nested', 'packet.payload.data', 5], ['slice', 'packet.payload.data[3:0]', 4],
        ['reverse', 'packet.payload.data[0:3]', 4], ['single', 'packet.payload.data[4:4]', 1],
        ['list', 'packet.payload.flags[0]', 1], ['list_slice', 'packet.payload.flags[1][1:0]', 2],
    ) {
        my ($name, $token, $width) = @$path;
        for my $generated (0, 1) {
            my $owner = $generated ? 'worker' : 'main';
            my $body = $generated ? child("(set result $token)", $width) : parent("(set seen $token)");
            refuses("foreign_${name}_$owner", source($body, foreign => 1, width => $width, imported => $generated),
                qr/clock-domain violation: transaction '\Q$owner\E' set clause read signal '\Q$token\E' owned by domain 'aux' from domain 'core' without a crossing primitive/);
        }
    }
    for my $generated (0, 1) {
        my $owner = $generated ? 'worker' : 'main';
        my $body = $generated ? child('(set held packet) (set result 0)') : parent('(set held packet)');
        refuses("foreign_copy_$owner", source($body, foreign => 1, imported => $generated),
            qr/clock-domain violation: transaction '\Q$owner\E' set clause read signal 'packet' owned by domain 'aux' from domain 'core'/);
    }
};

subtest 'authored domain control sample rule and drive contexts retain foreign ownership' => sub {
    for my $case (
        ['condition', parent('(when packet.payload.data (set seen 1))'), qr/transaction 'main'.*read signal/],
        ['body_sample', parent('(sample packet.payload.data as q) (set seen q)'), qr/transaction 'main' sample clause read signal/],
        ['entry_sample', '(transaction main (domain core) (on start (sample packet.payload.data as q))'
            . ' (set seen q) (complete done))', qr/transaction 'main' sample clause read signal/],
        ['rule', '(rule observe (domain core) 1 (seen packet.payload.data))', qr/rule 'observe'.*read signal/],
        ['inline_drive', parent('(drive (seen packet.payload.data))'), qr/transaction 'main'.*read signal/],
        ['named_drive', '(drive publish (seen packet.payload.data)) ' . parent('(drive publish)'), qr/drive 'publish' assignment read signal/],
    ) {
        refuses("foreign_$case->[0]", source($case->[1], foreign => 1, imported => 1),
            qr/clock-domain violation: $case->[2] 'packet.payload.data' owned by domain 'aux' from domain 'core'/);
    }
};

subtest 'domain and generated input roots and members remain read-only' => sub {
    for my $generated (0, 1) {
        for my $target ('packet', 'packet.payload.data') {
            my $rhs = $target eq 'packet' ? 'held' : '1';
            my $body = $generated ? child("(set $target $rhs) (set result 0)") : parent("(set $target $rhs)");
            refuses(($generated ? 'child' : 'parent') . ($target eq 'packet' ? '_input_root' : '_input_member'),
                source($body, imported => $generated), qr/cannot write declared input '\Q$target\E'/);
        }
    }
};

subtest 'nearest scalar declarations cannot borrow foreign record members' => sub {
    for my $token ('packet.payload.data', 'packet[0].payload.data', 'packet[0:0].payload.data') {
        (my $suffix = $token) =~ s/\W/_/g;
        my $formal = '(transaction worker (domain core) (ports (input packet (width 3)) (output result (width 5)))'
            . " (set result $token) (complete done))"
            . ' (transaction main (domain core) (on start) (spawn worker as job'
            . ' (bind (input packet scalar[2:0]) (output result seen))) (await_all done) (complete done))';
        refuses("formal_$suffix", source($formal, foreign => 1, imported => 1), qr/member_on_non_record/);
        my $drive = "(drive (publish packet) (seen $token)) " . child('(drive publish start) (set result 0)');
        refuses("drive_$suffix", source($drive, foreign => 1), qr/member_on_non_record/);
    }
    refuses('local_member', source(child('(local packet (width 3)) (set result packet.payload.data)'), foreign => 1),
        qr/member_on_non_record/);
    refuses('local_pin_collision', source(parent('(local packet (width 3)) (set seen packet[0])'), width => 1),
        qr/\(local packet \.\.\.\).*collides with interface port 'packet'/);
};

subtest 'explicit binding and sole whole writer boundaries remain closed' => sub {
    my $writer = '(transaction worker (domain core) (set held packet) (complete done))';
    my $spawn = '(transaction main (domain core) (on start) (spawn worker as job) (await_all done) (complete done))';
    refuses('parent_and_child_writer', source($writer . $spawn . ' (rule competing (domain core) start (held packet))', imported => 1),
        qr/parent writer and generated child writer/);
    (my $two = $spawn) =~ s/\(await_all done\)/(spawn worker as peer) (await_all done)/;
    refuses('competing_child_writers', source($writer . $two), qr/competing generated child writers/);
    (my $partial = $writer) =~ s/\(set held packet\)/(set held.payload.data packet.payload.data)/;
    refuses('unqualified_child_member_writer', source($partial . $spawn, imported => 1),
        qr/only full-width variable sequential writes are qualified/);
    my $unbound = '(transaction worker (domain core) (set seen packet.payload.data) (complete done))' . $spawn;
    refuses('unbound_child_output', source($unbound), qr/leaves child port 'core__job.seen' unconnected/, 1);
    refuses('aggregate_child_formal', source('(transaction worker (domain core) (ports (input payload (type frame))))'),
        qr/transaction 'worker' port 'payload' references aggregate type/);
};

subtest 'activation binding values do not inherit record leaf-read permission' => sub {
    for my $site (qw(spawn local_do generated_do local_trigger generated_trigger)) {
        my $generated = $site =~ /generated/;
        my $rule = $site =~ /trigger/;
        my $local_rule = $site eq 'local_trigger';
        my $params = $generated ? '(params (LAT 1))' : '';
        my $ports = '(ports (input payload (width 5))' . ($local_rule ? '' : ' (output result (width 5))') . ')';
        my $worker = "(transaction worker (domain core) $params $ports (set "
            . ($local_rule ? 'seen' : 'result') . ' payload) (complete done))';
        my $bindings = '(bind (input payload (+ packet.payload.data 0))'
            . ($local_rule ? '' : ' (output result seen)') . ')';
        my $caller = $rule ? "(rule launch (domain core) start (trigger worker $params $bindings))"
            : parent($site eq 'spawn' ? "(spawn worker as job $bindings) (await_all done)"
                : "(do worker $params $bindings)");
        refuses("record_actual_$site", source($worker . $caller, imported => 1),
            qr/Invalid ISF record context: (?:transaction 'main' (?:spawn|do) clause|rule 'launch' trigger) does not admit record port reference 'packet.payload.data'/);
    }
};

subtest 'admitted scalar formal and drive slices retain exact local physical identities' => sub {
    my $formal = '(transaction main (domain core) (ports (input packet (width 3))) (on start)'
        . ' (set seen packet[2:0]) (complete done))';
    accepts('formal_slice', source($formal, foreign => 1, width => 3, imported => 1),
        qr/isf_port_main_packet\[2:0\]/, 3, 3);
    my $generated = '(transaction worker (domain core) (ports (input packet (width 5)) (output result (width 5)))'
        . ' (set result packet[4:0]) (complete done))'
        . ' (transaction main (domain core) (on start) (spawn worker as job'
        . ' (bind (input packet scalar) (output result seen))) (await_all done) (complete done))';
    accepts('generated_formal_slice', source($generated, foreign => 1, imported => 1),
        qr/\(job_packet 5\)/, undef, 5, 1);
    my $drive = '(drive (publish packet) (whole packet) (seen packet[3:0])) ' . parent('(drive publish scalar)');
    accepts('drive_slice', source($drive, foreign => 1, width => 4), qr/seen>\s+publish_packet\[3:0\]/, undef, 4);
    my $local = parent('(local count (width 3) (default 2)) (set count scalar[2:0]) (set seen count)');
    accepts('local_scalar', source($local, foreign => 1, width => 3), qr/\(count 3\)/, undef, 3);
    my $namespace = parent('(when mode.ON (set seen scalar))');
    accepts('foreign_scalar_namespace', source($namespace, foreign => 1, imported => 1), qr/mode\.ON/, undef, 5);

};

same({map {$_ => sha256_hex(read_file($_))} @producers}, $producer_before,
    'all actual public qualifications preserve exact named producer bytes');
done_testing;

sub refuses {
    my ($name, $text, $cause, $preview) = @_;
    my $path = fixture($name, $text);
    for my $kind (qw(check semantic)) {
        my $native = capture([$^X, 'bin/fsmgen', @{$flags{$kind}}, $path]);
        is($native->{exit_code}, 1, "$name $kind native refusal") or diag($native->{stdout} . $native->{stderr});
        is($native->{stderr}, '', "$name $kind clean machine-report stderr");
        my $report = eval {$json->decode($native->{stdout})};
        ok(ref($report) eq 'HASH', "$name $kind complete failure JSON") or diag($native->{stdout});
        next unless ref($report) eq 'HASH';
        $report = normalize_repository_paths($report, $root);
        ok(!$report->{success}, "$name $kind explicit failure");
        like(first_cause($report->{diagnostics}[0]{message} // ''), $cause, "$name $kind independent first cause");
        ok(exists($report->{diagnostics}[0]{code}), "$name $kind nullable diagnostic code retained");
        is($report->{source}{input}, $path, "$name $kind exact source provenance");
        ok(!exists($report->{source}{interface_ports}), "$name $kind no successful declaration snapshot");
        ok(!defined($report->{semantic}), "$name $kind no partial semantic success");
        ok(!$report->{generated_output}{emitted}, "$name $kind no emitted HDL");
        my $request = request($path, $kind);
        my $response = $api->handle_jsonrpc_request($request);
        ok(!$response->{error} && $response->{result}{isError}, "$name $kind API compiler-failure envelope")
            or diag($json->encode($response));
        next if $response->{error};
        same($response->{result}{structuredContent}{report}, $report, "$name $kind complete typed native/API failure equality");
        same($json->decode($response->{result}{content}[0]{text}), $response->{result}{structuredContent},
            "$name $kind complete text/structured failure equality");
        wire_equal($request, $response, "$name $kind");
    }
    if ($preview) {
        my $native = capture([$^X, 'bin/fsmgen', @{$flags{schedule}}, $path]);
        is($native->{exit_code}, 0, "$name existing pre-HDL schedule preview succeeds");
        is($native->{stderr}, '', "$name schedule preview stderr is clean");
        my $report = $json->decode($native->{stdout});
        $report = normalize_repository_paths($report, $root);
        is($report->{scheduled_fsm}, 'contextual_records_top.fsm', 'preview retains the intended top carrier');
        same($report->{clock_domains}[0]{child_instances},
            [{child => 'worker', instance => 'job', kind => 'spawn', owner => 'main'}],
            'preview retains the exact planned child identity without claiming C2 qualification');
        same($report->{compile_issues}, [], 'preview reports scheduler issues only, before later C2 validation');
        my $request = request($path, 'schedule');
        my $response = $api->handle_jsonrpc_request($request);
        ok(!$response->{error} && !$response->{result}{isError}, "$name schedule API retains its preview contract");
        same($response->{result}{structuredContent}{report}, $report, "$name entire typed native/API preview equality");
        same($json->decode($response->{result}{content}[0]{text}), $response->{result}{structuredContent},
            "$name complete preview text/structured equality");
        wire_equal($request, $response, "$name schedule preview");
    } else {
        my $native = capture([$^X, 'bin/fsmgen', @{$flags{schedule}}, $path]);
        isnt($native->{exit_code}, 0, "$name native schedule refusal") or diag($native->{stdout} . $native->{stderr});
        is($native->{stdout}, '', "$name no partial schedule JSON");
        like(first_cause($native->{stderr}), $cause, "$name schedule independent first cause");
        my $request = request($path, 'schedule');
        my $response = $api->handle_jsonrpc_request($request);
        same($response, {jsonrpc => '2.0', id => 1, error => {code => -32000,
            message => 'FSMGen command failed without a matching public failure report'}},
            "$name exact message-only schedule error with no result or data");
        wire_equal($request, $response, "$name schedule");
    }
    unchanged($path, $text, $name);
}

sub accepts {
    my ($name, $text, $identity, $formal_width, $seen_width, $generated) = @_;
    my $path = fixture($name, $text);
    my $actor = FSM::Adapter::ISF->new->parse_file($path);
    my $before = $json->encode($actor);
    my $expected_ports = [
        {name => 'start', direction => 'input', width => 1, domain => 'core'},
        {name => 'scalar', direction => 'input', width => 5, domain => 'core'},
        {name => 'mode', direction => 'input', width => 1, domain => 'aux'},
        {name => 'packet', direction => 'input', width => 10, domain => 'aux', type => 'frame', type_kind => 'record', fields => [
            {path => 'kind', width => 2, lsb => 8, msb => 9, signed => 0},
            {path => 'payload.data', width => 5, lsb => 3, msb => 7, signed => 1, state_model => 'four_state'},
            {path => 'payload.flags[0]', width => 1, lsb => 2, msb => 2, signed => 0},
            {path => 'payload.flags[1]', width => 2, lsb => 0, msb => 1, signed => 0, state_model => 'two_state'}]},
        {name => 'seen', direction => 'output', width => $seen_width, domain => 'core'},
        {name => 'whole', direction => 'output', width => 5, domain => 'core'},
        {name => 'flag', direction => 'output', width => 1, domain => 'core'},
        {name => 'done', direction => 'output', width => 1, domain => 'core'}];
    same($actor->{interface_port_metadata}, $expected_ports, "$name entire independently authored declaration/layout");
    my $product = FSM::Scheduler::ISF->new->lower($actor);
    is($json->encode($actor), $before, "$name complete caller facts unchanged");
    my $owner = $product->{files}{'contextual_records__domain_core.fsm'};
    like($owner, $identity, "$name literal physical scalar identity");
    unlike($owner, qr/\(packet frame\)/, "$name core does not inherit foreign record facts");
    like($product->{files}{'contextual_records__domain_aux.fsm'}, qr/\(packet frame\)/,
        "$name foreign record declaration remains only in aux");
    like($owner, qr/\(isf_port_main_packet \Q$formal_width\E\)/, "$name scalar formal width stays independent")
        if defined $formal_width;
    if ($generated) {
        my $child = $product->{files}{'contextual_records__domain_core__child_worker.fsm'};
        like($child, qr/\(input packet\)/, 'generated child retains its authored scalar public input');
        like($child, qr/\(packet 5\)/, 'generated input keeps its independently declared scalar width');
        like($child, qr/\(<- \(result> packet\[4:0\]\)\)/, 'generated assignment uses its own scalar input selector');
        unlike($child, qr/\(packet frame\)/, 'generated child borrows no actor record type');
        like($owner, qr/\(= \(job_packet> scalar\)\)/, 'caller explicitly feeds only the scalar handoff');
        like($product->{files}{'contextual_records_top.fsm'}, qr/\(core\.job_packet core__job\.packet\)/,
            'actual top connects the private caller handoff to the published child formal');
    }
    my $dir = "$work/$name";
    mkdir $dir or die $!;
    for my $file (sort keys %{$product->{files}}) {
        write_file("$dir/$file", $product->{files}{$file});
        my $checked = capture([$^X, 'bin/fsmgen', '--strict', '--check', '--json', "$dir/$file"]);
        is($checked->{exit_code}, 0, "$name actual $file strict replay") or diag($checked->{stdout} . $checked->{stderr});
    }
    for my $kind (qw(check semantic schedule)) {
        my $native = capture([$^X, 'bin/fsmgen', @{$flags{$kind}}, $path]);
        is($native->{exit_code}, 0, "$name $kind actual native success") or diag($native->{stdout} . $native->{stderr});
        is($native->{stderr}, '', "$name $kind clean machine-report stderr");
        my $report = eval {$json->decode($native->{stdout})};
        ok(ref($report) eq 'HASH', "$name $kind complete success JSON") or diag($native->{stdout});
        next unless ref($report) eq 'HASH';
        $report = normalize_repository_paths($report, $root);
        ok($report->{success}, "$name $kind explicit success") unless $kind eq 'schedule';
        my $ports = $kind eq 'schedule' ? $report->{interface_ports} : $report->{source}{interface_ports};
        same($ports, $expected_ports, "$name $kind entire independently authored interface snapshot");
        my $response = $api->handle_jsonrpc_request(request($path, $kind));
        ok(!$response->{error} && !$response->{result}{isError}, "$name $kind API success") or diag($json->encode($response));
        next if $response->{error};
        same($response->{result}{structuredContent}{report}, $report, "$name $kind complete typed native/API success equality");
        same($json->decode($response->{result}{content}[0]{text}), $response->{result}{structuredContent},
            "$name $kind complete text/structured success equality");
        wire_equal(request($path, $kind), $response, "$name $kind");
        if ($generated && $kind eq 'semantic') {
            my $children = $report->{semantic}{forward_ir}{intent_hir}{composition_children};
            my @child = grep {$_->{instance_name} eq 'core__job'} @$children;
            is(scalar @child, 1, 'complete semantic product contains exactly the intended generated instance');
            my $expected = {name => 'packet', direction => 'input', width => 5, signed => 0};
            same([grep {$_->{name} eq 'packet'} @{$child[0]{intent_hir}{signal_analysis}{inputs}}], [$expected],
                'entire independently expected generated HIR input has scalar identity');
            same([grep {$_->{name} eq 'packet'} @{$child[0]{structural_rtl_ir}{ports}}], [{%$expected, type => 'wire'}],
                'entire independently expected generated structural input has scalar identity');
        }
    }
    unchanged($path, $text, $name);
}

sub fixture {my $path = "$work/$_[0].isf"; write_file($path, $_[1]); return File::Spec->abs2rel($path, $root)}
sub unchanged {
    is(read_file($_[0]), $_[1], "$_[2] exact source bytes retained");
    is(sha256_hex(read_file("$work/shared.fsm")), $package_before, "$_[2] exact imported package bytes retained");
}
sub first_cause {
    my @lines = split /\n/, $_[0];
    shift @lines while @lines && $lines[0] =~ /\A(?:Source file|Parent composition source|Expected child source file|Search roots|Searched locations|Generated child source):/;
    return $lines[0] // '';
}
sub request {return {jsonrpc => '2.0', id => 1, method => 'tools/call',
    params => {name => $tools{$_[1]}, arguments => {source_id => $_[0]}}}}
sub same {is($json->encode($_[0]), $json->encode($_[1]), $_[2])}
sub capture {return FSM::Test::SourceQueryRunner::_capture($_[0], $_[1] // '')}
sub wire_equal {
    my ($request, $response, $name) = @_;
    my $wire = capture([$^X, 'bin/fsmgen-mcp', '--workspace-root', '.'], $json->encode($request) . "\n");
    is($wire->{exit_code}, 0, "$name actual newline transport succeeds");
    is($wire->{stderr}, '', "$name actual newline stderr is clean");
    like($wire->{stdout}, qr/\A[^\n]+\n\z/, "$name exactly one compact newline response");
    my $decoded = eval {$json->decode($wire->{stdout})};
    ok(ref($decoded) eq 'HASH', "$name newline response is complete JSON") or diag($wire->{stdout});
    same($decoded, $response, "$name entire typed API/newline equality") if ref($decoded) eq 'HASH';
}
sub read_file {open my $file, '<:raw', $_[0] or die $!; local $/; return <$file>}
sub write_file {open my $file, '>:raw', $_[0] or die $!; print {$file} $_[1] or die $!; close $file or die $!}

sources.t/2027-isf-record-input-backend-profiles:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Pipeline::HDLGenerator;

my $work = tempdir(CLEANUP => 1);
my $direct_prefix = '[VHDL.pm][direct scaffold] Unsupported generated SystemVerilog shape for direct VHDL backend: ';
my $mixed_member = qr/^Error generating HDL: \Q$direct_prefix\Eunsupported packed struct member 'logic signed \[4:0\] data; struct packed \{ bit item_0; '/;
my $record_input = qr/^Error generating HDL: \Q$direct_prefix\Eunsupported generated port declaration 'input fsmgen_m[1-9][0-9]*_link_rx_lmp_t_fsmgen_t lmp_in'/;
my @refusals = (
    ['t/data/isf_record_input_runtime.isf', $mixed_member],
    ['t/data/isf_record_input_generated_domains_runtime.isf', composition_reason('packed_input_generated_domains_top')],
    ['t/data/isf_record_input_generated_blocking_runtime.isf', composition_reason('packed_input_generated_blocking_top')],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port.isf', $record_input],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port-field-guard.isf', $record_input],
);
my @controls = (
    ['docs/audits/specforge-aggregate-intake-20260930/baseline-good.isf',
        qr/entity link_rx is/, qr/subtype_in\s+:\s+in std_logic_vector\(3 downto 0\)/],
    ['t/corpus/direct_aggregate_constant_target_autogrowth.fsm',
        qr/entity direct_aggregate_constant_target_autogrowth is/,
        qr/OUT_FRAME\s+:\s+out std_logic_vector\(4 downto 0\)/],
);
my @paths = (map {$_->[0]} @refusals, @controls);
push @paths, qw(bin/fsmgen perl/FSM/Pipeline/HDLGenerator.pm
    perl/FSM/HDL/FlattenedDT/Backend/VHDL.pm
    perl/FSM/Backend/VHDL/StructuralRTLIREmitter.pm
    perl/FSM/Composition/PlanBuilder.pm
    perl/FSM/Adapter/ISF/Parser.pm perl/FSM/Scheduler/ISF/LoweringIR.pm
    perl/FSM/Support/ISFPublicInterfaceContract.pm);
my $before = {map {$_ => sha256_hex(read_file($_))} @paths};
my @observed;

for my $i (0..$#refusals) {
    my ($source,$reason) = @{$refusals[$i]};
    subtest "VHDL profile refuses $source before publication" => sub {
        my $existing = "$work/existing_$i.vhd";
        write_file($existing, "EXISTING DESTINATION\n");
        my $native = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl',
            '--output',$existing,$source]);
        ok(refused($native,$reason),'native exit, signal and first diagnostic establish exact refusal')
            or diag($native->{stdout},$native->{stderr});
        is(read_file($existing),"EXISTING DESTINATION\n",'existing destination remains byte-exact');
        unlike($native->{stdout},qr/\b(?:entity|architecture|module|typedef)\b/,
            'native failure publishes no HDL payload');
        my $missing = "$work/missing_$i.vhd";
        my $absent = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl',
            '--output',$missing,$source]);
        ok(refused($absent,$reason),'same profile refuses absent destination') or diag($absent->{stderr});
        ok(!-e $missing,'failure creates no destination');
        my ($product,$error);
        eval {$product=FSM::Pipeline::HDLGenerator->new(debug_level=>0,target_language=>'vhdl',quiet=>1)
            ->generate_hdl_from_file($source);1} or $error=$@;
        ok(!defined($product),'public pipeline returns no partial successful product');
        like(primary_diagnostic($error // ''),$reason,'public pipeline retains the same precise primary reason');
        push @observed, [$native,$reason];
    };
}

for my $i (0..$#controls) {
    my ($source,$entity,$port) = @{$controls[$i]};
    subtest "supported VHDL control $source remains admitted" => sub {
        my $output = "$work/control_$i.vhd";
        my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','vhdl','--output',$output,$source]);
        is($native->{exit_code},0,'native control emits successfully') or diag($native->{stderr});
        is($native->{signal},0,'native control ends normally');
        is($native->{stderr},'','native control stderr is clean');
        my $text=read_file($output);
        like($text,$entity,'independently named entity emitted');
        like($text,$port,'independently sized scalar or packed-vector declaration emitted');
        unlike($text,qr/\b(?:module|typedef|always_ff|always_comb)\b/,'control emits VHDL scaffold syntax');
        my $product=FSM::Pipeline::HDLGenerator->new(debug_level=>0,target_language=>'vhdl',quiet=>1)
            ->generate_hdl_from_file($source);
        like($product->{hdl_code},$entity,'public pipeline admits supported control');
        like($product->{hdl_code},$port,'public pipeline preserves independent declaration');
        if ($i == 1) {
            like($text,qr/OUT_LANES\s+<=\s+"10101";/,'existing packed-output constant keeps exact literal');
        }
    };
}

subtest 'refusal oracle rejects false success and stack-only expected text' => sub {
    for my $row (@observed) {
        my ($native,$reason)=@$row;
        ok(refused($native,$reason),'actual selected negative calibrates oracle');
        ok(!refused({%$native,exit_code=>0},$reason),'zero exit never qualifies refusal');
        ok(!refused({%$native,signal=>9},$reason),'signal failure never qualifies profile refusal');
        ok(!refused({%$native,stderr=>"Error generating HDL: unrelated failure\n\t".primary_diagnostic($native->{stderr})},$reason),
            'expected reason only in later stack text never qualifies');
        ok(!refused({%$native,stderr=>''},$reason),'missing diagnostic never qualifies');
    }
};

is_deeply({map {$_ => sha256_hex(read_file($_))} @paths},$before,
    'complete selected sources and named producer bytes remain unchanged');
done_testing;

sub composition_reason {
    my ($top)=@_;
    return qr/^Composition source '\?top:\Q$top\E' .*Target language 'vhdl' is not implemented for this composition shape yet: generated-child composition VHDL is outside the bounded C2 scalar-autowire\/scalar-bitstring-one-bit-aggregate-generic and APB\/C4 generated-FSM structural-top leaves\. See docs\/COMPOSITION_SCOPE\.md and docs\/COMPOSITION_LEGACY_MAPPING\.md\.\z/;
}
sub primary_diagnostic {
    my ($error)=@_;
    my @lines=split /\n/,$error;
    shift @lines if @lines && $lines[0] =~ /^Source file: /;
    return $lines[0] // '';
}
sub refused { my($result,$reason)=@_; return $result->{exit_code} == 1 && $result->{signal} == 0
    && primary_diagnostic($result->{stderr}) =~ $reason ? 1 : 0; }
sub capture { FSM::Test::SourceQueryRunner::_capture($_[0],''); }
sub read_file {open my $fh,'<:raw',$_[0] or die $!;local $/;my $s=<$fh>;close $fh or die $!;return $s;}
sub write_file {open my $fh,'>:raw',$_[0] or die $!;print {$fh} $_[1] or die $!;close $fh or die $!;}

use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use Digest::SHA qw(sha256_hex);
use File::Temp qw(tempdir);
use JSON::PP;
use FSM::Test::ProjectDataLocality;
use FSM::Test::SourceQueryRunner;
use FSM::Pipeline::HDLGenerator;

my $work = tempdir(CLEANUP => 1);
my $json = JSON::PP->new->canonical;
write_file("$work/shared.fsm", '(?pkg:shared (+types (type frame (record (flag bit) (data (bits 3))))))');
write_file("$work/imported.isf", '(actor imported_record_profile (imports (package shared)) (types (type alias shared.frame)) (clock clk) (interface (input start) (input packet (type alias)) (output done)) (transaction main (on start) (complete done)))');
write_file("$work/unused.isf", '(actor unused_record_profile (clock clk) (types (type frame (record (flag bit) (data (bits 3))))) (interface (input start) (input packet (type frame)) (output done)) (transaction main (on start) (complete done)))');
my @cases = (
    ["$work/imported.isf", 'imported_record_profile', 'packet', 'alias'],
    ["$work/unused.isf", 'unused_record_profile', 'packet', 'frame'],
    ['t/data/isf_record_input_runtime.isf', 'packed_input_runtime', 'packet', 'frame', 'direct'],
    ['t/data/isf_record_input_generated_domains_runtime.isf', 'packed_input_generated_domains', 'packet', 'frame', 'domains'],
    ['t/data/isf_record_input_generated_blocking_runtime.isf', 'packed_input_generated_blocking', 'packet', 'frame', 'blocking'],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port.isf', 'link_rx', 'lmp_in', 'lmp_t'],
    ['docs/audits/specforge-aggregate-intake-20260930/record-port-field-guard.isf', 'link_rx', 'lmp_in', 'lmp_t'],
);
my @sources = ("$work/shared.fsm", map {$_->[0]} @cases);
push @sources, qw(bin/fsmgen perl/FSM/Pipeline/HDLGenerator.pm
    perl/FSM/Adapter/ISF/Parser.pm perl/FSM/Scheduler/ISF/LoweringIR.pm
    perl/FSM/Support/ISFHDLProfile.pm perl/FSM/Support/ISFInterfacePortMetadata.pm
    t/data/isf_record_input_runtime_tb.sv
    t/data/isf_record_input_generated_runtime_tb.sv);
my $before = {map {$_ => sha256_hex(read_file($_))} @sources};
my @observed;

for my $index (0..$#cases) {
    my ($source,$actor,$port,$type,$old_name)=@{$cases[$index]};
    my $reason = "ISF actor '$actor' record input '$port' (type '$type') cannot generate target 'verilog': packed record inputs require SystemVerilog; use --language systemverilog. Verilog-2005 record lowering is not implemented.";
    subtest "precise record-input Verilog boundary for $source" => sub {
        for my $target (qw(verilog v)) {
            my $output = "$work/refused_${index}_$target.v";
            write_file($output,"EXISTING DESTINATION\n");
            my $native = capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
            ok(refused($native,$reason),'normal native failure names authored actor, record port, type and supported alternative')
                or diag($native->{stdout},$native->{stderr});
            is(read_file($output),"EXISTING DESTINATION\n",'existing output is byte-exact');
            push @observed,[$native,$reason];
            unlink $output or die $!;
            my $absent = capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
            ok(refused($absent,$reason),'absent output has the same precise normal refusal') or diag($absent->{stderr});
            ok(!-e $output,'no new destination is published');
            my ($product,$error);
            eval {$product=FSM::Pipeline::HDLGenerator->new(target_language=>$target,quiet=>1,strict_mode=>1)
                ->generate_hdl_from_file($source);1} or $error=$@;
            ok(!defined($product),'facade publishes no partial successful product');
            like($error // '',qr/^\Q$reason\E(?: at |\n|$)/,'facade retains the same primary contextual reason');
        }
        for my $kind (['check', qw(--check --json)], ['semantic', '--emit-semantic-json']) {
            my ($name,@flags)=@$kind;
            my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','verilog',@flags,$source]);
            is($native->{exit_code},1,"$name profile failure has normal status");
            is($native->{signal},0,"$name profile failure has no signal");
            is($native->{stderr},'',"$name machine report owns the diagnostic");
            my $report=$json->decode($native->{stdout});
            is($json->encode($report->{success}),'false',"$name exact JSON failure kind");
            is($report->{diagnostics}[0]{message},$reason,"$name precise stable message contains no implementation stack");
            ok(exists($report->{diagnostics}[0]{code}),"$name nullable diagnostic code is retained");
            ok(!exists($report->{source}{interface_ports}),"$name publishes no successful declaration snapshot");
            ok(!defined($report->{semantic}),"$name publishes no partial semantic product");
        }
        my $schedule = capture([$^X,'bin/fsmgen','--strict','--quiet','--language','verilog','--emit-schedule-json',$source]);
        is($schedule->{exit_code},0,'target-neutral schedule preview remains available');
        ok($json->decode($schedule->{stdout})->{interface_ports},'preview retains declared interface metadata');
        if (defined $old_name) {
            my $output = "$work/supported_$index.sv";
            my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language','systemverilog','--output',$output,$source]);
            is($native->{exit_code},0,'SystemVerilog source generation remains supported') or diag($native->{stderr});
            is(normalize_date(read_file($output)),normalize_date(read_file("docs/audits/record-input-language-profile-20261001/${old_name}_systemverilog.hdl.source")),
                'complete SystemVerilog HDL equals committed predecessor except dated banners');
        }
    };
}

subtest 'scalar Verilog and SystemVerilog storage controls remain supported' => sub {
    for my $case (
        ['docs/audits/specforge-aggregate-intake-20260930/baseline-good.isf','verilog','link_rx'],
        ['isf/storage_fields.isf','systemverilog','storage_fields'],
    ) {
        my ($source,$target,$module)=@$case;
        my $output="$work/control_$target.sv";
        my $native=capture([$^X,'bin/fsmgen','--strict','--quiet','--language',$target,'--output',$output,$source]);
        is($native->{exit_code},0,'unchanged supported control generates HDL') or diag($native->{stderr});
        like(read_file($output),qr/\bmodule \Q$module\E\b/,'independently named module remains');
    }
};

subtest 'refusal oracle rejects false success, signal and secondary diagnostic' => sub {
    for my $row (@observed) {
        my ($native,$reason)=@$row;
        ok(!refused({%$native,exit_code=>0},$reason),'successful emission cannot qualify a refusal');
        ok(!refused({%$native,signal=>9},$reason),'signal failure cannot qualify a profile refusal');
        ok(!refused({%$native,stderr=>"Error generating HDL: unrelated failure\n$reason\n"},$reason),
            'later expected text cannot replace primary diagnostic');
        ok(!refused({%$native,stderr=>''},$reason),'missing diagnostic cannot qualify');
    }
};
is_deeply({map {$_ => sha256_hex(read_file($_))} @sources},$before,'source, bench and named producer bytes remain unchanged during qualification');
done_testing;

sub refused {
    my ($result,$reason)=@_;
    my $first=(split /\n/,$result->{stderr})[0] // '';
    return $result->{exit_code}==1 && $result->{signal}==0
        && $first =~ /^(?:Error generating HDL: )?\Q$reason\E(?: at |$)/ ? 1 : 0;
}
sub normalize_date {my ($text)=@_;$text =~ s{^// Date:[^\n]*$}{// Date: omitted}mg;return $text;}
sub capture { FSM::Test::SourceQueryRunner::_capture($_[0],''); }
sub read_file {open my $fh,'<:raw',$_[0] or die $!;local $/;my $s=<$fh>;close $fh or die $!;return $s;}
sub write_file {open my $fh,'>:raw',$_[0] or die $!;print {$fh} $_[1] or die $!;close $fh or die $!;}

